/* formulário curto em janela própria (no lugar das janelinhas do navegador): resolve com os valores ou null */
function formulario(titulo,campos,ok){return new Promise(res=>{const ov=document.createElement('div'); ov.className='ov';
  ov.innerHTML=`<form class="sh grid" style="max-width:480px"><div class="sec" style="font-size:20px;margin:0">${esc(titulo)}</div>${campos.map((c,i)=>`<label class="f">${esc(c.l)}<input name="${c.k}" type="${c.type||'text'}"${c.mode?` inputmode="${c.mode}"`:''} value="${esc(c.val||'')}" placeholder="${esc(c.ph||'')}"${c.req?' required':''}${i?'':' autofocus'}></label>`).join('')}
   <div class="row" style="justify-content:flex-end;margin-top:6px"><button type="button" class="btn ghost" data-fx>Cancelar</button><button class="btn">${esc(ok||'OK')}</button></div></form>`;
  document.body.appendChild(ov); const f=ov.querySelector('form'); const fim=v=>{ov.remove(); res(v)}; setTimeout(()=>{const i=f.querySelector('input'); i&&i.focus()},50);
  ov.onclick=e=>{if(e.target===ov||e.target.closest('[data-fx]')) fim(null)}; f.onsubmit=e=>{e.preventDefault(); const v={}; campos.forEach(c=>v[c.k]=f.elements[c.k].value.trim()); fim(v)}})}
function sairDaConta(){if(confirm('Sair da conta?')){sess=null;S('sess',null);try{['chamae_tp','mdx_k','cca_k'].forEach(k=>localStorage.removeItem(k))}catch(e){} showLock()}}
function menuUsuario(e){if(e) e.stopPropagation(); const old=$('#umenu'); if(old) return old.remove(); const d=document.createElement('div'); d.id='umenu'; d.className='umenu';
  d.innerHTML=`<div class="hint" style="padding:6px 10px">${esc(sess&&sess.email||'')}</div><button data-um="aj">⚙️ Meus dados e ajustes</button><button data-um="ajuda">❓ Ajuda e tutoriais</button><button data-um="sair">🚪 Sair da conta</button>`;
  document.body.appendChild(d); const fecha=ev=>{if(!d.contains(ev.target)){d.remove(); document.removeEventListener('click',fecha,true)}}; setTimeout(()=>document.addEventListener('click',fecha,true),0);
  d.onclick=ev=>{const b=ev.target.closest('[data-um]'); if(!b) return; d.remove(); document.removeEventListener('click',fecha,true); const k=b.dataset.um; if(k==='sair') return sairDaConta(); go(k)}}

/* ---------- dados ---------- */
let REPS=null; const CAT={}, TABS={}, PRICES={};
/* cache rápido no aparelho (IndexedDB): mostra o que já tem na hora e atualiza por trás */
const kv={_d:null,open(){return this._d||(this._d=new Promise((res,rej)=>{try{const r=indexedDB.open('chamae',1); r.onupgradeneeded=()=>r.result.createObjectStore('kv'); r.onsuccess=()=>res(r.result); r.onerror=()=>rej(r.error)}catch(e){rej(e)}}))},
  async get(k){try{const d=await this.open(); return await new Promise(res=>{const t=d.transaction('kv').objectStore('kv').get(k); t.onsuccess=()=>res(t.result); t.onerror=()=>res(undefined)})}catch(e){return undefined}},
  async set(k,v){try{const d=await this.open(); d.transaction('kv','readwrite').objectStore('kv').put(v,k)}catch(e){}}};
const STALE=new Set(), BG={};
const SWRP={}; /* mesma chave pedida duas vezes ao mesmo tempo: espera a primeira */
function swr(key,mem,mk,fetcher,force){if(!force&&!STALE.has(key)&&mem[mk]!==undefined) return Promise.resolve(mem[mk]); if(!force&&SWRP[key]) return SWRP[key]; return SWRP[key]=swr0(key,mem,mk,fetcher,force).finally(()=>{delete SWRP[key]})}
async function swr0(key,mem,mk,fetcher,force){if(STALE.has(key)){force=true; STALE.delete(key)} if(mem[mk]!==undefined&&!force) return mem[mk];
  if(!force){const c=await kv.get(key); if(c!==undefined){mem[mk]=c; if(!BG[key]){BG[key]=1; fetcher().then(v=>{mem[mk]=v; kv.set(key,v)}).catch(()=>{})} return c}}
  const v=await fetcher(); mem[mk]=v; kv.set(key,v); BG[key]=1; return v}
const CNTP={t:0,n:{}}; /* contagem de produtos por representada (guardada 10 min) */
async function reps(force){if(REPS&&!force) return REPS; const M={}; REPS=await swr('reps',M,'r',async()=>{const R=await api('representadas?select=*&order=ordem'); /* só a contagem de produtos de cada uma, todas de uma vez (antes baixava os 7 mil produtos só para contar) */ const fr=CNTP.t&&Date.now()-CNTP.t<6e5&&!STALE.has('cntp'); await Promise.all(R.map(async r=>{r.n=fr&&CNTP.n[r.id]!=null?CNTP.n[r.id]:await contar(`produtos?select=id&rep=eq.${encodeURIComponent(r.id)}&ativo=eq.true`).catch(()=>0); CNTP.n[r.id]=r.n})); if(!fr) CNTP.t=Date.now(); return R},force); return REPS}
async function catalog(rep,force){return swr('cat_'+rep,CAT,rep,()=>apiAll(`produtos?select=*&rep=eq.${rep}&ativo=eq.true&order=cod`),force)}
async function tabelas(rep,force){return swr('tab_'+rep,TABS,rep,()=>api(`tabelas?select=*&rep=eq.${rep}&ativa=eq.true&order=nome`),force)}
async function prices(tid,force){if(!tid) return {}; return swr('pr_'+tid,PRICES,tid,async()=>{const rows=await apiAll(`precos?select=produto_id,nivel,preco&tabela_id=eq.${tid}`); const m={}; rows.forEach(r=>{(m[r.produto_id]=m[r.produto_id]||{})[r.nivel]=+r.preco}); return m},force)}
/* ---------- campanhas de produtos (qualquer representada): preço fixo ou % sobre a tabela, quantidade mínima opcional ---------- */
const CAMPS={};
async function campanhas(rep,force){if(!rep) return []; return swr('camp_'+rep,CAMPS,rep,()=>api(`campanhas?select=*&rep=eq.${rep}&order=fim.asc.nullslast,nome`).catch(()=>[]),force)}
const hojeISO=()=>new Date().toLocaleDateString('sv-SE');
const campVigente=c=>{const h=hojeISO(); return c.ativa&&(!c.inicio||c.inicio<=h)&&(!c.fim||c.fim>=h)};
const campSit=c=>!c.ativa?'pausada':c.fim&&c.fim<hojeISO()?'encerrada':c.inicio&&c.inicio>hojeISO()?'agendada':'vigente';
/* melhor campanha vigente do produto nesta tabela; ok=false quando a quantidade ainda não chegou ao mínimo; só vale se ficar abaixo do preço normal (base) */
function campDe(rep,p,tabela,base,qt){const k=norm(p.cod||'').trim(), kr=norm(p.ref||'').trim(); if(!k) return null; let best=null;
  for(const c of (CAMPS[rep]||[])){if(!campVigente(c)||(c.tabelas&&c.tabelas.length&&!c.tabelas.map(String).includes(String(tabela)))) continue; const its=c.itens||[];
    let it=its.find(x=>{const xc=norm(x.cod||'').trim(); return xc===k||(kr&&xc===kr)}); if(!it&&!its.length&&c.desc_geral!=null) it={}; if(!it) continue;
    const temP=it.preco!=null&&it.preco!=='', d=it.desc!=null&&it.desc!==''?+it.desc:(!temP&&c.desc_geral!=null?+c.desc_geral:null);
    const pu=temP?+it.preco:d!=null&&base?rHU(base*(1-d/100)):0; if(!pu||(base&&pu>=base-0.004)) continue;
    const min=+it.min||0; const x={id:c.id,nome:c.nome,fim:c.fim,pu,de:base,desc:d,min,ok:qt==null||qt>=min}; if(!best||(x.ok&&!best.ok)||(x.ok===best.ok&&x.pu<best.pu)) best=x}
  return best}
const CAMP_ST='background:#ff6a3d26;color:#ff8a5c;font-weight:700';
const campTxt=c=>`🔥 ${c.nome}${c.fim?' · até '+dbr(c.fim):''}${c.min>1?' · a partir de '+c.min+' un.':''}`;
let CLIS=null, CLITAB=null; const CLIM={};
async function clientes(force){if(CLIS&&!force) return CLIS; CLIS=await swr('clis4',CLIM,'c',async()=>{const m={};
    const add=(k,o)=>{k=String(k||'').replace(/\D/g,'')||k; if(!k) return; const c=m[k]=m[k]||{cnpj:k,n:'',fa:'',cid:'',reps:{}}; for(const f in o) if(o[f]&&!c[f]) c[f]=o[f]; return c};
    try{const r=await apiAll('clientes?select=cnpj,razao,fantasia,endereco,bairro,cidade,uf,cep,telefone,email,vendedor,segmento,reprio'); CLITAB=true; r.forEach(x=>{const rp=x.reprio||{}; add(x.cnpj,{n:x.razao||rp.razao,fa:x.fantasia||rp.fantasia,end:x.endereco||rp.endereco,bai:x.bairro||rp.bairro,cep:x.cep||rp.cep,seg:x.segmento,cid:(x.cidade||rp.cidade||'')+((x.uf||rp.uf)?'/'+(x.uf||rp.uf):''),tel:x.telefone||rp.telefone,em:x.email||rp.email,v:vAt(x.vendedor||rp.vendedor),cad:true})})}catch(e){CLITAB=false}
    try{const r=await apiAll('cliente_rep?select=cnpj,cliente,cidade,representada,ultimo,ultimo_prazo,vendedor'); vAtL(r).forEach(x=>{const c=add(x.cnpj,{n:x.cliente,cid:x.cidade,v:x.vendedor}); if(c) c.reps[x.representada]=x})}catch(e){}
    if(Object.keys(m).length<300){try{const d=await lerApp('marluvas'); (d.CLI||[]).forEach(x=>add(x.cnpj,{n:x.n,fa:x.fa,cid:x.cid,em:x.em,tel:x.tel,v:x.v,t:x.t,pz:x.pz}))}catch(e){}}
    /* CNPJ errado (planilha antiga) com o mesmo nome de um cliente de CNPJ certo: junta no certo, para não aparecer cliente repetido sem dados */
    const nk=x=>norm(x).replace(/\b(LTDA|ME|EPP|EIRELI|S\/?A)\b/g,'').replace(/[^A-Z0-9]/g,''); const bons=Object.values(m).filter(c=>c.n&&cnpjOk(c.cnpj));
    Object.values(m).forEach(c=>{if(!c.n||cnpjOk(c.cnpj)||c.cad) return; const a=cnpjGemeo(c,bons,nk); if(!a) return; (a.alias=a.alias||[]).push(c.cnpj); for(const r in c.reps){const x=c.reps[r], y=a.reps[r]; if(!y||String(x.ultimo||'')>String(y.ultimo||'')) a.reps[r]=Object.assign({},y,x,{cnpj:a.cnpj})} for(const f in c) if(c[f]&&!a[f]&&f!=='alias') a[f]=c[f]; delete m[c.cnpj]});
    return Object.values(m).filter(c=>c.n).sort((a,b)=>String(a.n).localeCompare(String(b.n)))},force);
  const ex=new Set((await cexcLista()).filter(x=>x.status==='aprovado').map(x=>x.cnpj)); if(ex.size) CLIS=CLIS.filter(c=>!ex.has(c.cnpj)); return CLIS}
/* ---------- exclusão de cliente: vendedor pede com motivo, gestor exclui ou recusa (tabela cliente_exclusao) ----------
   "Excluído" = some das listas (Clientes, carteira, busca do orçamento). Pedidos/orçamentos/relatórios ficam. Gestor pode restaurar. */
let CEXC=null;
async function cexcLista(force){if(CEXC&&!force) return CEXC; try{CEXC=await api('cliente_exclusao?select=*&status=in.(pendente,aprovado)&order=pedido_em.desc')}catch(e){CEXC=[]} return CEXC}
function cexcRecarregar(){CEXC=null; CLIS=null}
const cexcPend=()=>(CEXC||[]).filter(x=>x.status==='pendente');
const dtBR=d=>d?new Date(d).toLocaleDateString('pt-BR'):'';
/* janela para escrever o motivo (obrigatório). Gestor exclui na hora; vendedor só pede. */
function cexcPedir(cnpj,nome){return new Promise(res=>{const g=ehGestor(); const ov=document.createElement('div'); ov.className='ov'; ov.innerHTML=`<div class="sh grid"><b style="font-size:18px">${g?'Excluir cliente':'Pedir exclusão do cliente'}</b><div><b>${esc(nome||'')}</b><div class="hint">${esc(fmtCnpj(cnpj))}</div></div>
   <p class="hint" style="margin:0">${g?'O cliente some das listas do Sistema (Clientes, carteira e busca do orçamento). Pedidos, orçamentos e relatórios continuam. Dá para restaurar depois em Clientes › Pedidos de exclusão.':'O gestor vai ver o seu pedido e decidir se exclui ou não. Até lá o cliente continua normal.'}</p>
   <label class="f">Motivo (obrigatório)<textarea id="cxm" rows="3" placeholder="Ex.: empresa fechou · CNPJ duplicado · não é cliente nosso · cadastro de teste"></textarea></label>
   <div class="row" style="gap:6px">${['Empresa fechou','Cadastro duplicado','Não é nosso cliente','Cadastro de teste'].map(x=>`<button class="chip" data-cxs="${x}">${x}</button>`).join('')}</div>
   <div class="row"><button class="btn" id="cxok"${g?' style="background:var(--bad)"':''}>${g?'Excluir cliente':'Enviar pedido ao gestor'}</button><button class="btn ghost" data-x>Cancelar</button></div></div>`; document.body.appendChild(ov);
  const fim=v=>{ov.remove(); res(v)};
  ov.onclick=async e=>{const t=e.target; if(t===ov||t.closest('[data-x]')) return fim(false); const sg=t.closest('[data-cxs]'); if(sg){const a=$('#cxm'); a.value=a.value.trim()?a.value.trim()+' · '+sg.dataset.cxs:sg.dataset.cxs; return a.focus()}
    if(t.id==='cxok'){const mot=$('#cxm').value.trim(); if(mot.length<5) return toast('Escreva o motivo (pelo menos 5 letras)'); t.disabled=true;
      const body={cnpj,cliente:nome||null,motivo:mot,pedido_por:meuNome()||null}; if(g) Object.assign(body,{status:'aprovado',decidido_por:meuNome()||null,decidido_em:new Date().toISOString()});
      try{await api('cliente_exclusao',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify(body)}); cexcRecarregar(); toast(g?'Cliente excluído':'Pedido enviado ao gestor'); fim(true)}catch(err){t.disabled=false; toast(/duplicate|unique|23505/.test(err.message)?'Já existe um pedido de exclusão aberto para este cliente':'Erro: '+err.message)}}}})}
/* gestor decide: aprovar (excluir), recusar ou restaurar */
async function cexcDecidir(id,status,resposta){await api(`cliente_exclusao?id=eq.${id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({status,decidido_por:meuNome()||null,decidido_em:new Date().toISOString(),resposta:resposta||null})}); cexcRecarregar()}
/* lista de pedidos para o gestor (e "Excluídos" para restaurar) */
async function cexcPainel(aba){aba=aba||'p'; let L=[]; try{L=await api(aba==='p'?'cliente_exclusao?select=*&status=eq.pendente&order=pedido_em':aba==='e'?'cliente_exclusao?select=*&status=eq.aprovado&order=decidido_em.desc':'cliente_exclusao?select=*&status=in.(recusado,cancelado,restaurado)&order=pedido_em.desc&limit=50')}catch(e){return toast('Erro: '+e.message)}
  document.querySelectorAll('.ov[data-cexc]').forEach(x=>x.remove()); const ov=document.createElement('div'); ov.className='ov'; ov.dataset.cexc=1; const g=ehGestor();
  const card=x=>`<div class="card grid" style="margin:0;gap:6px"><div class="row" style="justify-content:space-between"><b>${esc(x.cliente||x.cnpj)}</b><span class="tag${x.status==='pendente'?' warn':x.status==='aprovado'?' bad':''}">${{pendente:'aguardando',aprovado:'excluído',recusado:'recusado',cancelado:'cancelado',restaurado:'restaurado'}[x.status]||esc(x.status)}</span></div>
     <div class="hint">${esc(fmtCnpj(x.cnpj))} · pedido por <b>${esc(x.pedido_por||'—')}</b> em ${dtBR(x.pedido_em)}${x.decidido_por?` · decidido por ${esc(x.decidido_por)} em ${dtBR(x.decidido_em)}`:''}</div>
     <div style="background:var(--surface2);border-radius:8px;padding:8px"><small class="hint">Motivo</small><div>${esc(x.motivo)}</div>${x.resposta?`<small class="hint">Resposta do gestor</small><div>${esc(x.resposta)}</div>`:''}</div>
     <div class="row"><button class="chip" data-cxf="${esc(x.cnpj)}">Abrir ficha ›</button>${g&&x.status==='pendente'?`<button class="btn sm" style="background:var(--bad)" data-cxa="${x.id}">🗑 Excluir</button><button class="btn sm ghost" data-cxr="${x.id}">Não excluir</button>`:''}${g&&x.status==='aprovado'?`<button class="btn sm ghost" data-cxv="${x.id}">↺ Restaurar cliente</button>`:''}</div></div>`;
  ov.innerHTML=`<div class="sh grid" style="max-width:720px"><div class="row" style="justify-content:space-between"><b style="font-size:18px">🗑 Pedidos de exclusão de cliente</b><button class="chip" data-x>✕</button></div>
   <div class="row">${[['p','Aguardando'],['e','Excluídos'],['h','Histórico']].map(([k,l])=>`<button class="chip${k===aba?' on':''}" data-cxt="${k}">${l}</button>`).join('')}</div>
   ${L.map(card).join('')||`<p class="hint">${aba==='p'?'Nenhum pedido aguardando.':aba==='e'?'Nenhum cliente excluído.':'Nada por aqui ainda.'}</p>`}</div>`; document.body.appendChild(ov);
  ov.onclick=async e=>{const t=e.target; if(t===ov||t.closest('[data-x]')) return ov.remove(); const tb=t.closest('[data-cxt]'); if(tb) return cexcPainel(tb.dataset.cxt);
    const f=t.closest('[data-cxf]'); if(f){ov.remove(); return go('cli',{cnpj:f.dataset.cxf})}
    const a=t.closest('[data-cxa]'), r=t.closest('[data-cxr]'), v=t.closest('[data-cxv]'); const id=(a||r||v||{}).dataset; if(!id) return; const x=L.find(y=>String(y.id)===(id.cxa||id.cxr||id.cxv));
    try{if(a){if(!confirm(`Excluir ${x.cliente||x.cnpj}?\n\nEle some das listas do Sistema. Pedidos e relatórios continuam, e dá para restaurar depois.`)) return; await cexcDecidir(x.id,'aprovado'); toast('Cliente excluído')}
      else if(r){const resp=prompt('Por que não excluir? (opcional, o vendedor vai ver na ficha do cliente)',''); if(resp===null) return; await cexcDecidir(x.id,'recusado',resp.trim()); toast('Pedido recusado')}
      else if(v){if(!confirm(`Restaurar ${x.cliente||x.cnpj}? Ele volta a aparecer nas listas.`)) return; await cexcDecidir(x.id,'restaurado'); toast('Cliente restaurado')}
      cexcPainel(aba); if(route==='cli') clientesView(); if(route==='home') home()}catch(err){toast('Erro: '+err.message)}}}
const repName=id=>((REPS||[]).find(r=>r.id===id)||{}).nome||HIST_REP[id]||id;
const HIST_REP={marcon:'Marcon',marluvas:'Marluvas',medix:'Medix',sigma:'Sigma Tools',camper:'Camper',zm:'ZM Bombas',terra:'Terra',fortlev:'Fortlev',pegorari:'Pegorari',valcan:'Valcan',cid:'CID',chemicals:'Chemicals 4U'};
/* transportadoras padrão (usadas enquanto a representada não tem lista própria em Representadas > Transportadoras e frete) */
const TRANSP={marcon:[{nome:'',tipo:'Cliente retira',p:0},{nome:'Alfa Transportes',tipo:'FOB',p:5},{nome:'Transportadora Floresta',tipo:'FOB',p:5},{nome:'Transportadora a ser indicada',tipo:'FOB',p:0}]};
const FR_TIPOS=['CIF','FOB','FOB dirigido','Cliente retira','Redespacho','A combinar'];
const trTxt=x=>x?[x.tipo,x.nome].filter(Boolean).join(' · ')||String(x.n||'').replace(/\s*\(~[\d,.]+%\)$/,''):''; /* sem o % estimado: é o que vai para o cliente */
/* frete escolhido num orçamento salvo (dados): cópia gravada ou, nos antigos, pelo índice na lista da representada */
const trDe=(d,rep)=>d&&d.trs&&(d.trs.tipo||d.trs.nome||d.trs.n)?d.trs:d&&d.transp!=null&&d.transp!==''?transpDe(rep)[+d.transp]||null:null;
const trLbl=x=>{const a=[x.tipo,x.nome].filter(Boolean).join(' · ')||'—'; return +x.p?`${a} (~${String(+x.p).replace('.',',')}%)`:a};
/* lista de transportadoras/frete da representada: [{nome,tipo,p,padrao}] → opções do orçamento {n,p,tipo,nome,padrao} */
const transpCad=rep=>{const r=(REPS||[]).find(x=>x.id===rep)||{}; const L=(r.regras||{}).transp; return Array.isArray(L)?L:(TRANSP[rep]||[])};
const transpDe=rep=>transpCad(rep).map(x=>({...x,n:trLbl(x),p:+x.p||0}));
const EXTERNAL={marluvas:'/conversor-ca/teste/',medix:'/medix-luvas/teste/'};
/* Chama Solar: cartão em Fábricas só para quem tem acesso ao módulo solar (tabela sol_usuarios) */
const SOLAR_URL='../solar-teste/'; let SOLAR_ON=null;
async function preencherSolar(){if(SOLAR_ON===null){try{SOLAR_ON=!!(await api('rpc/eh_solar',{method:'POST',body:'{}'}))}catch(e){SOLAR_ON=false}} const el=document.getElementById('solarSlot'); if(!SOLAR_ON||!el) return;
  el.outerHTML=`<button class="rep" data-solar style="--c:#ff6700"><span class="row" style="gap:8px;flex-wrap:nowrap"><img src="${SOLAR_URL}marca/logo-cor.webp" alt="" width="30" height="30" style="width:30px;height:30px;border-radius:50%;object-fit:contain;background:#fff;padding:3px"><b>Chama Solar</b></span><small>Orçamento solar · Proposta Viva</small><span id="solarSino" hidden style="position:absolute;top:8px;right:10px;min-width:22px;height:22px;padding:0 6px;border-radius:11px;background:#ff3b30;color:#fff;font:700 12px/22px system-ui;text-align:center;box-shadow:0 0 0 3px #ff3b3033">🔔</span></button>`;
  /* sino: lembretes de hoje, cliente que abriu/aceitou proposta (24 h) e lead novo do site (48 h) */
  try{const a=await api('rpc/sol_alertas',{method:'POST',body:'{}'}); const sn=document.getElementById('solarSino'); if(sn&&a&&a.total>0){sn.hidden=false; sn.textContent='🔔 '+a.total; sn.title=[a.lembretes?a.lembretes+' lembrete(s) para hoje':'',a.eventos?a.eventos+' cliente(s) mexeram na proposta':'',a.leads?a.leads+' lead(s) novo(s)':''].filter(Boolean).join(' · '); const bt=sn.closest('button'); if(bt) bt.style.position='relative'}}catch(e){}}
/* CHAVE LIGA/DESLIGA (01/11): true = Marluvas e Medix funcionam como as outras pastas (catálogo → orçamento do Sistema) e o conversor abre só para buscar o CA e mandar o item ao orçamento.
   false = volta ao jeito antigo (tocar na pasta abre o conversor inteiro). */
const CONV_PASTA=true;

/* ---------- apps Marluvas/Medix dentro do Sistema: mesmo login, volta ao início sem recarregar ---------- */
/* senha da equipe vem da base: conversores (app ou ⇄ Converter CA) abrem sem pedir senha */
async function garantirTp(){let tp=null; try{tp=localStorage.getItem('chamae_tp')}catch(_){} if(tp) return tp; try{const sg=await api('segredos?select=valor&chave=eq.senha_equipe'); if(sg[0]){localStorage.setItem('chamae_tp',sg[0].valor); return sg[0].valor}}catch(e){} return null}
/* Marluvas e Medix usam a tela dos conversores (grade, níveis, tabelas) dentro do Sistema; orc = orçamento da base para reabrir nele */
async function abrirApp(rep,orc){if(!EXTERNAL[rep]) return; let ov=document.getElementById('appOv-'+rep);
  if(ov&&orc){try{ov.querySelector('iframe').contentWindow.postMessage({t:'chamae-abrir-orc',id:orc},location.origin)}catch(e){}}
  if(ov){try{ov.querySelector('iframe').contentWindow.postMessage({t:'chamae-produtos'},location.origin)}catch(e){}} /* conversor já aberto: puxa de novo os produtos alterados aqui no Sistema */
  if(!ov) await garantirTp();
  if(!ov){ov=document.createElement('div'); ov.id='appOv-'+rep; ov.className='appov'; ov.style.cssText='position:fixed;inset:0;z-index:35;background:var(--bg);display:flex;flex-direction:column';
    ov.innerHTML=`<div style="display:flex;align-items:center;gap:10px;padding:calc(env(safe-area-inset-top,0px) + 6px) 12px 6px;background:#1c2340;color:#fff"><button class="btn sm" data-fechaapp>‹ Início</button><b style="font-family:var(--display);font-size:18px;text-transform:uppercase;letter-spacing:.03em">${esc(repName(rep))}</b></div><iframe title="${esc(repName(rep))}" src="${EXTERNAL[rep]}?inapp=1${orc?'&orc='+encodeURIComponent(orc):''}" style="flex:1;border:0;width:100%;background:#fff"></iframe>`;
    document.body.appendChild(ov)}
  document.querySelectorAll('.appov').forEach(o=>o.style.display='none'); ov.style.display='flex'; try{history.pushState({app:rep},'')}catch(e){}}
function fecharApp(){document.querySelectorAll('.appov').forEach(o=>o.style.display='none')}
const voltarInicio=()=>fecharApp(); /* sem history.back(): o histórico do app aberto dentro não pode ser desfeito por engano */
addEventListener('popstate',fecharApp);
const SUJO={}; /* conversor avisa quando o orçamento tem alterações não salvas */
const repDoFrame=w=>{const o=[...document.querySelectorAll('.appov')].find(x=>{const f=x.querySelector('iframe'); return f&&f.contentWindow===w}); return o?o.id.replace('appOv-',''):''};
addEventListener('message',e=>{if(e.origin!==location.origin||!e.data) return; if(e.data.t==='chamae-sujo'){const r=repDoFrame(e.source); if(r) SUJO[r]=!!e.data.v; return} if(e.data.t==='chamae-home') sairApp()});
function sairApp(){const ov=[...document.querySelectorAll('.appov')].find(o=>o.style.display!=='none'); const rep=ov?ov.id.replace('appOv-',''):'';
  if(rep&&SUJO[rep]&&confirm('O orçamento '+repName(rep)+' tem alterações não salvas.\n\nOK = salvar e sair\nCancelar = sair sem salvar (ele continua em andamento no '+repName(rep)+')')){try{ov.querySelector('iframe').contentWindow.postMessage({t:'chamae-salvar'},location.origin)}catch(e){}}
  voltarInicio()}
document.addEventListener('click',e=>{const a=e.target.closest('[data-app]'); if(a){e.preventDefault(); return abrirApp(a.dataset.app)} if(e.target.closest('[data-fechaapp]')) sairApp();});

/* ---------- orçamentos (um por representada) ---------- */
const MOVEL=/Android|iPhone|iPad|iPod/i.test(navigator.userAgent)||(navigator.maxTouchPoints>1&&/Mac/.test(navigator.platform));
const waDesk=()=>{try{return !!(navigator.canShare&&navigator.canShare({files:[new File(['%PDF'],'a.pdf',{type:'application/pdf'})]}))}catch(e){return false}};
const Q=()=>L('quotes')||{}; const setQ=q=>{LS('quotes',q); badge()};
const curQ=rep=>{const q=Q(); return q[rep]||(q[rep]={rep,itens:[],tabela:null,cli:null,prazo:'',obs:'',id:String(Date.now())})};
function saveQ(o){const q=Q(); q[o.rep]=o; setQ(q)}
function badge(){const n=Object.values(Q()).reduce((s,o)=>s+o.itens.length,0); const b=$('#qn'); if(!b) return; b.hidden=!n; b.textContent=n}

/* ---------- navegação ---------- */
let route='home', ctx={};
function go(r,c){if(r!==route) limparFiltros(route); route=r; ctx=c||{}; LS('route',r==='rep'?'home':r); navMarca(); window.scrollTo(0,0); const mm=$('#main'); mm.onclick=mm.onchange=mm.oninput=null; ({home,rep:repView,orc,admin,ped,rel,aj:ajustes,busca,cli:clientesView,reps:admReps,prod:prodView,tar:tarefasView,mais,equipe:equipeView,trans:paraTransmitir,metas:metasView,fin:finView,tec:tecView,estr:estrategiaView,ajuda:ajudaView,limites:limitesView}[r]||home)()}
$('#homeLnk').onclick=e=>{e.preventDefault(); go('home')}; {const ab=$('#ajudaBtn'); if(ab) ab.onclick=ajudaDaTela} $('#homeBtn').onclick=()=>go('home'); $('#srchBtn').onclick=()=>go('busca');
