  const rows=await linhasDe(o); const UP=o.cli&&o.cli.cnpj?await ultPagos(rep,o.cli.cnpj):null, UPr=r=>UP?ultHtml(ultPago(UP,r.p,o.id),r.pu,rep,true):''; const UPs=p0=>{const u=UP&&ultPago(UP,p0,o.id); return u?`<div class="oult">🕘 Pagou <b>${brl(u.pu)}</b> em ${dbr(u.d)}</div>`:''}; const tr=ehGurO(o,(TABS[rep]||[]).find(t=>t.id==o.tabela))?[{n:'CIF (por conta da Marcon)',p:0}]:transpDe(rep); const ti=o.transp!=null&&tr[o.transp]?+o.transp:tr.findIndex(x=>x.padrao), trS=tr[ti]||null; const sub=rows.reduce((s,r)=>s+r.tot,0), ipi=rows.reduce((s,r)=>s+r.ipiv,0), fr=trS?(sub+ipi)*trS.p/100:0; const AJ=ajPz(rep,o.prazo,sub,ipi), aj=AJ.aj, cpz=condPz(rep,o.prazo), pmin=minPz(rep,o.prazo); const tt={sub,ipi,fr,aj,lbl:AJ.lbl,trN:trS?trTxt(trS):o.transpN?'Transportadora: '+o.transpN:''};
