    {const pm2=t.closest('[data-om],[data-op]'); if(pm2){const it=o.itens.find(i=>i.pid==(pm2.dataset.om||pm2.dataset.op)); const pr=C.find(x=>x.id==(pm2.dataset.om||pm2.dataset.op))||{}; if(it&&GR[pr.cod]&&gradeTxt(it.gq)){toast('Este item tem grade: ajuste a quantidade na grade'); const r_=await editarGrade((pr.cod||'')+(pr.ref&&pr.ref!==pr.cod?' - '+pr.ref:''),GR[pr.cod],it.gq,pr.descricao); if(r_){it.gq=r_.gq; if(r_.tot) it.qt=r_.tot; saveQ(o)} return orc()}}}
