    if(e.target.closest('[data-oml]')){const d=o.dados||{}; return enviarEmail({cnpj:o.cnpj,cliente:o.cliente,assunto:`${DocNm(st)} ${repName(d.rep||o.app)}${d.num?' Nº '+d.num:''}${d.oc?' – O.C '+d.oc:''} – ${o.cliente||''}`,texto:`Prezado(a) cliente,\n\nSegue em anexo o ${docNm(st)} ${repName(d.rep||o.app)} no valor de ${brl(o.total)}.\n\nQualquer dúvida estou à disposição.\n\nAtenciosamente,\n${meuNome()}\nChamae Representações`,gerarPDF:async()=>{const C=await catalog(d.rep||o.app).catch(()=>[]); const rows=L2.map(l=>{const p=C.find(x=>norm(x.cod).trim()===norm(l.cod).trim())||{cod:l.cod,descricao:l.desc}; const pu=+l.pu||0; return {i:{qt:+l.qt,gq:l.gq},p:{...p,descricao:p.descricao||l.desc},pu,tot:pu*l.qt,ipiv:pu*l.qt*(+p.ipi||0)/100}}); const sub=rows.reduce((a,r)=>a+r.tot,0), ipi=rows.reduce((a,r)=>a+r.ipiv,0); return pdf({rep:d.rep||o.app,status:st,cli:d.cli||{n:o.cliente,cnpj:o.cnpj},num:d.num,prazo:d.prazo,obs:d.obs,oc:d.oc,vend:d.vend},rows,{sub,ipi,fr:0,mode:'blob'})},ref:{tipo:'orcamento',id:o.id,cnpj:o.cnpj}})}
