/* ---------- relatórios ---------- */
const RELS=[['painel','Painel do mês'],['conv','Conversão e positivação'],['perdas','Motivos de perda'],['mes','Vendas mensais'],['rep','Por representada'],['vend','Por vendedor'],['abcc','Curva ABC de clientes'],['abcp','Curva ABC de produtos'],['prod','Produtos vendidos × clientes'],['queda','Clientes em queda'],['recompra','Recompra atrasada'],['cross','Oportunidades entre representadas'],['nunca','Quem não comprou um produto']];
let PEDS=null, PEDS_EXPIRE=0; const CACHE_TTL=5*60*1000;
/* relatórios: usa o que já foi baixado (período maior serve para um menor), guarda no aparelho e atualiza por trás */
let PEDS_BG=null; const corta=(x,de)=>x.de===de?x.d:x.d.filter(p=>p.data>=de); const assin=d=>d.length+':'+Math.round(d.reduce((s,p)=>s+(+p.valor||0),0));
async function pedidosPeriodo(de){
  if(PEDS&&PEDS.de<=de&&Date.now()<PEDS_EXPIRE) return corta(PEDS,de);
  const busca=()=>apiAll(`pedidos?select=id,num,origem,cnpj,cliente,cidade,representada,data:data_ref,valor,vendedor&data_ref=gte.${de}&or=(status.is.null,status.eq.finalizado,status.like.APROVADO*)&order=data`).then(d=>{d=semDupLeg(vAtL(d)); PEDS={de,d}; PEDS_EXPIRE=Date.now()+CACHE_TTL; kv.set('peds3',{de,d,t:Date.now()}); return d});
  const c=await kv.get('peds3'); if(c&&c.de<=de&&Date.now()-c.t<12*3600e3){PEDS={de:c.de,d:c.d}; PEDS_EXPIRE=Date.now()+60e3; const a0=assin(corta(c,de));
    if(!PEDS_BG) PEDS_BG=busca().then(d=>{PEDS_BG=null; if(route==='rel'&&assin(d)!==a0) rel()}).catch(()=>{PEDS_BG=null}); return corta(c,de)}
  return busca()}
const MEMO={}; const memo=(k,ttl,fn)=>{const x=MEMO[k]; if(x&&Date.now()<x.t) return x.p; const p=fn().catch(e=>{delete MEMO[k]; throw e}); MEMO[k]={p,t:Date.now()+ttl}; return p};
