/* ---------- PDF ---------- */
function loadXLSX(){return window.XLSX?Promise.resolve():new Promise((ok,bad)=>{const s=document.createElement('script');s.src='xlsx.full.min.js';s.onload=ok;s.onerror=()=>bad(new Error('sem leitor de planilha'));document.head.appendChild(s)})}
function loadJsPDF(){return window.jspdf?Promise.resolve():new Promise((ok,bad)=>{const s=document.createElement('script');s.src='jspdf.umd.min.js';s.onload=ok;s.onerror=()=>bad(new Error('sem gerador de PDF'));document.head.appendChild(s)})}
async function imgData(url,maxW){if(!url) return null; try{let r=null; try{r=await fetch(url)}catch(e){} if((!r||!r.ok)&&/^https?:\/\//.test(url)) r=await fetch('https://images.weserv.nl/?url='+encodeURIComponent(url.replace(/^https?:\/\//,''))); if(!r||!r.ok) return null; const b=await r.blob(); const bm=await createImageBitmap(b); const sc=Math.min(1,maxW/bm.width); const c=document.createElement('canvas'); c.width=Math.round(bm.width*sc); c.height=Math.round(bm.height*sc); const x=c.getContext('2d'); x.fillStyle='#fff'; x.fillRect(0,0,c.width,c.height); x.drawImage(bm,0,0,c.width,c.height); return {d:c.toDataURL('image/jpeg',.85),w:c.width,h:c.height}}catch(e){return null}}


/* ---------- produtos e tabelas (gestor) ---------- */
const COLS={cod:['codigo','código','cod','sku','referencia'],desc:['descricao','descrição','descrição do produto','produto','nome'],un:['unidade','un','und','um'],mult:['qtd multiplo','multiplo','múltiplo','qtd múltiplo','multiplo venda','múltiplo venda','multiplo de venda','múltiplo de venda'],base:['tabela base','preco bruto','preço bruto','bruto'],liq:['preço de custo','preco de custo','preço','preco','valor','preço líquido','preco liquido'],ncm:['ncm'],ean:['código de barras','codigo de barras','ean','gtin'],ipi:['ipi (%)','ipi','% ipi','perc. ipi','perc ipi','percentual ipi','ipi %','aliquota ipi','alíquota ipi'],st:['st (%)','st'],icms:['icms (%)','icms'],obs:['observacoes','observações','obs'],prazo:['prazo entrega','prazo de entrega','lead time'],img:['imagem','foto','image','url imagem']};
const keyOf=h=>{const n=String(h||'').trim().toLowerCase(); for(const k in COLS) if(COLS[k].includes(n)) return k; return null};
const nameFromFile=f=>{const m=f.match(/reprio_(.+?)_(\w{2})_\d{4}/i); return m?(m[1].replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase())+' '+m[2].toUpperCase()):f.replace(/\.\w+$/,'')};
async function admin(){const m=$('#main'); if(!ehGestor()){m.innerHTML='<p class="hint">Só gestores.</p>';return} const R=await reps();
  const rep=ctx.rep||L('admRep')||'marcon'; if(ctx.tid) return tabPreco(rep,ctx.tid);
  m.innerHTML=`<div class="sec">Produtos e tabelas</div><div class="row"><select id="arep">${R.map(r=>`<option value="${r.id}"${r.id===rep?' selected':''}>${esc(r.nome)}</option>`).join('')}</select><button class="chip on" data-t="tp">Tabelas de preço</button><button class="chip" data-t="imp">Importar várias planilhas</button><button class="chip" data-t="ed">Editar produto</button><button class="chip" data-t="tb">Configurar tabelas</button>${rep==='marcon'?'<button class="chip" data-t="gur">Regra Gurgelmix</button>':''}${APPSRC[rep]?'<button class="chip" data-t="app">Trazer do app '+esc((R.find(r=>r.id===rep)||{}).nome||rep)+'</button>':''}</div><div id="adm" style="margin-top:12px"></div>`;
  $('#arep').onchange=e=>{LS('admRep',e.target.value); ctx={rep:e.target.value}; admin()};
  m.querySelector('.row').onclick=e=>{const b=e.target.closest('[data-t]'); if(!b) return; m.querySelectorAll('[data-t]').forEach(x=>x.classList.toggle('on',x===b)); ({tp:admTabelas,imp:admImp,ed:admEd,tb:admTab,app:admApp,gur:admGur})[b.dataset.t](rep)};
  admTabelas(rep)}
function admImp(rep){const a=$('#adm'); a.innerHTML=`<div class="card grid"><p class="hint">Suba uma ou várias planilhas (uma por tabela de preço). O nome da tabela vem do arquivo e pode ser ajustado. Nada é gravado antes da sua aprovação.</p>
  <input id="files" type="file" accept=".xlsx,.xls,.csv" multiple style="width:100%"><div id="prev"></div></div>`;
  $('#files').onchange=async e=>{const fs=[...e.target.files]; if(!fs.length) return; await loadXLSX(); const pv=$('#prev'); pv.innerHTML='<p class="hint">Lendo planilhas…</p>'; const C=await catalog(rep,true).catch(()=>[]); const T=await tabelas(rep,true);
    const jobs=[]; let porNiv=false; for(const f of fs){const {map,items,niv}=await lerPlanilha(f); if(Object.keys(niv).length>1){porNiv=true; jobs.push(...jobsPorNivel(f.name,map,items,niv,C,T)); continue} const nome=nameFromFile(f.name); const tab=T.find(t=>norm(t.nome)===norm(nome)); jobs.push({f:f.name,nome,map,items,tab})}
    if(porNiv) pv.insertAdjacentHTML('beforebegin','<p class="hint">Planilha única com preço por nível de comissão: cada coluna “Preço N%” vai para a tabela do nível N (confira o nome na prévia; trocar o nome cria uma tabela nova). Nível vazio na planilha usa o valor do nível vizinho. Produtos que não estão na planilha continuam nas tabelas; descrição e múltiplo dos produtos já cadastrados não mudam.</p>')
    if(rep==='marluvas'&&jobs.length===1){const j0=jobs[0]; if(!j0.tab){j0.nome='0 · Tabela geral SP'; j0.tab=T.find(t=>norm(t.nome)===norm(j0.nome))} const CN=[['REV60-318',3],['REV60-518',5],['REV79-717',7],['REV80-1016',10],['ECON-1115',11],['ECO12-1314',13],['HCEN-1012',10],['HCE600-1111',11],['HCE600-1211',12],['ATC500-109',10],['ATC2M-128',12],['DBI599-76',7],['DBI600-95',9],['DBI2M-114',11],['DBI5M-133',13]];
      CN.forEach(([n,d])=>jobs.push({...j0,nome:n,tab:T.find(t=>norm(t.nome)===norm(n)),items:j0.items.map(it=>({...it,liq:Math.round(it.liq*(1-d/100)*100)/100}))}));
      pv.insertAdjacentHTML('beforebegin','<p class="hint">Marluvas: a tabela geral gera automaticamente as 15 tabelas de canal (Revenda, E-commerce, Homecenter, Atacado e Distribuidor) com os descontos de cada canal.</p>')}
    if(rep==='marcon'){const msg=[]; aplicarGurgel(jobs,msg); msg.forEach(h=>pv.insertAdjacentHTML('beforebegin',h))}
    await prevJobs(rep,jobs,C,T,pv)}}
/* lê a 1ª aba da planilha: acha a linha de cabeçalho pela coluna de código; colunas que não vierem ficam vazias (e não apagam o que o produto já tem) */
/* .xls que na verdade é HTML (ex.: tabela da Medix): lê como texto, senão "18,70" vira 1870 */
async function lerPlanilha(f){const buf=await f.arrayBuffer(); const ini=new TextDecoder().decode(new Uint8Array(buf.slice(0,64))).replace(/^\uFEFF/,'').trimStart(); const wb=XLSX.read(buf,ini.startsWith('<')?{raw:true}:{}); const ws=wb.Sheets[wb.SheetNames[0]]; const rows=XLSX.utils.sheet_to_json(ws,{header:1,defval:''}); let hi=rows.findIndex(r=>r.some(c=>keyOf(c)==='cod')); if(hi<0) hi=0;
  const map={}, niv={}; (rows[hi]||[]).forEach((h,i)=>{const k=keyOf(h); if(k&&map[k]==null) map[k]=i; const m=!k&&String(h||'').trim().match(/^(?:pre[cç]o|n[ií]vel|comiss[aã]o)\s*(\d)\s*%?$/i); if(m&&niv[m[1]]==null) niv[m[1]]=i}); const items=rows.slice(hi+1).filter(r=>String(r[map.cod]??'').trim()).map(r=>{const g=k=>map[k]!=null?r[map[k]]:''; const num=v=>{if(typeof v==='number') return v; const s=String(v).replace(/[^\d,.-]/g,''); return s?+(s.includes(',')?s.replace(/\./g,'').replace(',','.'):s):null};
    return {cod:String(g('cod')).trim(),desc:String(g('desc')).trim(),un:String(g('un')).trim(),mult:num(g('mult')),base:num(g('base')),liq:num(g('liq')),ncm:String(g('ncm')).trim(),ean:String(g('ean')).trim(),ipi:num(g('ipi')),st:num(g('st')),icms:num(g('icms')),obs:String(g('obs')).trim(),prazo:String(g('prazo')).trim(),img:/^https?:\/\//i.test(String(g('img')).trim())?String(g('img')).trim():'',lv:Object.fromEntries(Object.entries(niv).map(([n,i])=>[n,num(r[i])]))}});
  return {map,items,niv}}
/* planilha única com colunas Preço 1% … Preço 5%: vira um job por nível, na tabela cujo nome tem o nº e "comissão" */
function jobsPorNivel(fn,map,items,niv,C,T){const ns=Object.keys(niv).sort(); const byCod={}; C.forEach(p=>byCod[p.cod]=p);
  const its=items.map(it=>{const v=ns.map(n=>it.lv[n]??null); const f=v.find(x=>x!=null); if(f==null) return null; let u=f; return {...it,desc:byCod[it.cod]?'':it.desc,ipi:null,v:v.map(x=>u=x!=null?x:u)}}).filter(Boolean);
  return ns.map((n,k)=>{const re=new RegExp(`(^|\\D)${n}(\\D|$)`); const tab=T.find(t=>/comiss/i.test(t.nome)&&re.test(t.nome)); return {f:`${fn} · ${n}%`,nome:tab?tab.nome:`Nível ${n} (comissão ${n}%)`,map:{...map,liq:niv[n]},items:its.map(it=>({...it,liq:it.v[k]})),tab,keepOld:true}})}
function aplicarGurgel(jobs,msg){jobs.forEach(j=>{const R=ehGurgel(j.nome)&&gurRegraDe(j.tab); if(!R) return; const M=gurCalc(R,j.items); let n=0; j.items.forEach(it=>{const x=M[gcod(it.cod)]; if(x&&Math.abs(x.v-(it.liq??0))>=.005){it.liq=x.v; n++}}); msg.push(`<p class="hint">${esc(j.nome)}: regra de preço Gurgelmix aplicada (${n} preços corrigidos em relação à planilha). Confira em “Regra Gurgelmix”.</p>`)})}
async function prevJobs(rep,jobs,C,T,pv,done){
    // prévia
    const byCod={}; C.forEach(p=>byCod[p.cod]=p);
    for(const j of jobs){const old=j.tab?await prices(j.tab.id,true):{}; let novos=0,sub=0,desc=0,igual=0; const ch=[]; j.items.forEach(it=>{const p=byCod[it.cod]; if(!p){novos++; return} const o=(old[p.id]||{}).liq; if(o==null){novos++; return} const d=it.liq-o; if(Math.abs(d)<.005) igual++; else {d>0?sub++:desc++; ch.push({cod:it.cod,desc:it.desc,o,n:it.liq,p:o?d/o*100:0})}});
      const sai=j.tab&&!j.keepOld?Object.keys(old).filter(pid=>{const p=C.find(x=>x.id==pid); return p&&!j.items.some(i=>i.cod===p.cod)}).length:0; Object.assign(j,{novos,sub,desc,igual,ch,sai})}
    const miss=jobs.filter(j=>j.map&&(j.map.cod==null||j.map.liq==null));
    pv.innerHTML=`${miss.length?`<p class="bad">Não reconheci as colunas de código/preço em: ${miss.map(j=>esc(j.f)).join(', ')}</p>`:''}
     <div style="overflow-x:auto"><table class="t"><tr><th>Arquivo</th><th>Tabela</th><th class="n">Itens</th><th class="n">Novos</th><th class="n">Subiram</th><th class="n">Caíram</th><th class="n">Iguais</th><th class="n">Saíram</th></tr>
     ${jobs.map((j,k)=>`<tr><td><small>${esc(j.f)}</small></td><td>${j.fixo?esc(j.nome):`<input data-tn="${k}" value="${esc(j.nome)}" style="padding:6px;width:170px">${j.tab?'':' <small class="warn">nova</small>'}`}</td><td class="n">${j.items.length}</td><td class="n">${j.novos}</td><td class="n bad">${j.sub}</td><td class="n ok">${j.desc}</td><td class="n">${j.igual}</td><td class="n">${j.sai}</td></tr>`).join('')}</table></div>
     ${jobs.some(j=>j.ch.length)?`<details style="margin-top:8px"><summary class="hint">Ver mudanças de preço (${jobs.reduce((s,j)=>s+j.ch.length,0)})</summary><div class="diff"><table class="t"><tr><th>Tabela</th><th>Código</th><th class="n">Antes</th><th class="n">Agora</th><th class="n">%</th></tr>${jobs.flatMap(j=>j.ch.slice(0,300).map(c=>`<tr><td>${esc(j.nome)}</td><td>${esc(c.cod)}</td><td class="n">${brl(c.o)}</td><td class="n">${brl(c.n)}</td><td class="n ${c.p>0?'bad':'ok'}">${c.p.toFixed(1)}%</td></tr>`)).join('')}</table></div></details>`:''}
     <div class="row" style="margin-top:10px">${miss.length||jobs.some(j=>!j.items.length)?'<span class="bad">Corrija a planilha: sem itens com código e preço reconhecidos.</span>':'<button class="btn" id="aprov">Aprovar e gravar</button>'}<span class="hint" id="aprSt"></span></div>`;
    if(!$('#aprov')) return;
    pv.oninput=e=>{const i=e.target.closest('[data-tn]'); if(i) jobs[+i.dataset.tn].nome=i.value};
    $('#aprov').onclick=async()=>{const b=$('#aprov'); b.disabled=true; const st=$('#aprSt');
      try{// produtos: união de todos os arquivos (último vence)
        const prod={}; jobs.forEach(j=>j.items.forEach(it=>{const ob=byCod[it.cod]||{}; prod[it.cod]={rep,cod:it.cod,ref:it.ref||ob.ref||it.cod,descricao:it.desc||ob.descricao||'',un:it.un||ob.un||null,emb:it.emb||ob.emb||null,mult:Math.max(1,Math.round(it.mult||ob.mult||1)),ncm:it.ncm||ob.ncm||null,ipi:it.ipi!==undefined&&it.ipi!==null?it.ipi:(ob.ipi??null),ca:it.ca||ob.ca||null,grupo:ob.grupo||it.grupo||null,linha:it.linha||ob.linha||null,ficha:it.ficha||ob.ficha||null,img:it.img||ob.img||null,ativo:true,attrs:{...(ob.attrs||{}),...(it.attrs||{}),ean:it.ean||(ob.attrs||{}).ean||null,prazo:it.prazo||(ob.attrs||{}).prazo||null,st:it.st,obs:it.obs||(ob.attrs||{}).obs||null},atualizado_em:new Date().toISOString()}}));
        const arr=Object.values(prod); const ids={}; for(let i=0;i<arr.length;i+=400){st.textContent=`Gravando produtos ${i}/${arr.length}…`; const r=await api('produtos?on_conflict=rep,cod&select=id,cod',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=representation'},body:JSON.stringify(arr.slice(i,i+400))}); r.forEach(x=>ids[x.cod]=x.id)}
        for(const j of jobs){let tid=j.tab&&norm(j.tab.nome)===norm(j.nome)?j.tab.id:null; if(!tid){const r=await api('tabelas?on_conflict=rep,nome&select=id',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=representation'},body:JSON.stringify([{rep,nome:j.nome,vigencia:new Date().toISOString().slice(0,10),ativa:true}])}); tid=r[0].id}
          const pr=[]; j.items.forEach(it=>{const pid=ids[it.cod]; if(!pid) return; if(it.liq!=null) pr.push({tabela_id:tid,produto_id:pid,nivel:'liq',preco:it.liq}); if(it.base!=null) pr.push({tabela_id:tid,produto_id:pid,nivel:'base',preco:it.base}); if(it.icms!=null) pr.push({tabela_id:tid,produto_id:pid,nivel:'icms',preco:it.icms}); if(it.enc!=null) pr.push({tabela_id:tid,produto_id:pid,nivel:'enc',preco:it.enc})});
          for(let i=0;i<pr.length;i+=800){st.textContent=`Tabela ${j.nome}: preços ${i}/${pr.length}…`; await api('precos?on_conflict=tabela_id,produto_id,nivel',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify(pr.slice(i,i+800).map(x=>({...x,atualizado_em:new Date().toISOString()})))})}
          await logPrecos(rep,{id:tid,nome:j.nome},j.ch.filter(c=>byCod[c.cod]).map(c=>({p:byCod[c.cod],antes:c.o,depois:c.n})),'planilha '+j.f);
          if(j.tab&&!j.keepOld){const keep=new Set(j.items.map(it=>ids[it.cod])); const gone=Object.keys(await prices(tid,true)).filter(pid=>!keep.has(+pid)); for(let i=0;i<gone.length;i+=100) await api(`precos?tabela_id=eq.${tid}&produto_id=in.(${gone.slice(i,i+100).join(',')})`,{method:'DELETE'})}
          (delete PRICES[tid],STALE.add('pr_'+tid))}
        await api('alteracoes',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({rep,tipo:'importacao',resumo:jobs.map(j=>({arquivo:j.f,tabela:j.nome,itens:j.items.length,novos:j.novos,subiram:j.sub,cairam:j.desc,sairam:j.sai}))})}).catch(()=>{});
        (delete CAT[rep],STALE.add('cat_'+rep)); (delete TABS[rep],STALE.add('tab_'+rep)); (REPS=null,(STALE.add('reps'),CNTP.t=0)); st.textContent=''; toast('Importação concluída'); const msg=`✓ ${jobs.length} tabela(s) e ${arr.length} produtos gravados.`; if(done) return done(msg); admImp(rep); $('#adm').insertAdjacentHTML('afterbegin',`<p class="ok">${msg}</p>`)}
      catch(err){st.textContent=''; toast('Erro: '+err.message); b.disabled=false}}}


/* ---------- regra de preço Marcon → Gurgelmix (mesma regra da planilha de conferência) ----------
   1) código nas tabelas de campanha Gurgel (18% CIF): preço da tabela (Campanha A, ou B se A vazio), sem desconto nenhum;
   2) código da Gurgel (FG/LM, via similares) fora dessas tabelas: mesmo preço final do código Marcon equivalente;
   3/4) Tabela Bruta ou campanha geral Marcon: Tabela Base × cascata Desc 1..6 da aba GURGELMIX (negativo = acréscimo);
   5) sem desconto cadastrado nem similar: Tabela Base (fator 1) e fica na lista de pendências. */
const rHU=v=>Math.round(Math.round(v*1e6)/1e4)/100; /* 2 casas, meio para cima (166,345 → 166,35) */
const gcod=c=>String(c??'').trim().replace(/\s+/g,' ').toUpperCase();
const gnum=v=>{if(typeof v==='number') return v; const s=String(v??'').replace(/[^\d,.-]/g,''); if(!s) return null; const n=+(s.includes(',')?s.replace(/\./g,'').replace(',','.'):s); return isNaN(n)?null:n};
const ehGurgel=nome=>/GURGEL/.test(norm(nome));
function gurRegraDe(tab){try{const o=JSON.parse((tab&&tab.obs)||'{}'); return o&&o.gurgel||null}catch(e){return null}}
/* Gurgelmix: único cliente Marcon com frete CIF; prazo sem as parcelas no fim; lead time em dias corridos (planilha da Gurgel) */
const gurTab=()=>(TABS.marcon||[]).find(t=>ehGurgel(t.nome));
const ehGurO=(o,tab)=>!!o&&o.rep==='marcon'&&(ehGurgel(tab&&tab.nome)||/GURGEL/.test(norm((o.cli&&o.cli.n)||o.cliente||'')));
const gurFrete='Frete CIF (por conta da Marcon).';
const gurPrazo=pz=>String(pz||'').replace(/\s+\d+(\s*,\s*\d+)+\s*$/,'');
function ltCorridos(tab,p){const R=gurRegraDe(ehGurgel(tab&&tab.nome)?tab:gurTab())||{}; const L=R.lt||{}; const c=gcod(p.cod).replace(/\.+$/,''); const sm=(R.sim||{})[c];
  const v=L[c]??(sm!=null?L[sm]:undefined)??L[c.replace(/^LM(PR|VM)/,'')]; if(v!=null&&v!=='') return String(v); const du=+leadTime(p); return du?String(Math.round(du*1.4)+7):''}
/* lê as planilhas: tabelas de campanha (cabeçalho "Ref." + "Campanha A"), descontos (aba GURGELMIX), similares (Tabela | Cod Terceiro | Cod Marcon) */
function gurLer(wb,arq){const out={camp:{},desc:{},sim:{},lt:{},dup:[],vistos:[]}; const H=r=>r.map(c=>norm(c).replace(/\s+/g,' ').trim());
  for(const sn of wb.SheetNames){const rows=XLSX.utils.sheet_to_json(wb.Sheets[sn],{header:1,defval:''});
    if(norm(sn).trim()==='GURGELMIX'){const hi=rows.findIndex(r=>H(r).some(c=>/^COD/.test(c))&&H(r).some(c=>/^DESC/.test(c))); if(hi<0) continue; const h=H(rows[hi]); const ic=h.findIndex(c=>/^COD/.test(c)); const id=[1,2,3,4,5,6].map(k=>h.findIndex(c=>c.replace(/\s/g,'')==='DESC'+k));
      let n=0; rows.slice(hi+1).forEach(r=>{const c=gcod(r[ic]); if(!c||out.desc[c]) return; const D=id.map(i=>{if(i<0) return 0; let v=gnum(r[i])||0; if(Math.abs(v)>=1) v/=100; return v}); out.desc[c]={d:D.map(v=>Math.round(v*1e6)/1e6),f:D.reduce((f,v)=>f*(1-v),1)}; n++}); out.vistos.push(`${arq}: descontos GURGELMIX (${n} códigos)`); continue}
    const hl=rows.findIndex(r=>H(r).some(c=>/^TOTAL LEAD TIME/.test(c)));
    if(hl>=0){const h=H(rows[hl]); const ic=h.findIndex(c=>/^COD\.? (ITEM )?FORNECEDOR/.test(c)), it=h.findIndex(c=>/^TOTAL LEAD TIME/.test(c)); let n=0;
      if(ic>=0) rows.slice(hl+1).forEach(r=>{const c=gcod(r[ic]).replace(/\.+$/,''); const v=gnum(r[it]); if(c&&v>0&&out.lt[c]==null){out.lt[c]=Math.round(v); n++}});
      out.vistos.push(`${arq} (${sn}): lead time Gurgel em dias corridos (${n} códigos)`); continue}
    const hs=rows.findIndex(r=>H(r).includes('COD TERCEIRO')&&H(r).includes('COD MARCON'));
    if(hs>=0){const h=H(rows[hs]); const it=h.indexOf('TABELA'), i3=h.indexOf('COD TERCEIRO'), im=h.indexOf('COD MARCON'); let n=0;
      rows.slice(hs+1).forEach(r=>{if(it>=0&&!/GURGEL/.test(norm(r[it]))) return; const a=gcod(r[i3]), b=gcod(r[im]); if(!a||!b) return; if(out.sim[a]){if(out.sim[a]!==b) out.dup.push(`${a} aparece 2x no similares (${out.sim[a]} e ${b}); usei ${out.sim[a]}`); return} out.sim[a]=b; n++});
      out.vistos.push(`${arq}: similares Gurgelmix (${n} códigos)`); continue}
    let n=0, h=null, ia=-1, ib=-1, ir=-1;
    rows.forEach(r=>{const hh=H(r); if(hh.some(c=>/^REF\.?$/.test(c))&&hh.includes('CAMPANHA A')){h=hh; ir=hh.findIndex(c=>/^REF\.?$/.test(c)); ia=hh.indexOf('CAMPANHA A'); ib=hh.indexOf('CAMPANHA B'); return} if(!h) return;
      const c=gcod(r[ir]); if(!c) return; const a=gnum(r[ia]), b=ib>=0?gnum(r[ib]):null; const v=a>0?a:(b>0?b:null); if(v==null) return; if(!out.camp[c]){out.camp[c]={v,b:!(a>0),t:arq.replace(/\.\w+$/,'')}; n++}});
    if(n) out.vistos.push(`${arq}: tabela de campanha Gurgel (${n} códigos)`)}
  return out}
/* calcula o preço de cada código; it = [{cod, base, obs}] (base = Tabela Base do Reprio) */
function gurCalc(R,its){const B={}, O={}; its.forEach(i=>{const c=gcod(i.cod); B[c]=i.base; O[c]=i.obs||''}); const sim={...R.sim}; if(sim['LMJ-2T']) sim['LMJ-2T']='MJH-2T';
  const M={}; const fx=f=>f.toLocaleString('pt-BR',{maximumFractionDigits:6});
  const own=c=>{const b=B[c]; if(!(b>0)) return null; const d=R.desc[c]; const tipo=/BRUTA/.test(norm(O[c]))?'Tabela bruta':'Campanha geral Marcon';
    if(!d) return {v:rHU(b),r:'Sem desconto cadastrado na aba GURGELMIX: Tabela Base sem desconto',pend:1};
    return {v:rHU(b*d.f),r:`${tipo}: ${brl(b)} × ${fx(d.f)} (${d.d.map(v=>String(Math.round(v*10000)/100).replace('.',',')).join('/')})`}};
  const P=(c,dp=0)=>{if(M[c]!==undefined) return M[c]; if(dp>4) return null; let x=null; const k=R.camp[c];
    if(k) x={v:rHU(k.v),r:`Tabela Gurgel ${k.t}: preço ${k.b?'Campanha B (A vazio)':'Campanha A'} sem desconto`};
    else{const s=sim[c]||(/^LM(PR|VM)/.test(c)?c.replace(/^LM(PR|VM)/,''):null); const q=s&&s!==c&&(B[s]>0||R.camp[s])?P(s,dp+1):null;
      x=q?{v:q.v,r:`Igual ao Marcon ${s} (${q.r})`,pend:q.pend}:own(c)}
    return M[c]=x};
  its.forEach(i=>P(gcod(i.cod))); return M}
async function admGur(rep){const a=$('#adm'); const T=await tabelas(rep,true); const tab=T.find(t=>ehGurgel(t.nome)); if(!tab){a.innerHTML='<p class="bad">Não encontrei a tabela Gurgelmix da Marcon.</p>'; return}
  const salvo=gurRegraDe(tab); const cnt=o=>Object.keys(o||{}).length;
  a.innerHTML=`<div class="card grid"><b>Regra de preço Gurgelmix (${esc(tab.nome)})</b>
   <p class="hint" style="margin:0">1) Código nas tabelas de campanha Gurgel: preço da tabela, sem desconto. 2) Código da Gurgel (FG/LM) fora delas: mesmo preço do Marcon equivalente (similares). 3) Tabela bruta e campanhas gerais: Tabela Base × descontos da aba GURGELMIX (negativo = acréscimo). 4) Sem desconto nem similar: Tabela Base e fica em pendências.</p>
   <p class="hint" style="margin:0">${salvo?`Regra salva em ${esc(new Date(salvo.em).toLocaleString('pt-BR'))}: ${cnt(salvo.camp)} preços de campanha, ${cnt(salvo.desc)} descontos, ${cnt(salvo.sim)} similares, ${cnt(salvo.lt)} lead times. Ao importar de novo a planilha Gurgelmix do Reprio, a regra é aplicada sozinha.`:'Ainda não há regra salva.'}</p>
   <label class="f">Planilhas (tabelas Gurgel 18% CIF, descontos.xlsx, similares.xlsx, planilha de lead time da Gurgel; pode mandar só as que mudaram)<input id="gfiles" type="file" accept=".xlsx,.xls" multiple style="width:100%"></label>
   ${salvo?'<div class="row"><button class="chip" id="grec">Recalcular com a regra salva</button></div>':''}<div id="gprev"></div></div>`;
  const run=async novo=>{const pv=$('#gprev'); pv.innerHTML='<p class="hint">Calculando…</p>'; const R={camp:{...(salvo&&salvo.camp||{})},desc:{...(salvo&&salvo.desc||{})},sim:{...(salvo&&salvo.sim||{})},lt:{...(salvo&&salvo.lt||{})},dup:[],vistos:[]};
    if(novo){if(cnt(novo.camp)) R.camp=novo.camp; if(cnt(novo.desc)) R.desc=novo.desc; if(cnt(novo.sim)) R.sim=novo.sim; if(cnt(novo.lt)) R.lt=novo.lt; R.dup=novo.dup; R.vistos=novo.vistos}
    const C=await catalog(rep,true); const PR=await prices(tab.id,true); const byId={}; C.forEach(p=>byId[p.id]=p);
    const its=Object.keys(PR).map(pid=>byId[pid]).filter(Boolean).map(p=>({p,cod:p.cod,base:PR[p.id].base,obs:(p.attrs||{}).obs}));
    const M=gurCalc(R,its); const ch=[], pend=[], arr=[]; let igual=0;
    its.forEach(i=>{const x=M[gcod(i.cod)]; const o=PR[i.p.id].liq; if(!x){pend.push(`${i.cod}: sem Tabela Base, preço mantido`); return} if(x.pend) pend.push(`${i.cod}: ${x.r}`); if(o!=null&&Math.abs(x.v-o)<1e-9) igual++; else if(o!=null&&Math.abs(x.v-o)<.005) arr.push({i,o,x}); else ch.push({i,o,x})});
    const naoTem=Object.keys(R.camp).filter(c=>!C.some(p=>gcod(p.cod)===c)); if(naoTem.length) pend.push(`Códigos das tabelas Gurgel que não estão no catálogo do Sistema (${naoTem.length}): ${naoTem.slice(0,40).join(', ')}${naoTem.length>40?'…':''}`);
    const ok=cnt(R.camp)&&cnt(R.desc);
    pv.innerHTML=`${R.vistos.length?`<p class="ok">${R.vistos.map(esc).join('<br>')}</p>`:''}${novo&&!R.vistos.length?'<p class="bad">Não reconheci nenhuma das planilhas.</p>':''}
     ${!cnt(R.camp)?'<p class="bad">Faltam as tabelas de campanha Gurgel.</p>':''}${!cnt(R.desc)?'<p class="bad">Falta o descontos.xlsx (aba GURGELMIX).</p>':''}${!cnt(R.sim)?'<p class="warn">Sem similares: os códigos FG/LM ficam com o próprio preço.</p>':''}
     <p>${its.length} produtos na tabela · <b>${ch.length}</b> preços mudam · ${igual+arr.length} já estavam certos${arr.length?` (${arr.length} só com casas decimais a mais, ficam com 2 casas)`:''}</p>
     ${['4503','BF-2','FG-063','1','FG-115'].map(c=>{const x=M[c]; return x?`<span class="tag">${c}: ${brl(x.v)}</span> `:''}).join('')}
     ${ch.length?`<div class="diff" style="margin-top:8px"><table class="t"><tr><th>Código</th><th>Descrição</th><th class="n">Antes</th><th class="n">Agora</th><th>Regra</th></tr>${ch.map(c=>`<tr><td>${esc(c.i.cod)}</td><td><small>${esc(String(c.i.p.descricao||'').slice(0,40))}</small></td><td class="n">${c.o==null?'—':brl(c.o)}</td><td class="n"><b>${brl(c.x.v)}</b></td><td><small>${esc(c.x.r)}</small></td></tr>`).join('')}</table></div>`:''}
     ${pend.length||R.dup.length?`<details style="margin-top:8px"><summary class="warn">Pendências para conferir (${pend.length+R.dup.length})</summary><p class="hint">${[...R.dup,...pend].map(esc).join('<br>')}</p></details>`:''}
     <div class="row" style="margin-top:10px">${ok?`<button class="btn" id="gapr">${ch.length||arr.length?'Aprovar e gravar':'Salvar a regra'}</button>`:''}<button class="chip" id="gxls">⬇ Planilha para o Reprio</button><span class="hint" id="gst"></span></div>`;
    $('#gxls').onclick=async()=>{const ws=XLSX.utils.aoa_to_sheet([['Codigo','Descrição','Tabela Base','Preço de Custo','Regra'],...its.map(i=>{const x=M[gcod(i.cod)]; return [i.cod,i.p.descricao||'',i.base??'',x?x.v:PR[i.p.id].liq,x?x.r:'sem Tabela Base']})]); const wb=XLSX.utils.book_new(); XLSX.utils.book_append_sheet(wb,ws,'Produtos'); XLSX.writeFile(wb,'Precos_Gurgelmix_Marcon.xlsx')};
    const b=$('#gapr'); if(b) b.onclick=async()=>{b.disabled=true; const st=$('#gst');
      try{let ob={}; try{ob=JSON.parse(tab.obs||'{}')||{}}catch(e){ob={texto:tab.obs}} ob.gurgel={camp:R.camp,desc:R.desc,sim:R.sim,lt:R.lt,em:new Date().toISOString()};
        await api(`tabelas?id=eq.${tab.id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({obs:JSON.stringify(ob)})});
        const pr=[...ch,...arr].map(c=>({tabela_id:tab.id,produto_id:c.i.p.id,nivel:'liq',preco:c.x.v,atualizado_em:new Date().toISOString()}));
        for(let i=0;i<pr.length;i+=800){st.textContent=`Gravando ${i}/${pr.length}…`; await api('precos?on_conflict=tabela_id,produto_id,nivel',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify(pr.slice(i,i+800))})}
        await api('alteracoes',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({rep,tipo:'regra_gurgelmix',resumo:[{tabela:tab.nome,itens:its.length,mudaram:ch.length,pendencias:pend.length}]})}).catch(()=>{});
        (delete PRICES[tab.id],STALE.add('pr_'+tab.id)); (delete TABS[rep],STALE.add('tab_'+rep)); toast('Preços Gurgelmix gravados'); await admGur(rep); $('#adm').insertAdjacentHTML('afterbegin',`<p class="ok">✓ ${ch.length} preços da ${esc(tab.nome)} atualizados pela regra.</p>`)}
      catch(err){st.textContent=''; toast('Erro: '+err.message); b.disabled=false}}};
  $('#gfiles').onchange=async e=>{const fs=[...e.target.files]; if(!fs.length) return; await loadXLSX(); const N={camp:{},desc:{},sim:{},lt:{},dup:[],vistos:[]};
    for(const f of fs){const r=gurLer(XLSX.read(await f.arrayBuffer()),f.name); Object.keys(r.camp).forEach(c=>{if(!N.camp[c]) N.camp[c]=r.camp[c]}); Object.assign(N.desc,r.desc); Object.assign(N.sim,r.sim); Object.assign(N.lt,r.lt); N.dup.push(...r.dup); N.vistos.push(...r.vistos); if(!r.vistos.length) N.vistos.push(f.name+': não reconhecida (ignorada)')}
    run(N).catch(err=>{$('#gprev').innerHTML=`<p class="bad">Erro: ${esc(err.message)}</p>`})};
  const g=$('#grec'); if(g) g.onclick=()=>run(null)}

/* ---------- trazer catálogo dos apps Medix/Marluvas (lê o pacote protegido com a senha da equipe; nada sai do aparelho além da gravação na base) ---------- */
const APPSRC={marluvas:'/conversor-ca/teste/index.html',medix:'/medix-luvas/teste/index.html'};
const MDX_LN={SAFE:'Safety',PROF:'Profissional',HOSP:'Hospitalar',VF:'Vida Fácil'};
const APPC={}; function lerApp(rep){return APPC[rep]||(APPC[rep]=lerApp0(rep).catch(e=>{delete APPC[rep]; throw e}))}
async function lerApp0(rep){const tp=await garantirTp(); if(!tp) throw new Error('Não consegui liberar o app (sem conexão com a base). Tente de novo.');
  const h=await (await fetch(APPSRC[rep]+'?v='+Date.now(),{cache:'no-store'})).text(); const m=h.match(/const ENC=\{s:"([^"]+)",i:"([^"]+)",d:"([^"]+)",n:(\d+)\}/); if(!m) throw new Error('Não encontrei o pacote do app.');
  const ub=x=>Uint8Array.from(atob(x),c=>c.charCodeAt(0)); const bk=await crypto.subtle.importKey('raw',new TextEncoder().encode(tp),'PBKDF2',false,['deriveBits']);
  const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:ub(m[1]),iterations:+m[4],hash:'SHA-256'},bk,256); const k=await crypto.subtle.importKey('raw',bits,'AES-GCM',false,['decrypt']);
  const js=new TextDecoder().decode(await crypto.subtle.decrypt({name:'AES-GCM',iv:ub(m[2])},k,ub(m[3])));
  const a=js.indexOf('const CAT = ')+12, b=js.indexOf(';\nconst VIG'); const CATX=JSON.parse(js.slice(a,b)); const vig=(js.match(/const VIG = "([^"]*)"/)||[])[1]||'';
  let CH=null; const c1=js.indexOf('const CHANNELS = ['); if(c1>=0){const c2=js.indexOf('];',c1); try{CH=Function('return '+js.slice(c1+17,c2+1))()}catch(e){}}
  let CLI=[]; const k1=js.indexOf('const CLI='); if(k1>=0){const k2=js.indexOf('; const GRD=',k1); try{CLI=JSON.parse(js.slice(k1+10,k2))}catch(e){}}
  return {CATX,vig,CH,CLI}}
const r2=v=>Math.round(v*100)/100;
function jobsDoApp(rep,{CATX,CH}){const limpa=d=>String(d||'').split('|').map(x=>x.trim()).filter(Boolean).join(' · ');
  if(rep==='marluvas'){const chs=(CH||[{c:'0',d:0}]); const base=CATX.filter(it=>it.p&&it.cod);
    const mk=it=>({cod:String(it.cod),ref:it.ref,desc:(it.ref?it.ref+' — ':'')+limpa(it.d),un:'PAR',mult:1,ipi:it.ipi??null,ca:it.ca||null,grupo:it.a&&it.a.tipo?it.a.tipo.charAt(0)+it.a.tipo.slice(1).toLowerCase():null,img:it.img||null,ficha:it.ft?'https://drive.google.com/file/d/'+it.ft+'/view':null,prazo:it.pz?String(it.pz):'',attrs:{tam:it.tam||null,est:it.est||null,...(it.a||{})}});
    return chs.map(ch=>({f:'app Marluvas',nome:ch.c==='0'?'TABELA GERAL SP':ch.c,items:base.map(it=>({...mk(it),liq:r2(it.p*(1-(ch.d||0)/100))}))}))}
  if(rep==='medix'){const base=CATX.filter(it=>it.cod&&it.pt&&Object.keys(it.pt).length); const lv=['1','2','3','4','5'];
    const fit=(pt,c)=>{if(pt[c]!=null) return pt[c]; const ks=Object.keys(pt).filter(k=>k!=='E'); let best=ks[0]; ks.forEach(k=>{if(Math.abs(+k-+c)<Math.abs(+best-+c)) best=k}); return pt[best]};
    const mk=it=>({cod:String(it.cod),ref:it.ref,desc:it.d,un:it.un||null,emb:it.emb||null,mult:it.mult||1,ipi:it.ipi??null,ca:it.ca||null,grupo:MDX_LN[it.ln]||it.ln||null,linha:it.sec||null,img:'/medix-luvas/img/'+(it.im||it.cod)+'.jpg',attrs:{sec:it.sec||null}});
    return lv.map(c=>({f:'app Medix',nome:'SUDESTE '+c+' (comissão '+c+'%)',items:base.map(it=>({...mk(it),liq:fit(it.pt,c),enc:it.pt.E??null}))}))}
  return []}
async function admApp(rep){const a=$('#adm'); a.innerHTML=`<div class="card grid"><p class="hint">Copia para a base os produtos e preços que estão hoje no app ${rep==='medix'?'Medix':'Marluvas'} (versão de teste). Você vê a prévia antes; nada é gravado sem aprovar. Depois disso, o orçamento único do sistema usa esses preços.</p><button class="btn" id="lerApp">Ler catálogo do app</button><div id="prev"></div></div>`;
  $('#lerApp').onclick=async()=>{const b=$('#lerApp'); b.disabled=true; const pv=$('#prev'); pv.innerHTML='<p class="hint">Abrindo o pacote protegido…</p>';
    try{const d=await lerApp(rep); const C=await catalog(rep,true).catch(()=>[]); const T=await tabelas(rep,true); const jobs=jobsDoApp(rep,d);
      jobs.forEach(j=>j.tab=T.find(t=>norm(t.nome)===norm(j.nome))); pv.innerHTML=''; pv.insertAdjacentHTML('beforebegin',`<p class="hint">Catálogo ${esc(d.vig)} · ${jobs[0]?jobs[0].items.length:0} produtos · ${jobs.length} tabelas</p>`); await prevJobs(rep,jobs,C,T,pv)}
    catch(e){pv.innerHTML=`<p class="bad">${esc(e.message)}</p>`; b.disabled=false}}}
async function admEd(rep){const a=$('#adm'); a.innerHTML='<p class="hint">Carregando…</p>'; const C=await catalog(rep,true); const T=await tabelas(rep,true);
  a.innerHTML=`<div class="card grid"><input id="eq" type="search" placeholder="Buscar produto por código ou descrição"><div id="eres"></div><div id="eform"></div></div>`;
  $('#eq').oninput=e=>{const w=norm(e.target.value); $('#eres').innerHTML=w.length<2?'':C.filter(p=>norm(p.cod+' '+p.descricao).includes(w)).slice(0,12).map(p=>`<button class="chip" style="display:block;width:100%;text-align:left;margin:3px 0" data-e="${p.id}"><b>${esc(p.cod)}</b> ${esc(p.descricao)}</button>`).join('')};
  a.onclick=async e=>{const b=e.target.closest('[data-e]'); if(!b) return; const p=C.find(x=>x.id==b.dataset.e); $('#eres').innerHTML=''; const PR={}; for(const t of T) PR[t.id]=(await prices(t.id))[p.id]||{};
    $('#eform').innerHTML=`<div class="sec" style="font-size:18px">${esc(p.cod)}</div><div class="grid"><label class="f">Descrição<input id="fd" value="${esc(p.descricao)}"></label>
     <div class="r2"><label class="f">Unidade<input id="fu" value="${esc(p.un||'')}"></label><label class="f">Múltiplo<input id="fm" type="number" value="${p.mult||1}"></label><label class="f">IPI %<input id="fi" type="number" step="0.01" value="${p.ipi??''}"></label><label class="f">NCM<input id="fn" value="${esc(p.ncm||'')}"></label>
     <label class="f">EAN<input id="fe" value="${esc(p.attrs&&p.attrs.ean||'')}"></label><label class="f">Prazo de entrega (dias)<input id="fp" value="${esc(p.attrs&&p.attrs.prazo||'')}"></label></div>
     <label class="f">Grupo<input id="fg" list="glist" value="${esc(grupoOf(rep,p))}"><datalist id="glist">${[...new Set(C.map(x=>grupoOf(rep,x)))].map(g=>`<option value="${esc(g)}">`).join('')}</datalist></label><label class="f">Link da foto<input id="fimg" value="${esc(p.img||'')}"></label><label class="f" style="display:flex;gap:8px;align-items:center"><input id="fat" type="checkbox"${p.ativo!==false?' checked':''}> Produto ativo</label>
     <table class="t"><tr><th>Tabela</th><th class="n">Bruto</th><th class="n">Líquido (orçamento)</th></tr>${T.map(t=>`<tr><td>${esc(t.nome)}</td><td class="n"><input data-pb="${t.id}" type="number" step="0.01" value="${PR[t.id].base??''}" style="width:110px;padding:6px"></td><td class="n"><input data-pl="${t.id}" type="number" step="0.01" value="${PR[t.id].liq??''}" style="width:110px;padding:6px"></td></tr>`).join('')}</table>
     <button class="btn" id="fsave">Salvar alterações</button></div>`;
    $('#fsave').onclick=async()=>{try{await api(`produtos?id=eq.${p.id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({grupo:$('#fg').value||null,descricao:$('#fd').value,un:$('#fu').value,mult:+$('#fm').value||1,ipi:$('#fi').value===''?null:+$('#fi').value,ncm:$('#fn').value,img:$('#fimg').value||null,ativo:$('#fat').checked,attrs:{...(p.attrs||{}),ean:$('#fe').value||null,prazo:$('#fp').value||null},atualizado_em:new Date().toISOString()})});
      const pr=[]; T.forEach(t=>{const b=document.querySelector(`[data-pb="${t.id}"]`).value, l=document.querySelector(`[data-pl="${t.id}"]`).value; if(b!=='') pr.push({tabela_id:t.id,produto_id:p.id,nivel:'base',preco:+b}); if(l!=='') pr.push({tabela_id:t.id,produto_id:p.id,nivel:'liq',preco:+l})});
      if(pr.length) await api('precos?on_conflict=tabela_id,produto_id,nivel',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify(pr)});
      await api('alteracoes',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({rep,tipo:'edicao',resumo:{cod:p.cod}})}).catch(()=>{});
      T.forEach(t=>(delete PRICES[t.id],STALE.add('pr_'+t.id))); (delete CAT[rep],STALE.add('cat_'+rep)); toast('Produto atualizado')}catch(err){toast('Erro: '+err.message)}}}}
async function admTab(rep){const a=$('#adm'); const T=await api(`tabelas?select=*&rep=eq.${rep}&order=nome`); const H=await api(`alteracoes?select=*&rep=eq.${rep}&order=criado_em.desc&limit=10`).catch(()=>[]);
  a.innerHTML=`<div class="card"><table class="t"><tr><th>Tabela</th><th>Vigência</th><th>Ativa</th><th>Padrão do portal B2B</th></tr>${T.map(t=>`<tr><td>${esc(t.nome)}</td><td>${esc(t.vigencia||'')}</td><td><input type="checkbox" data-at="${t.id}"${t.ativa?' checked':''} aria-label="Ativa"></td><td><input type="radio" name="b2bp" data-b2b="${t.id}"${t.b2b_padrao?' checked':''} aria-label="Padrão B2B"></td><td><button class="chip" data-tdel="${t.id}" data-tn="${esc(t.nome)}">🗑</button></td></tr>`).join('')||'<tr><td colspan="4">Nenhuma tabela.</td></tr>'}</table><p class="hint">“Padrão do portal B2B” é a tabela que o cliente vê quando não tiver uma tabela definida na ficha dele.</p><table class="t" hidden></table></div>
   <div class="card" style="margin-top:12px"><b>Últimas alterações</b>${H.map(h=>`<p class="hint">${new Date(h.criado_em).toLocaleString('pt-BR')} · ${esc(h.tipo)} · ${esc(JSON.stringify(h.resumo).slice(0,160))}</p>`).join('')||'<p class="hint">Nenhuma.</p>'}</div>`;
  a.onclick=async e=>{const d=e.target.closest('[data-tdel]'); if(!d) return; if(!confirm(`Excluir a tabela “${d.dataset.tn}” e todos os preços dela? Orçamentos já feitos não mudam.`)) return; try{await api(`tabelas?id=eq.${d.dataset.tdel}`,{method:'DELETE'}); (delete TABS[rep],STALE.add('tab_'+rep)); toast('Tabela excluída'); admTab(rep)}catch(err){toast('Erro: '+err.message)}};
  a.onchange=async e=>{const b=e.target.closest('[data-b2b]'); if(b){try{await api(`tabelas?rep=eq.${rep}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({b2b_padrao:false})}); await api(`tabelas?id=eq.${b.dataset.b2b}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({b2b_padrao:true})}); toast('Tabela padrão do portal definida')}catch(err){toast('Rode o SQL 7 no Supabase para ativar o portal')} return} const c=e.target.closest('[data-at]'); if(c){await api(`tabelas?id=eq.${c.dataset.at}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({ativa:c.checked})}); (delete TABS[rep],STALE.add('tab_'+rep)); toast('Tabela '+(c.checked?'ativada':'desativada'))}}}

/* ---------- tabelas de preço (estilo Reprio): representada › tabela › produtos vinculados, preço na linha, preço em massa, promoção, histórico ---------- */
async function contar(path){const t=await token(); const r=await fetch(SB+'/rest/v1/'+path,{method:'HEAD',headers:{apikey:KEY,Authorization:'Bearer '+t,Prefer:'count=exact'}}); if(!r.ok) throw new Error('HTTP '+r.status); return +((r.headers.get('content-range')||'').split('/')[1])||0}
/* cada mudança de preço vira uma linha em alteracoes (tipo preco), que é o histórico do produto na tabela */
async function logPrecos(rep,tab,L,origem){const por=meuNome()||null; const rows=L.filter(x=>x.antes!==x.depois).map(x=>({rep,tipo:'preco',resumo:{tid:tab.id,tabela:tab.nome,pid:x.p.id,cod:x.p.cod,antes:x.antes??null,depois:x.depois??null,origem,por}}));
  for(let i=0;i<rows.length;i+=500) await api('alteracoes',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify(rows.slice(i,i+500))}).catch(()=>{})}
async function admTabelas(rep){const a=$('#adm'); a.innerHTML='<p class="hint">Carregando…</p>';
  let T,C,R,N; try{[T,C,R]=await Promise.all([api(`tabelas?select=*&rep=eq.${rep}&order=nome`),catalog(rep,true).catch(()=>[]),reps()]); N=await Promise.all(T.map(t=>contar(`precos?select=produto_id&tabela_id=eq.${t.id}&nivel=eq.liq`).catch(()=>null)))}catch(e){a.innerHTML=`<p class="bad">${esc(e.message)}</p>`; return} if(!a.isConnected) return;
  const nm=(R.find(r=>r.id===rep)||{}).nome||rep;
  a.innerHTML=`<p class="hint">Entre na tabela para ver os produtos, importar a planilha dela e mudar preços. ${C.length} produtos ativos na ${esc(nm)}.</p>
   <div class="tpl">${T.map((t,i)=>`<button class="tpc${t.ativa?'':' off'}" data-tid="${t.id}"><b>${esc(t.nome)}</b><span class="hint">${N[i]==null?'—':N[i]+' de '+C.length+' produtos vinculados'}${t.vigencia?' · desde '+dbr(t.vigencia):''}</span><span class="tags">${t.ativa?'<span class="tag ok">ativa</span>':'<span class="tag">inativa</span>'}${t.b2b_padrao?'<span class="tag">padrão do portal</span>':''}${rep==='marcon'&&gurRegraDe(t)?'<span class="tag">regra Gurgelmix</span>':''}</span></button>`).join('')}
    <button class="tpc nova" id="tpNova"><b>＋ Nova tabela</b><span class="hint">Criar e importar a planilha dela</span></button></div>`;
  a.onclick=async e=>{const b=e.target.closest('[data-tid]'); if(b) return go('admin',{rep,tid:+b.dataset.tid});
    if(e.target.closest('#tpNova')){const n=(prompt('Nome da nova tabela de preço:')||'').trim(); if(!n) return; if(T.some(t=>norm(t.nome)===norm(n))) return toast('Já existe uma tabela com esse nome');
      try{const r=await api('tabelas?select=id',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify([{rep,nome:n,vigencia:hojeISO(),ativa:true}])}); (delete TABS[rep],STALE.add('tab_'+rep)); go('admin',{rep,tid:r[0].id})}catch(err){toast('Erro: '+err.message)}}}}
async function tabPreco(rep,tid){const m=$('#main'); m.innerHTML='<p class="hint">Carregando…</p>';
  let T,C,PR,R; try{[T,C,PR,R]=await Promise.all([api(`tabelas?select=*&id=eq.${tid}`),catalog(rep,true),prices(tid,true),reps(),campanhas(rep,true)])}catch(e){m.innerHTML=`<p class="bad">${esc(e.message)}</p>`; return}
  const tab=T[0]; if(!tab) return go('admin',{rep}); const nm=(R.find(r=>r.id===rep)||{}).nome||rep;
  const f={q:'',vin:true,nao:false,promo:false,g:'',lim:50}, sel=new Set();
  const liq=p=>(PR[p.id]||{}).liq, vinc=p=>liq(p)!=null, promo=p=>vinc(p)?campDe(rep,p,tid,liq(p),null):null;
  const temBase=Object.values(PR).some(x=>x.base!=null); const G=[...new Set(C.map(p=>grupoOf(rep,p)).filter(Boolean))].sort();
  const sync=rep==='medix'||(rep==='marluvas'&&norm(tab.nome)==='TABELA GERAL SP');
  const filtra=()=>{const w=norm(f.q).trim().split(/\s+/).filter(Boolean); return C.filter(p=>{const v=vinc(p); if(f.vin!==f.nao&&(f.vin?!v:v)) return false; if(f.promo&&!promo(p)) return false; if(f.g&&grupoOf(rep,p)!==f.g) return false;
    if(w.length){const s=norm(p.cod+' '+(p.ref||'')+' '+p.descricao); if(!w.every(x=>s.includes(x))) return false} return true})};
  m.innerHTML=`<div class="card"><div class="sec" style="margin:0">Produtos · ${esc(tab.nome)}</div><p class="hint" style="margin:4px 0 0">Gerencie os produtos vinculados à tabela de preço da ${esc(nm)}${tab.ativa?'':' · <b class="warn">tabela inativa</b>'}${sync?' · as mudanças de preço chegam ao conversor':''}</p></div>
   <div class="row" style="justify-content:space-between;margin:12px 0"><button class="chip" id="tpVolta">← Voltar</button><div class="row"><button class="chip" id="tpXls">⬇ Baixar planilha</button><button class="btn sm ghost" id="tpImp">📄 Importar planilha</button></div></div>
   <div id="tpImpBox"></div><div class="kpis tpk" id="tpK"></div>
   <div class="card grid" style="margin-top:12px"><label class="f">Buscar produto<input id="tpQ" type="search" placeholder="Código ou descrição…" autocomplete="off"></label>
    <div class="row" style="gap:14px"><label class="tpf"><input type="checkbox" data-f="nao"> Não vinculados</label><label class="tpf"><input type="checkbox" data-f="vin" checked> Vinculados</label><label class="tpf"><input type="checkbox" data-f="promo"> Em promoção</label>${G.length>1?`<select id="tpG" style="padding:7px;font-size:13px"><option value="">Todos os grupos</option>${G.map(g=>`<option>${esc(g)}</option>`).join('')}</select>`:''}</div>
    <div class="row" style="justify-content:space-between;border-top:1px solid var(--line);padding-top:10px"><div class="row" id="tpAc"><button class="btn sm" data-ac="preco">％ Aplicar preço</button><button class="chip" data-ac="promo">🏷 Criar promoção</button><button class="chip" data-ac="rpromo">✕ Remover promoção</button><button class="chip" data-ac="desv">⛓ Desvincular selecionados</button></div>
     <div class="row"><span class="hint" id="tpSel"></span><button class="chip" id="tpTodos"></button><button class="chip" id="tpNen">Desselecionar</button></div></div></div>
   <div class="card" style="margin-top:12px;padding:0;overflow-x:auto"><table class="t tpt" id="tpT"></table><div id="tpMais" style="padding:10px"></div></div>`;
  const draw=()=>{const L=filtra(), V=C.filter(vinc).length, P=C.filter(p=>promo(p)).length;
    $('#tpK').innerHTML=`<button class="kpi${!f.nao&&!f.vin&&!f.promo?' on':''}" data-k="tot"><small>Total de produtos</small><b>${C.length}</b></button><button class="kpi${f.vin&&!f.nao&&!f.promo?' on':''}" data-k="vin"><small>Produtos vinculados</small><b class="ok">${V}</b></button><button class="kpi${f.nao&&!f.vin?' on':''}" data-k="nao"><small>Não vinculados</small><b>${C.length-V}</b></button><button class="kpi${f.promo?' on':''}" data-k="promo"><small>Em promoção</small><b style="color:#ff8a5c">${P}</b></button>`;
    m.querySelectorAll('[data-f]').forEach(x=>x.checked=f[x.dataset.f]);
    $('#tpTodos').textContent=`Selecionar todos (${L.length})`; $('#tpSel').textContent=sel.size?sel.size+' selecionado(s)':''; m.querySelectorAll('#tpAc button').forEach(b=>b.disabled=!sel.size);
    const vis=L.slice(0,f.lim);
    $('#tpT').innerHTML=`<tr><th><input type="checkbox" id="tpAll" aria-label="Selecionar os da tela"${vis.length&&vis.every(p=>sel.has(p.id))?' checked':''}></th><th>Código</th><th>Descrição</th>${temBase?'<th class="n">Bruto</th>':''}<th class="n">Preço na tabela</th><th class="n">Preço promoção</th><th>Histórico</th><th>Editar</th><th>Status</th></tr>
     ${vis.map(p=>{const v=liq(p), pr=promo(p); return `<tr data-r="${p.id}"><td><input type="checkbox" data-sel="${p.id}"${sel.has(p.id)?' checked':''} aria-label="Selecionar ${esc(p.cod)}"></td><td><b>${esc(p.cod)}</b></td><td>${esc(p.descricao)}${grupoOf(rep,p)?`<div class="hint" style="font-size:11px">${esc(grupoOf(rep,p))}</div>`:''}</td>${temBase?`<td class="n hint">${(PR[p.id]||{}).base!=null?brl(PR[p.id].base):'—'}</td>`:''}
       <td class="n"><button class="tpv" data-pe="${p.id}" title="Clique para mudar o preço">${v!=null?brl(v):'<span class="hint">definir</span>'}</button></td><td class="n">${pr?`<span style="${CAMP_ST};padding:2px 6px;border-radius:6px" title="${esc(pr.nome)}${pr.fim?' até '+dbr(pr.fim):''}">${brl(pr.pu)}</span>`:'<span class="hint">—</span>'}</td>
       <td><button class="tpi" data-hi="${p.id}" title="Histórico de preço">🕘</button></td><td><button class="tpi" data-ed="${p.id}" title="Editar produto">✎</button></td><td><span class="tag${v!=null?' ok':''}">${v!=null?'Vinculado':'Não vinculado'}</span></td></tr>`}).join('')||`<tr><td colspan="9" class="hint">Nenhum produto com esses filtros.</td></tr>`}`;
    $('#tpMais').innerHTML=L.length>f.lim?`<button class="chip" id="tpMaisB">Mostrar mais (${vis.length} de ${L.length})</button>`:`<span class="hint">${L.length} produto(s)</span>`};
  const gravar=async(L,origem)=>{const agora=new Date().toISOString(); const pr=L.map(x=>({tabela_id:tid,produto_id:x.p.id,nivel:'liq',preco:x.novo,atualizado_em:agora}));
    for(let i=0;i<pr.length;i+=800) await api('precos?on_conflict=tabela_id,produto_id,nivel',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify(pr.slice(i,i+800))});
    await logPrecos(rep,tab,L.map(x=>({p:x.p,antes:liq(x.p)??null,depois:x.novo})),origem);
    L.forEach(x=>{(PR[x.p.id]=PR[x.p.id]||{}).liq=x.novo}); STALE.add('pr_'+tid); draw()};
  const editar=td=>{const p=C.find(x=>x.id==td.dataset.pe); const v=liq(p); const cell=td.parentNode; cell.innerHTML=`<input class="tpin" inputmode="decimal" value="${v!=null?String(v).replace('.',','):''}" placeholder="0,00">`; const i=cell.firstChild; i.focus(); i.select(); let feito=false;
    const fim=async ok=>{if(feito) return; feito=true; const n=gnum(i.value); if(!ok||i.value.trim()===''||n==null||Math.abs((n||0)-(v??-1))<.005) return draw(); if(!(n>0)){toast('Preço inválido'); return draw()}
      i.disabled=true; try{await gravar([{p,novo:rHU(n)}],'edição na linha'); toast(`${p.cod}: ${brl(rHU(n))}`)}catch(err){toast('Erro: '+err.message); draw()}};
    i.onkeydown=e=>{if(e.key==='Enter') fim(true); if(e.key==='Escape') fim(false)}; i.onblur=()=>fim(true)};
  const modal=html=>{const ov=document.createElement('div'); ov.className='ov'; ov.innerHTML=`<div class="sh grid">${html}</div>`; document.body.appendChild(ov); ov.onclick=e=>{if(e.target===ov||e.target.closest('[data-x]')) ov.remove()}; return ov};
  const selP=()=>C.filter(p=>sel.has(p.id));
  const aplicar=()=>{const S=selP(); let modo='fx'; const ov=modal(`<b>Aplicar preço em ${S.length} produto(s) · ${esc(tab.nome)}</b>
     <div class="row" id="apM">${[['fx','Preço fixo (R$)'],['up','Aumentar %'],['dn','Reduzir %'],...(temBase?[['bd','Desconto sobre o bruto %']]:[])].map(([k,l],i)=>`<button class="chip${i?'':' on'}" data-m="${k}">${l}</button>`).join('')}</div>
     <label class="f"><span id="apL">Novo preço (R$)</span><input id="apV" inputmode="decimal" placeholder="0,00"></label><div id="apP" class="hint"></div>
     <div class="row"><button class="btn" id="apOk" disabled>Aplicar</button><button class="chip" data-x>Cancelar</button></div>`);
    const calc=(p,v)=>{const l=liq(p), b=(PR[p.id]||{}).base; if(modo==='fx') return rHU(v); if(modo==='up') return l!=null?rHU(l*(1+v/100)):null; if(modo==='dn') return l!=null?rHU(l*(1-v/100)):null; return b!=null?rHU(b*(1-v/100)):null};
    const prev=()=>{const v=gnum(ov.querySelector('#apV').value); const ok=v!=null&&(modo==='fx'?v>0:v>-100&&v<100); const L=ok?S.map(p=>({p,novo:calc(p,v)})).filter(x=>x.novo>0):[]; const fora=ok?S.length-L.length:0;
      ov.querySelector('#apP').innerHTML=ok?`${L.length} preço(s) vão mudar${fora?` · ${fora} ficam de fora (${modo==='bd'?'sem preço bruto':'não vinculados: use preço fixo para vincular'})`:''}<br>${L.slice(0,6).map(x=>`${esc(x.p.cod)}: ${liq(x.p)!=null?brl(liq(x.p)):'—'} → <b>${brl(x.novo)}</b>`).join('<br>')}${L.length>6?'<br>…':''}`:''; const b=ov.querySelector('#apOk'); b.disabled=!L.length; return L};
    ov.querySelector('#apM').onclick=e=>{const b=e.target.closest('[data-m]'); if(!b) return; modo=b.dataset.m; ov.querySelectorAll('[data-m]').forEach(x=>x.classList.toggle('on',x===b)); ov.querySelector('#apL').textContent=modo==='fx'?'Novo preço (R$)':'Percentual (%)'; prev()};
    ov.querySelector('#apV').oninput=prev; ov.querySelector('#apV').focus();
    ov.querySelector('#apOk').onclick=async e=>{const L=prev(); if(!L.length) return; e.target.disabled=true; try{await gravar(L,'aplicar preço em massa'); ov.remove(); sel.clear(); draw(); toast(`${L.length} preço(s) atualizados`)}catch(err){toast('Erro: '+err.message); e.target.disabled=false}}};
  const criarPromo=()=>{const S=selP().filter(vinc); if(!S.length) return toast('Selecione produtos vinculados à tabela'); let modo='desc';
    const ov=modal(`<b>Criar promoção · ${S.length} produto(s)</b><p class="hint" style="margin:0">Vale só na ${esc(tab.nome)}. Fica junto das outras campanhas da ${esc(nm)} (Representadas › ${esc(nm)} › Campanhas).</p>
     <label class="f">Nome<input id="prN" value="${esc('Promoção '+tab.nome+' '+dbr(hojeISO()).slice(0,5))}"></label>
     <div class="row" id="prM"><button class="chip on" data-m="desc">Desconto %</button><button class="chip" data-m="preco">Preço fixo (R$)</button></div>
     <div class="r2"><label class="f"><span id="prL">Desconto sobre o preço da tabela (%)</span><input id="prV" inputmode="decimal"></label><label class="f">Qtd mínima (opcional)<input id="prQ" type="number" min="0"></label><label class="f">Início<input id="prI" type="date" value="${hojeISO()}"></label><label class="f">Fim (opcional)<input id="prF" type="date"></label></div>
     <div class="row"><button class="btn" id="prOk">Criar promoção</button><button class="chip" data-x>Cancelar</button></div>`);
    ov.querySelector('#prM').onclick=e=>{const b=e.target.closest('[data-m]'); if(!b) return; modo=b.dataset.m; ov.querySelectorAll('[data-m]').forEach(x=>x.classList.toggle('on',x===b)); ov.querySelector('#prL').textContent=modo==='desc'?'Desconto sobre o preço da tabela (%)':'Preço promocional (R$)'};
    ov.querySelector('#prOk').onclick=async e=>{const nome=ov.querySelector('#prN').value.trim(), v=gnum(ov.querySelector('#prV').value), q=+ov.querySelector('#prQ').value||0, ini=ov.querySelector('#prI').value||null, fim=ov.querySelector('#prF').value||null;
      if(!nome) return toast('Informe o nome'); if(!(v>0)||(modo==='desc'&&v>=100)) return toast(modo==='desc'?'Informe o desconto':'Informe o preço'); if(ini&&fim&&fim<ini) return toast('O fim é antes do início');
      if(modo==='preco'){const caro=S.filter(p=>v>=liq(p)); if(caro.length&&!confirm(`${caro.length} produto(s) já custam menos que ${brl(v)} na tabela; para eles a promoção não aparece. Criar mesmo assim?`)) return}
      const itens=S.map(p=>{const y={cod:String(p.cod)}; if(modo==='desc') y.desc=v; else y.preco=rHU(v); if(q) y.min=q; return y});
      e.target.disabled=true; try{await api('campanhas',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({rep,nome,inicio:ini,fim,desc_geral:null,itens,tabelas:[tid],obs:null,ativa:true,criado_por:meuNome()||null,atualizado_em:new Date().toISOString()})});
        await campanhas(rep,true); ov.remove(); sel.clear(); draw(); toast('Promoção criada')}catch(err){toast('Erro: '+err.message); e.target.disabled=false}}};
  const removerPromo=async()=>{const S=selP(); const ks=new Set(S.flatMap(p=>[norm(p.cod).trim(),norm(p.ref||'').trim()]).filter(Boolean));
    const vale=c=>campSit(c)!=='encerrada'&&(!c.tabelas||!c.tabelas.length||c.tabelas.map(String).includes(String(tid)));
    const Cs=(CAMPS[rep]||[]).filter(vale); const mud=Cs.map(c=>({c,fica:(c.itens||[]).filter(x=>!ks.has(norm(x.cod||'').trim()))})).filter(x=>x.fica.length<(x.c.itens||[]).length);
    const geral=Cs.filter(c=>!(c.itens||[]).length&&c.desc_geral!=null);
    if(!mud.length) return toast(geral.length?`Esses itens estão na campanha geral “${geral[0].nome}” (vale para todos); edite-a em Representadas › Campanhas.`:'Nenhum item selecionado está em promoção nesta tabela');
    if(!confirm(`Tirar os itens selecionados de ${mud.length} promoção(ões)? ${mud.map(x=>'“'+x.c.nome+'”'+(x.fica.length?'':' (fica sem itens e é pausada)')).join(', ')}`)) return;
    try{for(const x of mud) await api(`campanhas?id=eq.${x.c.id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify(x.fica.length?{itens:x.fica,atualizado_em:new Date().toISOString()}:{itens:[],desc_geral:null,ativa:false,atualizado_em:new Date().toISOString()})});
      await campanhas(rep,true); sel.clear(); draw(); toast('Promoção removida dos itens')}catch(err){toast('Erro: '+err.message)}};
  const desvincular=async()=>{const S=selP().filter(vinc); if(!S.length) return toast('Nenhum selecionado está vinculado'); if(!confirm(`Desvincular ${S.length} produto(s) da ${tab.nome}? Eles saem da tabela (o preço é apagado; fica no histórico). Orçamentos já feitos não mudam.`)) return;
    try{const ids=S.map(p=>p.id); for(let i=0;i<ids.length;i+=100) await api(`precos?tabela_id=eq.${tid}&produto_id=in.(${ids.slice(i,i+100).join(',')})`,{method:'DELETE'});
      await logPrecos(rep,tab,S.map(p=>({p,antes:liq(p),depois:null})),'desvinculado'); S.forEach(p=>delete PR[p.id]); STALE.add('pr_'+tid); sel.clear(); draw(); toast(`${S.length} produto(s) desvinculados`)}catch(err){toast('Erro: '+err.message)}};
  const historico=async pid=>{const p=C.find(x=>x.id==pid); const ov=modal(`<div class="row" style="justify-content:space-between"><b>Histórico · ${esc(p.cod)}</b><button class="chip" data-x>Fechar</button></div><p class="hint" style="margin:0">${esc(p.descricao)} · ${esc(tab.nome)} · hoje ${liq(p)!=null?brl(liq(p)):'sem preço'}</p><div id="hiL"><p class="hint">Carregando…</p></div>`);
    try{const H=await api(`alteracoes?select=criado_em,resumo&tipo=eq.preco&resumo->>pid=eq.${pid}&resumo->>tid=eq.${tid}&order=criado_em.desc&limit=100`);
      ov.querySelector('#hiL').innerHTML=H.length?`<table class="t"><tr><th>Quando</th><th class="n">Antes</th><th class="n">Depois</th><th class="n">%</th><th>Como</th></tr>${H.map(h=>{const r=h.resumo||{}, d=r.antes&&r.depois?(r.depois/r.antes-1)*100:null; return `<tr><td>${new Date(h.criado_em).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'})}</td><td class="n">${r.antes!=null?brl(r.antes):'—'}</td><td class="n"><b>${r.depois!=null?brl(r.depois):'desvinculado'}</b></td><td class="n ${d>0?'bad':'ok'}">${d!=null?(d>0?'+':'')+d.toFixed(1).replace('.',',')+'%':''}</td><td><small>${esc(r.origem||'')}${r.por?' · '+esc(r.por):''}</small></td></tr>`}).join('')}</table>`:'<p class="hint">Nenhuma mudança registrada ainda. O histórico começa a contar a partir de 26/10/2026.</p>'}catch(err){ov.querySelector('#hiL').innerHTML=`<p class="bad">${esc(err.message)}</p>`}};
  const importar=()=>{const box=$('#tpImpBox'); if(box.innerHTML){box.innerHTML=''; return}
    box.innerHTML=`<div class="card grid" style="margin-bottom:12px"><b>Importar planilha na ${esc(tab.nome)}</b><p class="hint" style="margin:0">Colunas reconhecidas: Código e Preço (ou Preço de custo / Valor); opcionais Descrição, Unidade, Qtd múltiplo, Tabela base, IPI, NCM. A planilha do Reprio e a do “Baixar planilha” servem. Você vê a prévia antes; nada é gravado sem aprovar.</p>
     <label class="tpf"><input type="checkbox" id="tpSai"> Desvincular os produtos da tabela que não estão na planilha</label><input id="tpFile" type="file" accept=".xlsx,.xls,.csv" style="width:100%"><div id="tpPrev"></div></div>`;
    const run=async()=>{const fl=$('#tpFile').files[0]; if(!fl) return; const pv=$('#tpPrev'); pv.innerHTML='<p class="hint">Lendo planilha…</p>';
      try{await loadXLSX(); const {map,items}=await lerPlanilha(fl); const j={f:fl.name,nome:tab.nome,map,items,tab,fixo:true,keepOld:!$('#tpSai').checked}; const pre=[]; if(rep==='marcon') aplicarGurgel([j],pre);
        pv.innerHTML=pre.join(''); const d=document.createElement('div'); pv.appendChild(d); await prevJobs(rep,[j],C,[tab],d,msg=>{toast('Planilha importada'); (delete PRICES[tid],STALE.add('pr_'+tid)); tabPreco(rep,tid).then(()=>$('#tpK').insertAdjacentHTML('beforebegin',`<p class="ok">${msg}</p>`))})}catch(err){pv.innerHTML=`<p class="bad">${esc(err.message)}</p>`}};
    $('#tpFile').onchange=run; $('#tpSai').onchange=run};
  m.oninput=e=>{if(e.target.id==='tpQ'){f.q=e.target.value; f.lim=50; draw()}};
  m.onchange=e=>{const t=e.target; if(t.dataset.f){f[t.dataset.f]=t.checked; f.lim=50; return draw()} if(t.id==='tpG'){f.g=t.value; f.lim=50; return draw()}
    if(t.dataset.sel){t.checked?sel.add(+t.dataset.sel):sel.delete(+t.dataset.sel); return draw()} if(t.id==='tpAll'){filtra().slice(0,f.lim).forEach(p=>t.checked?sel.add(p.id):sel.delete(p.id)); draw()}};
  m.onclick=async e=>{const t=e.target; if(t.closest('#tpVolta')) return go('admin',{rep}); if(t.closest('#tpImp')) return importar(); if(t.id==='tpMaisB'){f.lim+=100; return draw()}
    if(t.id==='tpTodos'){filtra().forEach(p=>sel.add(p.id)); return draw()} if(t.id==='tpNen'){sel.clear(); return draw()}
    const k=t.closest('[data-k]'); if(k){const x=k.dataset.k; Object.assign(f,{vin:x==='vin',nao:x==='nao',promo:x==='promo',lim:50}); return draw()}
    const pe=t.closest('[data-pe]'); if(pe) return editar(pe); const hi=t.closest('[data-hi]'); if(hi) return historico(+hi.dataset.hi);
    const ed=t.closest('[data-ed]'); if(ed) return go('prod',{rep,pid:+ed.dataset.ed,volta:['admin',{rep,tid}]});
    const ac=t.closest('[data-ac]'); if(ac&&!ac.disabled) return ({preco:aplicar,promo:criarPromo,rpromo:removerPromo,desv:desvincular})[ac.dataset.ac]();
    if(t.id==='tpXls'){await loadXLSX(); const L=C.filter(vinc); const ws=XLSX.utils.aoa_to_sheet([['Código','Descrição',...(temBase?['Tabela base']:[]),'Preço'],...L.map(p=>[p.cod,p.descricao||'',...(temBase?[(PR[p.id]||{}).base??'']:[]),liq(p)])]); const wb=XLSX.utils.book_new(); XLSX.utils.book_append_sheet(wb,ws,'Produtos'); XLSX.writeFile(wb,`${repName(rep)}_${tab.nome.replace(/[^\w\- ]+/g,'')}.xlsx`)}};
  draw()}

/* ---------- ajustes (vale para o sistema e para os apps Medix e Marluvas) ---------- */
const RAW=k=>{try{return localStorage.getItem(k)}catch(e){return null}}, RAWS=(k,v)=>{try{v==null?localStorage.removeItem(k):localStorage.setItem(k,v)}catch(e){}};
