/* qual encarte vai para este cliente: o da fábrica do modelo escolhido, senão o de uma fábrica que ele compra */
function encDo(x){if(x.encOff) return null; const A=encAtivos(); if(!A.length) return null; const nm=s=>norm(s||'');
  const fr=[...(x.its||[]).map(i=>i.rep),x.rep,...((x.b&&x.b.reps)||[]).map(r=>r.rep)].filter(Boolean).map(nm);
  for(const f of fr){const e=A.find(e2=>nm(e2.rep)===f); if(e) return e} return null}
