/* 09/11 (pedido do Drauzio): buscar e incluir mais produtos no e-mail — até ED_MAXP, tirar os que não quer, escolher quantos "mais vendidos" mostrar */
const ED_MAXP=15, edK=i=>String((i&&i.cod)||'').trim().toUpperCase();
function edProds(x){const h=edHero(x), TI=x.tira||new Set(), b=h.mod==='desp'?[]:h.mod==='radar'?(x.heroOv?x.its:(x.rad.length?x.rad:x.its)):(x.its||[]);
  const L=[...b.slice(0,3).map(i=>({...i,o:'base'})),...(x.add||[]).map(i=>({...i,o:'add'})),...edSug(x).L.map(i=>({...i,o:'sug'}))], v=new Set(); return L.filter(i=>{const k=edK(i); if(!k||TI.has(k)||v.has(k)) return false; v.add(k); return true})}
function edProdOv(x,todos,fim){const ov=document.createElement('div'); ov.className='ov'; let R=[], q='', tq=null, rf='';
  const RP=(REPS||[]).filter(r=>r.ativa);
  const lista=()=>{const L=edProds(x), nm={base:'do e-mail',add:'você incluiu',sug:'mais vendido'}; return L.length?L.map(i=>`<div class="row" style="gap:8px;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);padding:6px 0"><span style="min-width:0;font-size:14px"><b>${esc(i.cod)}</b> ${esc(estCurto(i.ds))}<br><span class="hint" style="font-size:12px">${esc(i.rep||'')} · ${nm[i.o]}</span></span><button class="chip" data-pt="${esc(edK(i))}" aria-label="Tirar ${esc(i.cod)}">✕ Tirar</button></div>`).join(''):'<div class="hint">Nenhum produto neste e-mail.</div>'};
  const res=()=>{const tem=new Set(edProds(x).map(edK)); return !q?'<div class="hint">Digite o código ou o nome (2 letras ou mais).</div>':!R.length?'<div class="hint">Nada encontrado.</div>':R.map((p,j)=>`<div class="row" style="gap:8px;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);padding:6px 0"><span style="min-width:0;font-size:14px"><b>${esc(p.cod)}</b> ${esc(estCurto(p.descricao))}<br><span class="hint" style="font-size:12px">${esc(repName(p.rep))}</span></span>${tem.has(edK(p))?'<span class="hint">✓ no e-mail</span>':`<button class="chip" data-pa="${j}">+ Incluir</button>`}</div>`).join('')};
  const tit=()=>{const n=edProds(x).length; return `🛍 Produtos do e-mail · ${esc(x.n)} <span class="hint">(${n} de até ${ED_MAXP})</span>`};
  const pinta=()=>{ov.querySelector('#epT').innerHTML=tit(); ov.querySelector('#epL').innerHTML=lista(); ov.querySelector('#epR').innerHTML=res(); ov.querySelectorAll('[data-pn]').forEach(b=>b.classList.toggle('on',+b.dataset.pn===(x.nSug<0?0:(x.nSug||3))))};
  ov.innerHTML=`<div class="card grid" style="max-width:640px;width:100%;max-height:92vh;overflow:auto;gap:10px"><b id="epT"></b>
   <div class="f"><span>Buscar produto para incluir</span><div class="row" style="gap:6px;flex-wrap:nowrap"><input id="epQ" type="search" placeholder="Código, referência ou nome" style="flex:1;min-width:0"><select id="epF" style="max-width:40%"><option value="">Todas as fábricas</option>${RP.map(r=>`<option value="${esc(r.id)}">${esc(r.nome)}</option>`).join('')}</select></div></div>
   <div id="epR" style="max-height:34vh;overflow:auto"></div>
   <div class="f"><span>Quantos "mais vendidos" o agente sugere</span><div class="row" style="gap:6px">${[0,3,6,9,12].map(n=>`<button class="chip" data-pn="${n}">${n||'Nenhum'}</button>`).join('')}</div></div>
   <div class="ed-k" style="margin-top:4px">No e-mail agora</div><div id="epL"></div>
   <div class="row" style="gap:6px;justify-content:space-between;flex-wrap:wrap"><button class="btn sm ghost" id="epTodos" title="Os produtos que você incluiu vão em todos os e-mails de hoje">Usar os que incluí em todos os e-mails</button><button class="btn sm" id="epOk">Pronto</button></div></div>`;
  document.body.appendChild(ov); pinta(); const qi=ov.querySelector('#epQ'); qi.focus();
  const busca=async()=>{q=qi.value.trim(); rf=ov.querySelector('#epF').value; if(q.length<2){R=[]; return pinta()} const like=encodeURIComponent('*'+q.replace(/[*,()]/g,' ')+'*'); const q0=q;
    try{const r=await api(`produtos?select=id,rep,cod,ref,descricao&ativo=eq.true${rf?'&rep=eq.'+encodeURIComponent(rf):''}&or=(cod.ilike.${like},ref.ilike.${like},descricao.ilike.${like})&order=cod&limit=30`); if(q0===qi.value.trim()){R=r; pinta()}}catch(e){R=[]; pinta()}};
  qi.oninput=()=>{clearTimeout(tq); tq=setTimeout(busca,300)}; ov.querySelector('#epF').onchange=busca;
  const sai=()=>{ov.remove(); x.mudou=true; fim&&fim()};
  ov.onclick=e=>{const t=e.target; if(t===ov||t.id==='epOk') return sai();
    const a=t.closest('[data-pa]'); if(a){const p=R[+a.dataset.pa]; if(!p) return; if(edProds(x).length>=ED_MAXP) return toast(`Máximo de ${ED_MAXP} produtos por e-mail`); const k=edK(p); if(x.tira) x.tira.delete(k); x.add=[...(x.add||[]).filter(i=>edK(i)!==k),{cod:p.cod,ds:p.descricao||p.cod,rep:repName(p.rep)}]; return pinta()}
    const d=t.closest('[data-pt]'); if(d){const k=d.dataset.pt; if((x.add||[]).some(i=>edK(i)===k)) x.add=x.add.filter(i=>edK(i)!==k); else (x.tira=x.tira||new Set()).add(k); return pinta()}
    const n=t.closest('[data-pn]'); if(n){x.nSug=+n.dataset.pn; if(x.nSug===0) x.nSug=-1; return pinta()}
    if(t.id==='epTodos'){const A=x.add||[]; if(!A.length) return toast('Inclua produtos primeiro'); let c=0; (todos||[]).forEach(y=>{if(y===x) return; const tem=new Set((y.add||[]).map(edK)); y.add=[...(y.add||[]),...A.filter(i=>!tem.has(edK(i)))].slice(0,ED_MAXP); y.mudou=true; c++}); toast(`Incluídos em mais ${c} e-mail${c===1?'':'s'} de hoje`)}}}
function estEditar(x,fim){const ov=document.createElement('div'); ov.className='ov'; ov.innerHTML=`<div class="card grid" style="max-width:640px;width:100%;max-height:92vh;overflow:auto;gap:8px"><b>✎ Mudar e-mail · ${esc(x.n)}</b>
   <label class="f">Para<select id="eeP" multiple size="${Math.min(4,Math.max(2,x.em.length))}">${x.em.map(e=>`<option value="${esc(e.e)}" ${x.para.includes(e.e)?'selected':''}>${esc(e.e)}${e.n?' · '+esc(e.n):''}</option>`).join('')}</select></label>
   <label class="f">Assunto<input id="eeA" value="${esc(x.assunto)}"></label>${x.assuntos.length>1?`<div class="row" style="gap:6px">${x.assuntos.map((a,j)=>`<button class="chip" data-eea="${j}">Usar: ${esc(a)}</button>`).join('')}</div>`:''}
   <label class="f">Texto<textarea id="eeT" rows="14">${esc(x.texto)}</textarea></label><label class="row" style="gap:6px"><input type="checkbox" id="eeR" ${x.arteOn?'checked':''}> Incluir a arte no corpo do e-mail</label>
   <div class="row" style="gap:6px;justify-content:flex-end"><button class="btn sm ghost" id="eeX">Cancelar</button><button class="btn sm" id="eeS">Salvar mudanças</button></div></div>`; document.body.appendChild(ov);
  ov.onclick=e=>{const t=e.target; if(t===ov||t.id==='eeX') return ov.remove(); const a=t.closest('[data-eea]'); if(a) ov.querySelector('#eeA').value=x.assuntos[+a.dataset.eea];
    if(t.id==='eeS'){x.para=[...ov.querySelector('#eeP').selectedOptions].map(o=>o.value); x.assunto=ov.querySelector('#eeA').value.trim(); x.texto=ov.querySelector('#eeT').value; x.arteOn=ov.querySelector('#eeR').checked; x.mudou=true; ov.remove(); fim&&fim()}}}
async function estArteOv(x,fim){const ov=document.createElement('div'); ov.className='ov'; const o=x.arteOpt=x.arteOpt||{}; const draw=async()=>{x.arteUrl=await estArte(x,o); ov.querySelector('#arI').src=x.arteUrl};
  ov.innerHTML=`<div class="card grid" style="max-width:520px;width:100%;max-height:94vh;overflow:auto;gap:8px"><b>🖼 Arte para ${esc(x.n)}</b><img id="arI" style="width:100%;border-radius:12px;background:#222;aspect-ratio:1">
    <label class="f">Título<input id="arT" placeholder="(automático)" value="${esc(o.titulo||'')}"></label><label class="f">Faixa de oferta (opcional)<input id="arO" placeholder="Ex.: 5% extra até sexta · frete grátis acima de R$ 1.500" value="${esc(o.oferta||'')}"></label>
    <div class="row" style="gap:6px;flex-wrap:wrap"><button class="chip" id="arU">↻ Atualizar</button><a class="btn sm ghost" id="arD" download="arte-${esc(x.cnpj)}.png">⬇ Baixar (WhatsApp)</a><button class="btn sm" id="arE">📧 Usar no e-mail</button><button class="btn sm ghost" id="arX">Fechar</button></div>
    <p class="hint" style="margin:0">Baixe para mandar no WhatsApp junto com a mensagem, ou inclua no corpo do e-mail.</p></div>`; document.body.appendChild(ov); await draw(); ov.querySelector('#arD').href=x.arteUrl;
  ov.onclick=async e=>{const t=e.target; if(t===ov||t.id==='arX'){ov.remove(); return fim&&fim()} if(t.id==='arU'){o.titulo=ov.querySelector('#arT').value.trim(); o.oferta=ov.querySelector('#arO').value.trim(); await draw(); ov.querySelector('#arD').href=x.arteUrl}
    if(t.id==='arE'){o.titulo=ov.querySelector('#arT').value.trim(); o.oferta=ov.querySelector('#arO').value.trim(); await draw(); x.arteOn=true; toast('A arte vai no corpo do e-mail'); ov.remove(); fim&&fim()}}}
