    $('#pfl').innerHTML=`<p class="hint">${L2.length} produto(s)${f.inat?' excluído(s) — continuam nos orçamentos e pedidos antigos':C.length?` · ${C.filter(p=>falta(p).length).length} com cadastro incompleto`:''}</p>`+L2.slice(0,150).map(p=>{const fl=falta(p); return `<div class="card pc" style="margin-bottom:8px;grid-template-columns:${ges?'28px ':''}56px 1fr auto">${ges?`<input type="checkbox" data-ps="${p.id}"${sel.has(p.id)?' checked':''} style="width:22px;height:22px;align-self:center" aria-label="Selecionar">`:''}<img src="${esc(p.img||'')}" alt="" loading="lazy" style="width:56px;height:56px" onerror="this.style.visibility='hidden'"><button data-pid="${p.id}" style="min-width:0;text-align:left;background:none;border:0;color:inherit;font:inherit;cursor:pointer;padding:0"><b>${esc(p.cod)}</b> <span class="d">${esc(p.descricao||'')}</span><div class="tags" style="margin-top:4px"><span class="tag">${esc(grupoOf(f.rep,p))}</span><span class="tag">EAN ${esc(p.attrs&&p.attrs.ean||'—')}</span><span class="tag">NCM ${esc(p.ncm||'—')}</span><span class="tag">IPI ${p.ipi!=null?pct(p.ipi):'—'}</span><span class="tag">múlt. ${p.mult||1}</span>${p.ca?BASE?caTag(p.ca,BASE.get(caNum(p.ca))):`<span class="tag">CA ${esc(p.ca)}</span>`:''}${fl.length&&!f.inat?`<span class="tag" style="background:#5a2a24;color:#ffd2cc">falta ${fl.join(', ')}</span>`:''}</div></button><button class="chip${cmp.has(p.id)?' on':''}" data-cmpp="${p.id}" title="Comparar lado a lado" style="align-self:center">⇆</button></div>`}).join('')+(L2.length>150?'<p class="hint">Mostrando 150. Refine a busca ou o grupo.</p>':'')+(cmp.size?`<div class="card row" style="position:sticky;bottom:calc(env(safe-area-inset-bottom,0px) + 70px);justify-content:space-between;border-color:var(--accent);z-index:5"><b>${cmp.size} para comparar</b><div class="row"><button class="chip" data-cmpx>Limpar</button><button class="btn sm" data-cmpgo${cmp.size<2?' disabled':''}>⇆ Comparar</button></div></div>`:'');
