    if(g('[data-plver]')){mais=!mais; return draw()}
    const c=g('[data-plc]'); if(c){const lista=visiveis().filter(x=>x.cnpj===c.dataset.plc||!fez(x)).map(x=>x.cnpj); box.dataset.plov='1'; return painelCliente(c.dataset.plc,lista)}
