const TUT_ROTA={home:'inicio',orc:'orc',rep:'orc',cli:'cli',tar:'tar',ped:'ped',tec:'tec'};
const visivel=el=>{if(!el) return false; const r=el.getBoundingClientRect(); return r.width>0&&r.height>0};
async function tutorial(k){const T=TUT[k]; if(!T) return; $('#umenu')&&$('#umenu').remove(); if(route!==T.r||T.c) go(T.r,T.c); await new Promise(r=>setTimeout(r,900));
  document.querySelectorAll('.tour-ov').forEach(x=>x.remove()); let i=0; const ov=document.createElement('div'); ov.className='tour-ov'; ov.innerHTML='<div class="tour-spot" hidden></div><div class="tour-card" role="dialog" aria-live="polite"></div>'; document.body.appendChild(ov);
  const spot=ov.querySelector('.tour-spot'), card=ov.querySelector('.tour-card');
  const passo=()=>{const [sel,txt]=T.p[i]; const el=sel?[...document.querySelectorAll(sel)].find(visivel):null;
    if(el){el.scrollIntoView({block:'center',behavior:'instant'}); const r=el.getBoundingClientRect(), pd=6; Object.assign(spot.style,{top:(r.top-pd)+'px',left:(r.left-pd)+'px',width:(r.width+pd*2)+'px',height:Math.min(r.height+pd*2,innerHeight*.6)+'px'}); spot.hidden=false; card.classList.toggle('topo',r.top>innerHeight*.5)} else {spot.hidden=true; card.classList.remove('topo')}
    ov.classList.toggle('escuro',!el);
    card.innerHTML=`<div class="hint">${esc(T.t)} · passo ${i+1} de ${T.p.length}</div><p style="margin:8px 0 12px;font-size:16px;line-height:1.4">${esc(txt)}</p><div class="row" style="justify-content:space-between"><button class="chip" data-tx>Fechar</button><div class="row">${i?'<button class="btn ghost sm" data-tv>‹ Voltar</button>':''}<button class="btn sm" data-tn>${i===T.p.length-1?'Concluir ✓':'Próximo ›'}</button></div></div>`};
  ov.onclick=e=>{if(e.target.closest('[data-tx]')) return ov.remove(); if(e.target.closest('[data-tv]')){i--; return passo()} if(e.target.closest('[data-tn]')){if(i===T.p.length-1){ov.remove(); return toast('Pronto! O ? no topo mostra o passo a passo de cada tela.')} i++; return passo()}};
  passo()}
function ajudaDaTela(){const k=TUT_ROTA[route]; if(k) return tutorial(k); go('ajuda')}
function ajudaView(){const m=$('#main');
  const FAQ=[['Esqueci a senha. E agora?','Fale com o gestor. Ele confere seu acesso em Mais › Equipe e acessos.'],
   ['Fiz um orçamento e sumiu.','Veja em Orçamento › Continuar (os que estão pela metade) ou Orçamento › Salvos. Pedidos também lista todos os orçamentos do mês.'],
   ['O preço não apareceu no produto.','O produto não está na tabela escolhida. Troque a tabela no passo 2 do orçamento ou avise o gestor.'],
   ['Como mando o orçamento pelo WhatsApp?','Depois de "Salvar orçamento" aparece a janela com PDF, WhatsApp, e-mail e copiar texto.'],
   ['O que são as cores nos clientes?','Tempo desde a última compra em cada fábrica: verde até 30 dias, amarelo de 31 a 90, vermelho mais de 90.'],
   ['Apareceu uma mensagem de erro.','Leia a frase e tente de novo. Se repetir, toque em "Detalhe técnico", tire um print e mande para o gestor.'],
   ['Como escolho os botões da barra de baixo?','Mais › Escolher atalhos da barra. Vale só para o seu usuário.']];
  m.innerHTML=`<div class="sec">❓ Ajuda e tutoriais</div><p class="hint">Cada tutorial abre a tela certa e mostra, passo a passo, onde tocar. O botão <b>?</b> no topo mostra o tutorial da tela em que você está.</p>
   <div class="grid tut-lista">${Object.entries(TUT).filter(([k])=>k!=='gestor'||ehGestor()).map(([k,t])=>`<button class="card tut-b" data-tut="${k}"><b>${esc(t.t)}</b><span class="hint">${esc(t.d)}</span><span class="tut-go">▶ Ver passo a passo</span></button>`).join('')}</div>
   <div class="sec" style="margin-top:22px;font-size:18px">Perguntas frequentes</div><div class="grid">${FAQ.map(([q,a])=>`<details class="card faq"><summary><b>${esc(q)}</b></summary><p style="margin:8px 0 0">${esc(a)}</p></details>`).join('')}</div>
   <p class="hint" style="margin-top:16px">Ainda com dúvida? Fale com o gestor.</p>`;
  m.onclick=e=>{const b=e.target.closest('[data-tut]'); if(b) tutorial(b.dataset.tut)}}

/* ================= lembretes de tarefas (pop-up no canto da tela) ================= */
const AVISADAS=new Set(L('avisadas')||[]);
async function verificarLembretes(){if(!sess||!navigator.onLine) return; let T=[]; try{T=await api(`tarefas?select=*&feita=eq.false&vence=eq.${hoje()}&or=(responsavel.eq.${sess.uid},responsavel.is.null)&order=hora`)}catch(e){return}
  const agora=new Date(), min=agora.getHours()*60+agora.getMinutes();
  for(const t of T){const chave=t.id+'|'+t.vence+'|'+(t.hora||''); if(AVISADAS.has(chave)) continue; let mostrar=false;
    if(t.hora){const [h,mm]=t.hora.split(':').map(Number); const tm=h*60+mm; mostrar=tm-min<=15&&tm-min>=-60} else mostrar=min>=8*60;
    if(!mostrar) continue; AVISADAS.add(chave); LS('avisadas',[...AVISADAS].slice(-300)); lembrete(t);
    try{if('Notification' in window&&Notification.permission==='granted') new Notification('Chamae · '+(t.hora?t.hora+' · ':'')+t.titulo,{body:(t.cliente||'')+(t.obs?' — '+t.obs:''),icon:'icon-192.png',tag:'t'+t.id})}catch(e){}}}
function lembrete(t){let box=$('#lembretes'); if(!box){box=document.createElement('div'); box.id='lembretes'; document.body.appendChild(box)}
  const d=document.createElement('div'); d.className='lemb'; d.innerHTML=`<div class="row" style="justify-content:space-between;flex-wrap:nowrap;align-items:flex-start"><b>🔔 ${t.hora?esc(t.hora)+' · ':'Hoje · '}${esc(t.titulo)}</b><button class="chip" data-lx style="padding:2px 8px">✕</button></div>${t.cliente?`<div class="hint">${esc(t.cliente)}</div>`:''}<div class="row" style="margin-top:6px"><button class="btn sm" data-la>Abrir</button><button class="chip" data-l15>Adiar 15 min</button></div>`;
  d.onclick=async e=>{if(e.target.closest('[data-lx]')) return d.remove(); if(e.target.closest('[data-la]')){d.remove(); return abrirTarefa(t)}
    if(e.target.closest('[data-l15]')){const n=new Date(Date.now()+15*6e4); const h=String(n.getHours()).padStart(2,'0')+':'+String(n.getMinutes()).padStart(2,'0'); try{await api(`tarefas?id=eq.${t.id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({hora:h})})}catch(_){} d.remove(); toast('Lembro de novo às '+h)}};
  box.appendChild(d); try{navigator.vibrate&&navigator.vibrate([150,80,150])}catch(e){}}
function iniciarLembretes(){verificarLembretes(); clearInterval(window._lembT); window._lembT=setInterval(verificarLembretes,60000);
  try{if('Notification' in window&&Notification.permission==='default'&&!L('notifPerg')){LS('notifPerg',1); setTimeout(()=>{if(confirm('Quer receber avisos das tarefas no horário, mesmo com o app em segundo plano?')) Notification.requestPermission()},4000)}}catch(e){}}

/* ================= Financeiro: contas a pagar/receber, comissões das NF-e e DRE (só gestores; por enquanto só no Sistema de teste) ================= */
const FIN_ON=()=>ehGestor()&&/\/chamae\//.test(location.pathname);
const FILA_PULADAS=new Set(); const FST={ab:'painel',y:new Date().getFullYear(),mo:new Date().getMonth(),st:'',dre:'comp'}; let FIN=null;
const dbr=d=>d?String(d).slice(0,10).split('-').reverse().join('/'):'';
const FDRE=[['receita','(+) Comissões de representação'],['outras_receitas','(+) Outras receitas'],['impostos','(−) Impostos sobre a receita'],['=liq','(=) Receita líquida'],['com_vend','(−) Comissão de vendedores'],['=mc','(=) Margem de contribuição'],['pessoal','(−) Despesas com pessoal'],['comercial','(−) Despesas comerciais'],['administrativa','(−) Despesas administrativas'],['=op','(=) Resultado operacional'],['financeiro','(±) Resultado financeiro'],['=res','(=) Resultado líquido'],['investimento','Investimentos (fora do resultado)'],['emprestimo','Pagamento de empréstimos (fora do resultado)'],['transferencia','Transferências entre contas (fora do resultado)'],['retirada','Retiradas dos sócios (fora do resultado)']];
const FBASE={prod:'Produtos (sem IPI/ST/frete)',prod_ipi:'Produtos + IPI',nf:'Valor total da NF'}, FQUANDO={mes_seguinte:'No mês seguinte ao faturamento',duplicata:'Na liquidação de cada título (duplicata)',faturamento:'Na data do faturamento'};
async function finDados(force){if(FIN&&!force) return FIN; const [cats,contas,regras]=await Promise.all([api('fin_categorias?select=*&order=ordem'),api('fin_contas?select=*&order=id'),api('fin_regras?select=*')]); await reps(); FIN={cats,contas,regras}; return FIN}
const finCat=id=>((FIN&&FIN.cats)||[]).find(c=>c.id===id)||{nome:id||'—',dre:''};
const finStatus=l=>l.status==='aberto'&&l.vencimento<hoje()?'atrasado':l.status;
const FTAG={previsto:'<span class="tag" style="background:#3b82f6;color:#fff">cliente pagou (previsto)</span>',inadimplente:'<span class="tag" style="background:var(--bad);color:#fff">cliente em atraso</span>',aberto:'<span class="tag">em aberto</span>',atrasado:'<span class="tag" style="background:var(--bad);color:#fff">atrasado</span>',pago:'<span class="tag" style="background:var(--ok);color:#06210f">baixado</span>',cancelado:'<span class="tag">cancelado</span>'};
const mesSel=()=>`<select id="fmo">${MESES.map((n,i)=>`<option value="${i}"${i===FST.mo?' selected':''}>${n}</option>`).join('')}</select><select id="fy">${[0,1,2,3].map(k=>new Date().getFullYear()+1-k).map(y=>`<option${y===FST.y?' selected':''}>${y}</option>`).join('')}</select>`;
async function finView(){const m=$('#main'); if(!FIN_ON()){m.innerHTML='<div class="sec">Financeiro</div><p class="hint">Somente gestores acessam o financeiro.</p>'; return}
  m.innerHTML=`<div class="row" style="justify-content:space-between"><div class="sec" style="margin:0">💰 Financeiro</div><div class="row">${FST.ab==='aj'||FST.ab==='rec'||((FST.ab==='R'||FST.ab==='P')&&!['mes','ano'].includes(FFIL.per))?'':mesSel()}</div></div>
   <div class="row" style="margin:10px 0">${[['painel','Painel'],['R','A receber'],['P','A pagar'],['nfe','Comissões / NF-e'],['dre','DRE'],['rec','🧾 Recibos'],['aj','Configurar']].map(([k,l])=>`<button class="chip${FST.ab===k?' on':''}" data-fab="${k}">${l}</button>`).join('')}</div><div id="fb"><p class="hint">Carregando…</p></div>`;
  m.onchange=e=>{if(e.target.id==='fmo'){FST.mo=+e.target.value; return finView()} if(e.target.id==='fy'){FST.y=+e.target.value; return finView()}};
  m.onclick=e=>{const a=e.target.closest('[data-fab]'); if(a){if(FST.ab!==a.dataset.fab) FFIL.cat=''; FST.ab=a.dataset.fab; FST.st=''; return finView()}};
  try{await finDados()}catch(err){$('#fb').innerHTML=`<p class="warn">Não consegui abrir o financeiro: ${esc(err.message)}</p>`; return}
  if(!m.isConnected) return; const box=$('#fb');
  return ({painel:finPainel,R:finLista,P:finLista,nfe:finNFe,dre:finDRE,rec:finRecibos,aj:finAjustes}[FST.ab]||finPainel)(box)}

/* ---------- painel ---------- */
async function finPainel(box){const de=mesIni(FST.y,FST.mo), ate=mesFim(FST.y,FST.mo), h=hoje(), em7=maisDias(7);
  const [L1,ab,nf,pg]=await Promise.all([api(`fin_lancamentos?select=*&status=neq.cancelado&vencimento=gte.${de}&vencimento=lte.${ate}`),api(`fin_lancamentos?select=*&status=eq.aberto&vencimento=lte.${em7}&order=vencimento&limit=200`),api(`fin_nfe?select=rep,comissao,v_prod,cancelada&emissao=gte.${de}&emissao=lte.${ate}`),api('fin_lancamentos?select=tipo,valor_pago,pago_em,conta_id&status=eq.pago')]);
  if(!box.isConnected) return; const s=(t,f)=>L1.filter(l=>l.tipo===t&&f(l)).reduce((a,l)=>a+(+(l.status==='pago'?l.valor_pago??l.valor:l.valor)||0),0);
  const rec=s('R',l=>l.status==='pago'), arec=s('R',l=>l.status==='aberto'), pag=s('P',l=>l.status==='pago'), apag=s('P',l=>l.status==='aberto');
  const saldo=FIN.contas.filter(c=>c.ativa).map(c=>({c,v:(+c.saldo_inicial||0)+pg.filter(l=>l.conta_id===c.id&&l.pago_em>=c.data_saldo).reduce((a,l)=>a+(l.tipo==='R'?1:-1)*(+l.valor_pago||0),0)}));
  const porRep={}; nf.filter(n=>!n.cancelada).forEach(n=>{const k=n.rep||'?'; porRep[k]=porRep[k]||{c:0,f:0,n:0}; porRep[k].c+=+n.comissao||0; porRep[k].f+=+n.v_prod||0; porRep[k].n++});
  const atr=ab.filter(l=>l.vencimento<h&&l.categoria!=='comissao'), prox=ab.filter(l=>l.vencimento>=h);
  const linha=l=>`<div class="row" style="justify-content:space-between;padding:6px 0;border-bottom:1px solid var(--line)" data-fl="${l.id}"><span>${l.tipo==='R'?'⬇️':'⬆️'} ${esc(l.descricao)} <span class="hint">${dbr(l.vencimento)}</span></span><b class="${l.tipo==='R'?'ok':'bad'}">${brl(l.valor)}</b></div>`;
  box.innerHTML=`<div class="kpis"><div class="kpi"><span class="hint">Recebido no mês</span><b class="ok" style="font-size:20px">${brl(rec)}</b><span class="hint">a receber ${brl(arec)}</span></div>
    <div class="kpi"><span class="hint">Pago no mês</span><b class="bad" style="font-size:20px">${brl(pag)}</b><span class="hint">a pagar ${brl(apag)}</span></div>
    <div class="kpi"><span class="hint">Resultado previsto do mês</span><b style="font-size:20px">${brl(rec+arec-pag-apag)}</b><span class="hint">realizado ${brl(rec-pag)}</span></div>
    <div class="kpi"><span class="hint">Saldo em contas</span><b style="font-size:20px">${saldo.length?brl(saldo.reduce((a,x)=>a+x.v,0)):'—'}</b><span class="hint">${saldo.length?saldo.map(x=>esc(x.c.nome)+' '+brl(x.v)).join(' · '):'cadastre em Configurar'}</span></div></div>
   <div class="dgrid" style="margin-top:12px"><div class="card"><b>⚠️ Atrasados (${atr.length})</b>${atr.map(linha).join('')||'<p class="hint">Nada atrasado.</p>'}</div>
    <div class="card"><b>📅 Vencem nos próximos 7 dias (${prox.length})</b>${prox.map(linha).join('')||'<p class="hint">Nada vencendo.</p>'}</div>
    <div class="card"><b>🏭 Comissões faturadas no mês</b><table class="t" style="margin-top:6px"><tr><th>Representada</th><th class="n">NFs</th><th class="n">Faturado</th><th class="n">Comissão</th></tr>${Object.entries(porRep).sort((a,b)=>b[1].c-a[1].c).map(([k,v])=>`<tr><td>${esc(repName(k))}</td><td class="n">${v.n}</td><td class="n">${brl(v.f)}</td><td class="n">${brl(v.c)}</td></tr>`).join('')||'<tr><td colspan="4" class="hint">Nenhuma NF-e importada neste mês.</td></tr>'}</table></div></div>`;
  box.onclick=e=>{const r=e.target.closest('[data-fl]'); if(r) finForm([...ab,...L1].find(x=>x.id==r.dataset.fl))}
  finPECard(box);
  api('fin_xml_fila?select=id&processado=eq.false&limit=200').then(f=>{f=f.filter(x=>!FILA_PULADAS.has(x.id)); if(f.length&&box.isConnected) box.insertAdjacentHTML('afterbegin',`<button class="btn" data-fab="nfe" style="width:100%;margin-bottom:12px">📧 ${f.length} NF-e nova(s) do e-mail — importar agora</button>`)}).catch(()=>{})}

/* ---------- ponto de equilíbrio: quanto a Chamaê precisa receber de comissão (e as fábricas faturarem) para cobrir as despesas fixas ---------- */
const PE_FIXO=['pessoal','comercial','administrativa','financeiro'];
async function finPECfg(){const r=await api('fin_config?select=valor&chave=eq.pe').catch(()=>[]); const c=Object.assign({meses:3,aliquota:null,vend:0,emprestimos:true,excluir:null},(r[0]||{}).valor||{});
  if(!Array.isArray(c.excluir)) c.excluir=FIN.cats.filter(x=>x.tipo==='P'&&/rescis/i.test(x.nome)).map(x=>x.id); return c}
async function finPE(){const c=await finPECfg(), hj=new Date(), y=hj.getFullYear(), mo=hj.getMonth(); const ini=ymd(new Date(Date.UTC(y,mo-c.meses,1))), fim=ymd(new Date(Date.UTC(y,mo,0)));
  const [L1,N,P]=await Promise.all([api(`fin_lancamentos?select=categoria,valor,competencia,vencimento&tipo=eq.P&status=neq.cancelado&competencia=gte.${ini}&competencia=lte.${fim}`),
    api(`fin_nfe?select=v_prod,comissao,emissao&cancelada=eq.false&emissao=gte.${maisDias(-120)}`),api(`pedidos?select=valor&data=gte.${mesIni(y,mo)}&data=lte.${mesFim(y,mo)}&or=(status.like.APROVADO*,status.eq.finalizado)`).catch(()=>[])]);
  const meses=new Set(L1.map(l=>(l.competencia||l.vencimento).slice(0,7))).size||1; const grupos={};
  const entra=d=>PE_FIXO.includes(d)||(d==='impostos'&&c.aliquota==null)||(d==='emprestimo'&&c.emprestimos);
  L1.forEach(l=>{if(c.excluir.includes(l.categoria)) return; const d=finCat(l.categoria).dre||'administrativa'; if(!entra(d)) return; grupos[d]=(grupos[d]||0)+(+l.valor||0)/meses});
  const cf=Object.values(grupos).reduce((a,v)=>a+v,0), varp=((+c.aliquota||0)+(+c.vend||0))/100; const pe=varp<1?cf/(1-varp):0;
  const fp=N.reduce((a,n)=>a+(+n.v_prod||0),0), cm=N.reduce((a,n)=>a+(+n.comissao||0),0); const regs=(FIN.regras||[]).filter(r=>r.pct!=null&&!r.rep.startsWith('_'));
  const taxa=fp>0&&cm>0?cm/fp:(regs.length?regs.reduce((a,r)=>a+ +r.pct,0)/regs.length/100:0.03);
  const mesN=N.filter(n=>n.emissao>=mesIni(y,mo)); const fatMes=mesN.reduce((a,n)=>a+(+n.v_prod||0),0), comMes=mesN.reduce((a,n)=>a+(+n.comissao||0),0), vendMes=P.reduce((a,p)=>a+(+p.valor||0),0);
  let du=0; for(let d=new Date(hj); d.getMonth()===mo; d.setDate(d.getDate()+1)) if(d.getDay()%6) du++;
  return {c,meses,grupos,cf,varp,pe,taxa,peFat:taxa?pe/taxa:0,fatMes,comMes,vendMes,du,ini,fim}}
async function finPECard(box){let R; try{R=await finPE()}catch(e){return} if(!box.isConnected||!R.cf) return;
  const barra=(v,meta,cor)=>`<div class="bt" style="height:12px;margin:4px 0 2px"><div style="height:100%;width:${Math.min(100,meta?v/meta*100:0).toFixed(1)}%;background:${cor};border-radius:6px"></div></div>`;
  const falta=Math.max(0,R.peFat-R.vendMes); const nomes={pessoal:'Pessoal',comercial:'Comerciais',administrativa:'Administrativas',financeiro:'Financeiras',impostos:'Impostos (pagos)',emprestimo:'Parcelas de empréstimos'};
  box.insertAdjacentHTML('beforeend',`<div class="card" style="margin-top:12px"><div class="row" style="justify-content:space-between"><b>⚖️ Ponto de equilíbrio da Chamaê</b><button class="chip" data-fab="aj">ajustar</button></div>
   <p class="hint" style="margin:4px 0 10px">Média das despesas de ${dbr(R.ini).slice(3)} a ${dbr(R.fim).slice(3)} (${R.meses} ${R.meses>1?'meses':'mês'})${R.c.excluir.length?', sem as despesas não recorrentes marcadas':''}. Comissão média ${pct(R.taxa*100)} sobre o faturado${R.varp?`, impostos e vendedores ${pct(R.varp*100)} da comissão`:''}.</p>
   <div class="kpis"><div class="kpi"><span class="hint">Despesas fixas por mês</span><b style="font-size:20px">${brl(R.cf)}</b></div><div class="kpi"><span class="hint">Comissão mínima por mês</span><b style="font-size:20px">${brl(R.pe)}</b></div>
    <div class="kpi"><span class="hint">As fábricas precisam faturar</span><b style="font-size:20px;color:var(--accent)">${brl(R.peFat)}</b></div><div class="kpi"><span class="hint">Faltam vender neste mês</span><b class="${falta?'bad':'ok'}" style="font-size:20px">${falta?brl(falta):'✓ atingido'}</b><span class="hint">${falta&&R.du?brl(falta/R.du)+' por dia útil ('+R.du+' dias)':''}</span></div></div>
   <div style="margin-top:10px"><div class="row" style="justify-content:space-between"><span>Vendido no mês (pedidos aprovados)</span><b>${brl(R.vendMes)} · ${pct(R.peFat?R.vendMes/R.peFat*100:0)}</b></div>${barra(R.vendMes,R.peFat,'var(--accent)')}
    <div class="row" style="justify-content:space-between;margin-top:6px"><span>Faturado no mês (NF-e) · comissão ${brl(R.comMes)}</span><b>${brl(R.fatMes)} · ${pct(R.peFat?R.fatMes/R.peFat*100:0)}</b></div>${barra(R.fatMes,R.peFat,'var(--ok)')}</div>
   <details style="margin-top:8px"><summary class="hint" style="cursor:pointer">Despesas fixas consideradas</summary><table class="t" style="margin-top:6px">${Object.entries(R.grupos).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<tr><td>${esc(nomes[k]||k)}</td><td class="n">${brl(v)}</td></tr>`).join('')}</table></details></div>`)}

/* ---------- contas a receber / a pagar ---------- */
/* filtros de contas a pagar/receber (pedido do Victor 03/11/2026): busca por nome/descrição, período (mês, semana, 30 dias, ano, tudo ou de/até) por vencimento, pagamento ou competência, categoria, representada e conta */
const FFIL={q:'',per:'mes',dt:'vencimento',de:'',ate:'',cat:'',rep:'',conta:''};
const FPER=[['mes','Mês escolhido'],['sem','Esta semana'],['30','Próximos 30 dias'],['ano','Ano inteiro'],['tudo','Todo o período'],['custom','Escolher datas…']];
const FDT=[['vencimento','Vencimento'],['pago_em','Pagamento'],['competencia','Competência']];
function finPeriodo(){const f=FFIL, h=hoje(); if(f.per==='sem'){const d=new Date(h+'T12:00:00'), w=(d.getDay()+6)%7; return [ymd(new Date(Date.UTC(d.getFullYear(),d.getMonth(),d.getDate()-w))),ymd(new Date(Date.UTC(d.getFullYear(),d.getMonth(),d.getDate()-w+6)))]}
  if(f.per==='30') return [h,maisDias(30)]; if(f.per==='ano') return [`${FST.y}-01-01`,`${FST.y}-12-31`]; if(f.per==='tudo') return ['',''];
  if(f.per==='custom') return [f.de||'',f.ate||'']; return [mesIni(FST.y,FST.mo),mesFim(FST.y,FST.mo)]}
const finPerTxt=()=>{const [a,b]=finPeriodo(); if(FFIL.per==='mes') return `${MESES[FST.mo]} de ${FST.y}`; if(FFIL.per==='tudo') return 'todo o período'; if(FFIL.per==='ano') return 'o ano de '+FST.y; return a&&b?`${dbr(a)} a ${dbr(b)}`:a?'a partir de '+dbr(a):b?'até '+dbr(b):'todo o período'};
const finFilAtivos=()=>['q','cat','rep','conta'].filter(k=>FFIL[k]).length+(FFIL.per!=='mes'?1:0)+(FFIL.dt!=='vencimento'?1:0);
async function finLista(box){const tp=FST.ab, h=hoje(); const [de,ate]=finPeriodo(), dc=FFIL.dt;
  box.innerHTML='<p class="hint">Carregando…</p>';
  let L1=await apiAll(`fin_lancamentos?select=*&tipo=eq.${tp}${de?`&${dc}=gte.${de}`:''}${ate?`&${dc}=lte.${ate}`:''}${dc==='vencimento'?'':`&${dc}=not.is.null`}&order=${dc==='vencimento'?'vencimento':dc+',vencimento'},id`); if(!box.isConnected) return;
  /* comissão: depois do vencimento do título o cliente provavelmente pagou, a menos que a fábrica tenha mandado aviso de boleto em aberto daquela NF */
  const AV={}; if(tp==='R') (await api(`fin_avisos?select=nfs,assunto,recebido_em&recebido_em=gte.${maisDias(-200)}&order=recebido_em`).catch(()=>[])).forEach(a=>(a.nfs||[]).forEach(n=>AV[n]=a));
  const nfDe=l=>((l.descricao||'').match(/NF (\d+)/)||[])[1], avDe=l=>{const a=AV[String(nfDe(l)||'').replace(/^0+/,'')]; return a&&String(a.recebido_em).slice(0,10)>=l.vencimento?a:null};
  const finStatus=l=>{const s0=l.status==='aberto'&&l.vencimento<h?'atrasado':l.status; if(l.categoria!=='comissao'||l.status!=='aberto') return s0; if(avDe(l)) return 'inadimplente'; return l.vencimento<h?'previsto':'aberto'};
  const cats=FIN.cats.filter(c=>c.tipo===tp&&(c.ativa||L1.some(l=>l.categoria===c.id))), contas=FIN.contas.filter(c=>c.ativa||L1.some(l=>l.conta_id===c.id)), repsL=(REPS||[]).filter(r=>r.ativa||L1.some(l=>l.rep===r.id));
  const sel=(k,lbl,todos,ops)=>`<label class="f">${lbl}<select data-ff="${k}"><option value="">${todos}</option>${ops.map(([v,n])=>`<option value="${esc(v)}"${String(FFIL[k])===String(v)?' selected':''}>${esc(n)}</option>`).join('')}</select></label>`;
    box.innerHTML=`<div class="ffil card">
    <div class="ffil-top"><label class="f ffil-q">Buscar<input type="search" data-ff="q" autocomplete="off" value="${esc(FFIL.q)}" placeholder="${tp==='R'?'nome do cliente, fábrica, NF, descrição…':'fornecedor, descrição, observação…'}"></label>
     <label class="f">Período<select data-ff="per">${FPER.map(([k,n])=>`<option value="${k}"${FFIL.per===k?' selected':''}>${n}</option>`).join('')}</select></label>
     <label class="f">Pela data de<select data-ff="dt">${FDT.map(([k,n])=>`<option value="${k}"${FFIL.dt===k?' selected':''}>${n}</option>`).join('')}</select></label>
     ${FFIL.per==='custom'?`<label class="f">De<input type="date" data-ff="de" value="${FFIL.de}"></label><label class="f">Até<input type="date" data-ff="ate" value="${FFIL.ate}"></label>`:''}</div>
    <details class="ffil-mais"${FFIL.cat||FFIL.rep||FFIL.conta?' open':''}><summary>Mais filtros${FFIL.cat||FFIL.rep||FFIL.conta?` <span class="tag">${['cat','rep','conta'].filter(k=>FFIL[k]).length}</span>`:''}</summary><div class="ffil-top">
     ${sel('cat','Categoria','Todas',cats.map(c=>[c.id,c.grupo?c.grupo+' › '+c.nome:c.nome]))}${sel('rep','Representada','Todas',repsL.map(r=>[r.id,r.nome]))}${sel('conta','Conta bancária','Todas',contas.map(c=>[c.id,c.nome]))}</div></details>
    <div class="ffil-res"><span class="hint" id="fresumo"></span><button class="chip" id="flimpa" hidden></button></div></div>
   <div id="fres"></div>`;
  const res=$('#fres');
  const render=()=>{const q=norm(FFIL.q).trim(), qd=q.replace(/\D/g,'');
    const B=L1.filter(l=>(!FFIL.cat||l.categoria===FFIL.cat)&&(!FFIL.rep||l.rep===FFIL.rep)&&(!FFIL.conta||String(l.conta_id)===String(FFIL.conta))&&(!q||q.split(/\s+/).every(w=>norm([l.descricao,l.cliente,l.obs,l.parcela,finCat(l.categoria).nome,l.rep?repName(l.rep):''].join(' ')).includes(w))||(qd.length>=4&&String(l.cnpj||'').includes(qd))));
    const tot=k=>B.filter(l=>finStatus(l)===k).reduce((a,l)=>a+(+(k==='pago'?l.valor_pago??l.valor:l.valor)||0),0);
    const F=FST.st?B.filter(l=>finStatus(l)===FST.st):B.filter(l=>l.status!=='cancelado'); res._F=F; res._fs=finStatus;
    const nA=finFilAtivos(), lb=$('#flimpa'); lb.hidden=!nA; lb.textContent=`✕ Limpar filtros (${nA})`; const sm=F.reduce((a,l)=>a+(+l.valor||0),0); $('#fresumo').textContent=`${F.length} lançamento${F.length===1?'':'s'} · ${brl(sm)} · ${FDT.find(x=>x[0]===FFIL.dt)[1].toLowerCase()} em ${finPerTxt()}`;
    res.innerHTML=`<div class="kpis"><div class="kpi"><span class="hint">${tp==='R'?'Aguardando o cliente pagar':'Em aberto'}</span><b style="font-size:20px">${brl(tot('aberto'))}</b></div>${tp==='R'?`<div class="kpi"><span class="hint">Cliente pagou (previsto), falta a fábrica repassar</span><b style="font-size:20px;color:#3b82f6">${brl(tot('previsto'))}</b></div><div class="kpi"><span class="hint">Cliente em atraso (aviso da fábrica)</span><b class="bad" style="font-size:20px">${brl(tot('inadimplente')+tot('atrasado'))}</b></div>`:`<div class="kpi"><span class="hint">Atrasado</span><b class="bad" style="font-size:20px">${brl(tot('atrasado'))}</b></div>`}<div class="kpi"><span class="hint">${tp==='R'?'Recebido':'Pago'}</span><b class="ok" style="font-size:20px">${brl(tot('pago'))}</b></div>${tp==='R'?'':`<div class="kpi"><span class="hint">Total ${FFIL.per==='mes'?'do mês':'do período'}</span><b style="font-size:20px">${brl(tot('aberto')+tot('atrasado')+tot('pago'))}</b></div>`}</div>
   <div class="row" style="margin:10px 0">${(tp==='R'?[['','Todos'],['aberto','Aguardando cliente'],['previsto','Cliente pagou (previsto)'],['inadimplente','Cliente em atraso'],['atrasado','Atrasados'],['pago','Recebidos'],['cancelado','Cancelados']]:[['','Todos'],['aberto','Em aberto'],['atrasado','Atrasados'],['pago','Pagos'],['cancelado','Cancelados']]).map(([k,l])=>`<button class="chip${FST.st===k?' on':''}" data-fst="${k}">${l}</button>`).join('')}<span style="flex:1"></span>${tp==='R'&&B.some(l=>finStatus(l)==='previsto')?'<button class="btn ghost sm" id="fprev">✓ Fábrica pagou as previstas</button>':''}<button class="btn ghost sm" id="fxls">Excel</button>${tp==='P'?'<button class="btn ghost sm" id="fca">⬆ Importar Conta Azul (PDF/Excel)</button><input id="fcaf" type="file" accept=".pdf,.xlsx,.xls,.csv" multiple hidden>':''}<button class="btn sm" id="fnovo">+ ${tp==='R'?'Conta a receber':'Conta a pagar'}</button></div>
   <div style="overflow-x:auto"><table class="t"><tr><th>Vencimento</th><th>Descrição</th><th>Categoria</th><th class="n">Valor</th><th>Situação</th><th></th></tr>
   ${F.map(l=>`<tr data-fl="${l.id}" style="cursor:pointer;border-top:1px solid var(--line)"><td>${dbr(l.vencimento)}${FFIL.dt==='competencia'?`<div class="hint">comp. ${dbr(l.competencia).slice(3)}</div>`:''}</td><td>${esc(l.descricao)}${l.parcela?` <span class="hint">${esc(l.parcela)}</span>`:''}${l.cliente?`<div class="hint">${esc(l.cliente)}</div>`:''}</td><td class="hint">${esc(finCat(l.categoria).nome)}${l.rep?`<div>${esc(repName(l.rep))}</div>`:''}</td><td class="n"><b>${brl(l.valor)}</b>${l.status==='pago'&&+l.valor_pago!==+l.valor?`<div class="hint">baixado ${brl(l.valor_pago)}</div>`:''}</td><td>${FTAG[finStatus(l)]}${l.pago_em?`<div class="hint">${dbr(l.pago_em)}</div>`:''}${finStatus(l)==='inadimplente'?`<div class="hint" title="${esc(avDe(l).assunto)}">aviso ${dbr(avDe(l).recebido_em)}</div>`:''}</td><td class="n">${l.status==='aberto'?`<button class="btn sm" data-fbx="${l.id}">✓ ${tp==='R'?'Recebido':'Pago'}</button>`:''}${l.status==='pago'?`<button class="chip" data-frc="${l.id}" title="Emitir recibo deste lançamento">🧾 Recibo</button>`:''}</td></tr>`).join('')||`<tr><td colspan="6" class="hint" style="padding:12px 0">${finFilAtivos()||FST.st?'Nenhum lançamento com esses filtros.':'Nenhum lançamento neste mês.'}</td></tr>`}</table></div>`;
    const caf=$('#fcaf'); if(caf) caf.onchange=()=>{if(caf.files.length) finImportarCA([...caf.files])}};
  render();
  let tq; box.oninput=e=>{const k=e.target.dataset.ff; if(k!=='q') return; clearTimeout(tq); tq=setTimeout(()=>{FFIL.q=e.target.value; render()},200)};
  box.onchange=e=>{const k=e.target.dataset.ff; if(!k||k==='q') return; FFIL[k]=e.target.value; if(k==='per'&&FFIL.per==='custom'&&!FFIL.de){FFIL.de=mesIni(FST.y,FST.mo); FFIL.ate=mesFim(FST.y,FST.mo)} if(k==='per') return finView(); finLista(box)};
  box.onclick=async e=>{const t=e.target; if(t.id==='flimpa'){Object.assign(FFIL,{q:'',per:'mes',dt:'vencimento',de:'',ate:'',cat:'',rep:'',conta:''}); FST.st=''; return finView()}
    const s=t.closest('[data-fst]'); if(s){FST.st=s.dataset.fst; return render()} if(t.id==='fnovo') return finForm({tipo:tp}); if(t.id==='fca') return $('#fcaf').click();
    const F=res._F||[];
    if(t.id==='fxls'){await loadXLSX(); const ws=XLSX.utils.aoa_to_sheet([['Vencimento','Descrição','Parcela','Categoria','Representada','Cliente','Valor','Situação','Baixa','Valor baixado'],...F.map(l=>[dbr(l.vencimento),l.descricao,l.parcela||'',finCat(l.categoria).nome,l.rep?repName(l.rep):'',l.cliente||'',+l.valor,finStatus(l),dbr(l.pago_em),l.valor_pago==null?'':+l.valor_pago])]); const wb=XLSX.utils.book_new(); XLSX.utils.book_append_sheet(wb,ws,tp==='R'?'A receber':'A pagar'); return XLSX.writeFile(wb,`${tp==='R'?'Contas_a_receber':'Contas_a_pagar'}_${finPerTxt().replace(/[^\wÀ-ú]+/g,'_')}.xlsx`)}
    if(t.id==='fprev'){const P=F.filter(l=>finStatus(l)==='previsto'); if(!P.length) return toast('Nenhuma prevista na lista filtrada'); if(!confirm(`Dar baixa em ${P.length} comissão(ões) prevista(s), total ${brl(P.reduce((a,l)=>a+(+l.valor||0),0))}, como recebidas hoje?`)) return;
      try{for(const l of P) await api(`fin_lancamentos?id=eq.${l.id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({status:'pago',valor_pago:l.valor,pago_em:hoje()})}); toast('Baixas registradas'); return finLista(box)}catch(err){return toast('Erro: '+err.message)}}
    const rc=t.closest('[data-frc]'); if(rc) return recForm(recDeLanc(L1.find(x=>x.id==rc.dataset.frc)));
    const b=t.closest('[data-fbx]'); if(b){const l=L1.find(x=>x.id==b.dataset.fbx); return finBaixa(l)}
    const r=t.closest('[data-fl]'); if(r) return finForm(L1.find(x=>x.id==r.dataset.fl))}}
async function finBaixa(l){const fv=await formulario('Registrar baixa',[{k:'v',l:`Valor ${l.tipo==='R'?'recebido':'pago'} (R$)`,val:String(l.valor).replace('.',','),mode:'decimal',req:true},{k:'d',l:'Data',type:'date',val:hoje(),req:true}],'Registrar'); if(!fv) return; const vp=lerNumBR(fv.v); if(!(vp>=0)) return toast('Valor inválido'); const pe=fv.d||hoje();
  const conta=FIN.contas.filter(c=>c.ativa); let cid=l.conta_id||null; if(!cid&&conta.length===1) cid=conta[0].id;
  try{await api(`fin_lancamentos?id=eq.${l.id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({status:'pago',valor_pago:vp,pago_em:pe,conta_id:cid})}); toast('Baixa registrada'); finView()}catch(err){toast('Erro: '+err.message)}}
async function finForm(l0){if(!l0) return; const l={tipo:'P',status:'aberto',vencimento:hoje(),...l0}, novo=!l.id, tp=l.tipo;
  const ov=document.createElement('div'); ov.className='ov'; const cats=FIN.cats.filter(c=>c.ativa&&c.tipo===tp);
  ov.innerHTML=`<div class="sh grid"><b style="font-size:18px">${novo?'Nova':'Editar'} conta a ${tp==='R'?'receber':'pagar'}</b>
   ${l.nfe_id?'<p class="hint">Gerada pela NF-e (comissão). Valor e vencimento podem ser ajustados aqui.</p>':''}
   <label class="f">Descrição<input id="fd" value="${esc(l.descricao||'')}" placeholder="${tp==='R'?'ex.: Comissão Marcon setembro':'ex.: Aluguel do escritório'}"></label>
   <div class="r2"><label class="f">Categoria<select id="fc">${cats.map(c=>`<option value="${c.id}"${c.id===l.categoria?' selected':''}>${esc(c.grupo)} › ${esc(c.nome)}</option>`).join('')}</select></label>
    <label class="f">Conta bancária<select id="fco"><option value="">—</option>${FIN.contas.filter(c=>c.ativa||c.id===l.conta_id).map(c=>`<option value="${c.id}"${c.id===l.conta_id?' selected':''}>${esc(c.nome)}</option>`).join('')}</select></label></div>
   <div class="r2"><label class="f">Valor (R$)<input id="fv" inputmode="decimal" value="${l.valor!=null?String(l.valor).replace('.',','):''}"></label><label class="f">Vencimento<input id="fve" type="date" value="${l.vencimento}"></label></div>
   <div class="r2"><label class="f">Competência (mês da DRE)<input id="fcp" type="month" value="${(l.competencia||l.vencimento).slice(0,7)}"></label><label class="f">Representada (opcional)<select id="frp"><option value="">—</option>${(REPS||[]).map(r=>`<option value="${r.id}"${r.id===l.rep?' selected':''}>${esc(r.nome)}</option>`).join('')}</select></label></div>
   ${novo?`<div class="r2"><label class="f">Repetir todo mês por (meses)<input id="frep" type="number" min="1" max="60" value="1"></label><label class="f">ou parcelar em (vezes, divide o valor)<input id="fpar" type="number" min="1" max="60" value="1"></label></div>`:''}
   ${l.status==='pago'?`<div class="r2"><label class="f">Baixado em<input id="fpe" type="date" value="${l.pago_em||''}"></label><label class="f">Valor baixado<input id="fvp" inputmode="decimal" value="${String(l.valor_pago??'').replace('.',',')}"></label></div>`:''}
   <label class="f">Observação<textarea id="fob" rows="2">${esc(l.obs||'')}</textarea></label>
   <div class="row"><button class="btn" id="fsv">Salvar</button>${!novo&&l.status==='aberto'?`<button class="btn ghost" id="fbx">✓ Baixar</button>`:''}${!novo&&l.status==='pago'?`<button class="btn ghost" id="frc">🧾 Emitir recibo</button><button class="btn ghost" id="fest">Desfazer baixa</button>`:''}${!novo&&l.status!=='cancelado'?`<button class="btn ghost" id="fcan">Cancelar lançamento</button>`:''}${!novo?`<button class="btn ghost" id="fdel" style="color:var(--bad)">Excluir</button>`:''}<button class="btn ghost" data-x>Fechar</button></div></div>`;
  document.body.appendChild(ov); const q=s=>ov.querySelector(s); const fim=m_=>{ov.remove(); toast(m_); finView()};
  let cpMexeu=false; q('#fcp').oninput=()=>cpMexeu=true; q('#fve').onchange=()=>{if(!cpMexeu&&q('#fve').value) q('#fcp').value=q('#fve').value.slice(0,7)};
  ov.onclick=async e=>{const t=e.target; if(t===ov||t.closest('[data-x]')) return ov.remove();
    try{if(t.id==='fbx'){ov.remove(); return finBaixa(l)} if(t.id==='frc'){ov.remove(); return recForm(recDeLanc(l))}
      if(t.id==='fest'){await api(`fin_lancamentos?id=eq.${l.id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({status:'aberto',pago_em:null,valor_pago:null})}); return fim('Baixa desfeita')}
      if(t.id==='fcan'){await api(`fin_lancamentos?id=eq.${l.id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({status:'cancelado'})}); return fim('Lançamento cancelado')}
      if(t.id==='fdel'){if(!confirm('Excluir este lançamento?'+(l.grupo?' (só este; os outros meses/parcelas continuam)':''))) return; await api(`fin_lancamentos?id=eq.${l.id}`,{method:'DELETE'}); return fim('Excluído')}
      if(t.id!=='fsv') return; const desc=q('#fd').value.trim(), val=lerNumBR(q('#fv').value), ve=q('#fve').value; if(!desc||!(val>0)||!ve) return toast('Preencha descrição, valor e vencimento');
      const base={tipo:tp,descricao:desc,categoria:q('#fc').value||null,valor:val,vencimento:ve,competencia:(q('#fcp').value||ve.slice(0,7))+'-01',conta_id:+q('#fco').value||null,rep:q('#frp').value||null,obs:q('#fob').value.trim()||null};
      if(!novo){if(l.status==='pago'){base.pago_em=q('#fpe').value||l.pago_em; base.valor_pago=lerNumBR(q('#fvp').value)}
        await api(`fin_lancamentos?id=eq.${l.id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify(base)}); return fim('Salvo')}
      const rep_=Math.max(1,+q('#frep').value||1), par=Math.max(1,+q('#fpar').value||1), n=Math.max(rep_,par), grupo=n>1?'g'+Date.now().toString(36):null;
      const addM=(d,k)=>{const [y,mo,dd]=d.split('-').map(Number); const ult=new Date(Date.UTC(y,mo-1+k+1,0)).getUTCDate(); return ymd(new Date(Date.UTC(y,mo-1+k,Math.min(dd,ult))))};
      const vp=par>1?Math.round(val/par*100)/100:val; const rows=Array.from({length:n},(_,k)=>({...base,valor:par>1&&k===n-1?Math.round((val-vp*(n-1))*100)/100:vp,vencimento:addM(ve,k),competencia:addM(base.competencia,k).slice(0,8)+'01',grupo,parcela:par>1?`${k+1}/${n}`:null}));
      await api('fin_lancamentos',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify(rows)}); fim(n>1?`${n} lançamentos criados`:'Lançamento criado')}catch(err){toast('Erro: '+err.message)}}}

/* ---------- recibos (pedido do Victor 03/11/2026): o financeiro preenche, o Sistema gera o PDF no padrão do orçamento. Guardados em fin_config, chave 'recibo:000001' (sem tabela nova) ---------- */
const REC_CFG0={razao:'Chamae Representações Comerciais',cnpj:'18.308.187/0001-50',end:'',cidade:'',tel:'(16) 99793-7802',email:'victor.crepaldi@chamae.com.br',ass:'',ass_doc:''};
const REC_FORMAS=['PIX','Dinheiro','Transferência bancária','Boleto','Cheque','Cartão','Depósito','Compensação de comissão'];
const RST={q:''};
async function recCfg(){const r=await api('fin_config?select=valor&chave=eq.recibo_cfg').catch(()=>[]); return Object.assign({},REC_CFG0,(r[0]||{}).valor||{})}
async function recLista(){return (await apiAll('fin_config?select=chave,valor&chave=like.recibo:*&order=chave.desc').catch(()=>[])).map(x=>x.valor).filter(Boolean)}
const recNum=n=>String(n).padStart(4,'0');
function extenso(v){v=Math.round((+v||0)*100); const re=Math.floor(v/100), ce=v%100;
  const U=['','um','dois','três','quatro','cinco','seis','sete','oito','nove','dez','onze','doze','treze','quatorze','quinze','dezesseis','dezessete','dezoito','dezenove'], D=['','','vinte','trinta','quarenta','cinquenta','sessenta','setenta','oitenta','noventa'], C=['','cento','duzentos','trezentos','quatrocentos','quinhentos','seiscentos','setecentos','oitocentos','novecentos'];
  const ate999=n=>{if(n===100) return 'cem'; const c=Math.floor(n/100), r=n%100, p=[]; if(c) p.push(C[c]); if(r<20){if(r) p.push(U[r])} else {p.push(D[Math.floor(r/10)]+(r%10?' e '+U[r%10]:''))} return p.join(' e ')};
  const grupos=n=>{if(!n) return 'zero'; const G=[['',''],['mil','mil'],['milhão','milhões'],['bilhão','bilhões']]; const ps=[]; let i=0; const gs=[]; while(n>0){gs.push(n%1000); n=Math.floor(n/1000)}
    for(i=gs.length-1;i>=0;i--){const g=gs[i]; if(!g) continue; let t=i===1&&g===1?'mil':ate999(g)+(i?' '+(g===1?G[i][0]:G[i][1]):''); ps.push({t,g,i})}
    return ps.map((p,k)=>{if(!k) return p.t; const last=k===ps.length-1; return (last&&(p.g<100||p.g%100===0)?' e ':' ')+p.t}).join('')};
  const out=[]; if(re) out.push(grupos(re)+(re===1?' real':(re>=1e6&&re%1e6===0?' de reais':' reais'))); if(ce) out.push(grupos(ce)+(ce===1?' centavo':' centavos')); return out.join(' e ')||'zero reais'}
const recDataLonga=d=>d?new Date(d+'T12:00:00').toLocaleDateString('pt-BR',{day:'numeric',month:'long',year:'numeric'}):'';
const ehChamae=(nome,cfg)=>!!nome&&norm(nome)===norm(cfg.razao);
function recDeLanc(l){if(!l) return null; const ref=[l.descricao,l.parcela?'parcela '+l.parcela:''].filter(Boolean).join(' · '), outro=l.cliente||(l.rep?repName(l.rep):'');
  return l.tipo==='R'?{tipo:'R',pag:outro,pag_doc:l.cnpj?fmtCnpj(l.cnpj):'',valor:+(l.valor_pago??l.valor),data:l.pago_em||hoje(),ref,lanc:l.id}:{tipo:'P',rec:outro,rec_doc:l.cnpj?fmtCnpj(l.cnpj):'',valor:+(l.valor_pago??l.valor),data:l.pago_em||hoje(),ref,lanc:l.id}}

async function finRecibos(box){box.innerHTML='<p class="hint">Carregando recibos…</p>'; const [R,cfg]=await Promise.all([recLista(),recCfg()]); if(!box.isConnected) return;
  box.innerHTML=`<div class="ffil card"><div class="ffil-top rec-top"><label class="f ffil-q">Buscar recibo<input type="search" id="rq" autocomplete="off" value="${esc(RST.q)}" placeholder="nome, CPF/CNPJ, referente a, nº…"></label>
    <div class="row" style="align-self:end;gap:8px"><button class="btn ghost sm" id="rcfg">⚙ Dados da Chamae</button><button class="btn sm" id="rnovo">+ Novo recibo</button></div></div>
    ${cfg.cidade?'':'<p class="hint" style="margin:8px 0 0">Dica: em <b>⚙ Dados da Chamae</b> coloque a cidade e quem assina; assim o recibo já vem preenchido.</p>'}</div><div id="rres"></div>`;
  const res=$('#rres');
  const render=()=>{const q=norm(RST.q).trim(); const F=R.filter(r=>!q||q.split(/\s+/).every(w=>norm([recNum(r.n),r.pag,r.pag_doc,r.rec,r.rec_doc,r.ref,r.forma,brl(r.valor)].join(' ')).includes(w)));
    res.innerHTML=`<div class="hint" style="margin:10px 0 6px">${F.length} recibo${F.length===1?'':'s'}${F.length?' · '+brl(F.filter(r=>!r.cancelado).reduce((a,r)=>a+(+r.valor||0),0)):''}</div>
     <div style="overflow-x:auto"><table class="t"><tr><th>Nº</th><th>Data</th><th>Quem pagou → quem recebeu</th><th>Referente a</th><th class="n">Valor</th><th></th></tr>
     ${F.map(r=>`<tr style="border-top:1px solid var(--line)${r.cancelado?';opacity:.55':''}"><td><b>${recNum(r.n)}</b></td><td>${dbr(r.data)}</td><td>${esc(r.pag||'—')} <span class="hint">→</span> ${esc(r.rec||'—')}${r.cancelado?' <span class="tag">cancelado</span>':''}</td><td class="hint">${esc(String(r.ref||'').slice(0,80))}</td><td class="n"><b>${brl(r.valor)}</b></td>
       <td class="n" style="white-space:nowrap"><button class="chip" data-rpdf="${r.n}">📄 PDF</button> <button class="chip" data-red="${r.n}" title="Editar">✎</button></td></tr>`).join('')||`<tr><td colspan="6" class="hint" style="padding:14px 0">${R.length?'Nenhum recibo com essa busca.':'Nenhum recibo emitido ainda. Clique em “+ Novo recibo”.'}</td></tr>`}</table></div>`};
  render(); let tq; $('#rq').oninput=e=>{clearTimeout(tq); tq=setTimeout(()=>{RST.q=e.target.value; render()},200)};
  box.onclick=async e=>{const t=e.target; if(t.id==='rnovo') return recForm({}); if(t.id==='rcfg') return recCfgForm();
    const p=t.closest('[data-rpdf]'); if(p){const r=R.find(x=>x.n==p.dataset.rpdf); return recPdf(r,cfg,r.vias||1)}
    const d=t.closest('[data-red]'); if(d) return recForm(R.find(x=>x.n==d.dataset.red))}}

async function recCfgForm(){const c=await recCfg(); const fv=await formulario('Dados da Chamae no recibo',[{k:'razao',l:'Razão social / nome',val:c.razao,req:true},{k:'cnpj',l:'CNPJ',val:c.cnpj},{k:'end',l:'Endereço (opcional, sai no rodapé)',val:c.end},{k:'cidade',l:'Cidade/UF (local do recibo)',val:c.cidade},{k:'tel',l:'Telefone',val:c.tel},{k:'email',l:'E-mail',val:c.email},{k:'ass',l:'Quem assina pela Chamae',val:c.ass},{k:'ass_doc',l:'CPF ou cargo de quem assina',val:c.ass_doc}],'Salvar'); if(!fv) return;
  try{await api('fin_config?on_conflict=chave',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({chave:'recibo_cfg',valor:{...c,...fv},atualizado_em:new Date().toISOString()})}); toast('Dados salvos'); if(FST.ab==='rec') finView()}catch(err){toast('Erro: '+err.message)}}

async function recForm(r0){if(!r0) return; const cfg=await recCfg(); const novo=!r0.n; const ch={nome:cfg.razao,doc:cfg.cnpj};
  const r={tipo:'R',data:hoje(),local:cfg.cidade,forma:'PIX',vias:1,...r0}; if(novo){if(r.tipo==='R'){r.rec=r.rec||ch.nome; r.rec_doc=r.rec_doc||ch.doc} else {r.pag=r.pag||ch.nome; r.pag_doc=r.pag_doc||ch.doc}}
  if(novo&&!r.ass){if(r.tipo==='R'){r.ass=cfg.ass||cfg.razao; r.ass_doc=cfg.ass?cfg.ass_doc:cfg.cnpj} else {r.ass=r.rec||''; r.ass_doc=r.rec_doc||''}}
  if(r.valor&&!r.ext) r.ext=extenso(r.valor);
  const ov=document.createElement('div'); ov.className='ov'; const v=(k)=>esc(r[k]??'');
  ov.innerHTML=`<div class="sh grid rec-f"><div class="row" style="justify-content:space-between"><b style="font-size:18px">${novo?'Novo recibo':'Recibo nº '+recNum(r.n)}</b><button class="chip" data-x>✕</button></div>
   <div class="row rec-tipo"><button class="chip${r.tipo==='R'?' on':''}" data-rt="R">⬇️ A Chamae recebeu</button><button class="chip${r.tipo==='P'?' on':''}" data-rt="P">⬆️ A Chamae pagou</button></div>
   <div class="r2"><label class="f">Quem pagou<input id="rpag" list="rclis" value="${v('pag')}" placeholder="nome ou razão social"></label><label class="f">CPF/CNPJ de quem pagou<input id="rpagd" value="${v('pag_doc')}" inputmode="numeric"></label></div>
   <div class="r2"><label class="f">Quem recebeu<input id="rrec" list="rclis" value="${v('rec')}" placeholder="nome ou razão social"></label><label class="f">CPF/CNPJ de quem recebeu<input id="rrecd" value="${v('rec_doc')}" inputmode="numeric"></label></div>
   <datalist id="rclis"></datalist>
   <div class="r2"><label class="f">Valor (R$)<input id="rval" inputmode="decimal" value="${r.valor!=null?String(r.valor).replace('.',','):''}" placeholder="0,00"></label><label class="f">Data do pagamento<input id="rdat" type="date" value="${v('data')}"></label></div>
   <label class="f">Valor por extenso <span class="hint">(preenche sozinho; pode corrigir)</span><input id="rext" value="${v('ext')}"></label>
   <label class="f">Referente a<textarea id="rref" rows="2" placeholder="ex.: comissão de representação da NF 12345 / serviço de entrega de outubro">${v('ref')}</textarea></label>
   <div class="r2"><label class="f">Forma de pagamento<input id="rfor" list="rfors" value="${v('forma')}"><datalist id="rfors">${REC_FORMAS.map(f=>`<option value="${f}">`).join('')}</datalist></label><label class="f">Cidade/UF<input id="rloc" value="${v('local')}" placeholder="ex.: Ribeirão Preto/SP"></label></div>
   <div class="r2"><label class="f">Quem assina<input id="rass" value="${v('ass')}"></label><label class="f">CPF ou cargo de quem assina<input id="rassd" value="${v('ass_doc')}"></label></div>
   <label class="f">Observação (opcional, sai pequena no recibo)<input id="robs" value="${v('obs')}"></label>
   <label class="row" style="gap:8px;font-size:15px"><input type="checkbox" id="rvias"${r.vias==2?' checked':''} style="width:20px;height:20px;min-height:0"> Duas vias na mesma folha (uma para cada lado, com linha de corte)</label>
   <div class="row"><button class="btn" id="rsv">💾 Salvar e gerar PDF</button><button class="btn ghost" id="rprev">👁 Ver PDF sem salvar</button>${!novo?`<button class="btn ghost" id="rcan" style="color:var(--bad)">${r.cancelado?'Reativar':'Cancelar recibo'}</button>`:''}</div></div>`;
  document.body.appendChild(ov); const q=s=>ov.querySelector(s);
  clientes().then(C=>{const dl=q('#rclis'); if(dl) dl.innerHTML=C.slice(0,4000).map(c=>`<option value="${esc(c.n)}">${esc(fmtCnpj(c.cnpj))}</option>`).join('')}).catch(()=>{});
  const docDe=async(inp,docInp)=>{if(docInp.value.trim()) return; const C=await clientes().catch(()=>[]); const c=C.find(x=>norm(x.n)===norm(inp.value)); if(c) docInp.value=fmtCnpj(c.cnpj)};
  let extMexeu=!!r0.ext&&r0.ext!==extenso(r0.valor), assMexeu=!novo;
  q('#rext').oninput=()=>extMexeu=true; q('#rass').oninput=q('#rassd').oninput=()=>assMexeu=true;
  q('#rval').oninput=()=>{if(extMexeu) return; const n=lerNumBR(q('#rval').value); q('#rext').value=n>0?extenso(n):''};
  const syncAss=()=>{if(assMexeu) return; if(r.tipo==='P'){q('#rass').value=q('#rrec').value; q('#rassd').value=q('#rrecd').value}};
  q('#rpag').onchange=()=>docDe(q('#rpag'),q('#rpagd')); q('#rrec').onchange=async()=>{await docDe(q('#rrec'),q('#rrecd')); syncAss()}; q('#rrecd').oninput=syncAss;
  const ler=()=>({...r,tipo:r.tipo,pag:q('#rpag').value.trim(),pag_doc:q('#rpagd').value.trim(),rec:q('#rrec').value.trim(),rec_doc:q('#rrecd').value.trim(),valor:lerNumBR(q('#rval').value),data:q('#rdat').value,ext:q('#rext').value.trim(),ref:q('#rref').value.trim(),forma:q('#rfor').value.trim(),local:q('#rloc').value.trim(),ass:q('#rass').value.trim(),ass_doc:q('#rassd').value.trim(),obs:q('#robs').value.trim(),vias:q('#rvias').checked?2:1});
  const salvar=async x=>{if(!x.n){const u=await api('fin_config?select=chave&chave=like.recibo:*&order=chave.desc&limit=1'); x.n=(u[0]?+u[0].chave.split(':')[1]:0)+1; x.em=new Date().toISOString(); x.por=meuNome()}
    await api('fin_config?on_conflict=chave',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({chave:'recibo:'+String(x.n).padStart(6,'0'),valor:x,atualizado_em:new Date().toISOString()})}); return x};
  ov.onclick=async e=>{const t=e.target; if(t===ov||t.closest('[data-x]')) return ov.remove();
    const rt=t.closest('[data-rt]'); if(rt&&rt.dataset.rt!==r.tipo){const a=ler(); r.tipo=rt.dataset.rt; ov.querySelectorAll('[data-rt]').forEach(b=>b.classList.toggle('on',b.dataset.rt===r.tipo));
      /* troca os lados: a Chamae passa de quem recebeu para quem pagou (ou o contrário) */
      q('#rpag').value=a.rec; q('#rpagd').value=a.rec_doc; q('#rrec').value=a.pag; q('#rrecd').value=a.pag_doc;
      if(!assMexeu){if(r.tipo==='R'){q('#rass').value=cfg.ass||cfg.razao; q('#rassd').value=cfg.ass?cfg.ass_doc:cfg.cnpj} else syncAss()} return}
    try{if(t.id==='rcan'){r.cancelado=!r.cancelado; await salvar({...r}); ov.remove(); toast(r.cancelado?'Recibo cancelado':'Recibo reativado'); if(FST.ab==='rec') finView(); return}
      if(t.id!=='rsv'&&t.id!=='rprev') return; const x=ler();
      if(!x.pag||!x.rec||!(x.valor>0)||!x.data) return toast('Preencha quem pagou, quem recebeu, valor e data');
      if(!x.ext) x.ext=extenso(x.valor);
      if(t.id==='rprev') return recPdf({...x,n:x.n||0},cfg,x.vias,true);
      t.disabled=true; t.textContent='Gerando…'; const s=await salvar(x); ov.remove(); toast('Recibo nº '+recNum(s.n)+' salvo'); await recPdf(s,cfg,s.vias); if(FST.ab==='rec') finView()}catch(err){t.disabled=false; t.textContent='💾 Salvar e gerar PDF'; toast('Erro: '+err.message)}}}

async function recPdf(r,cfg,vias,previa){await loadJsPDF(); const {jsPDF}=window.jspdf; const doc=new jsPDF({unit:'mm',format:'a4'}); const W=210,M=14; const NAVY=[28,35,64],GOLD=[224,161,0],GREY=[110,104,98],LINE=[221,214,207],CREAM=[253,244,214];
  const logo=await imgData('logo.jpg',900); const dois=vias==2; const chR=ehChamae(r.rec,cfg);
  const rod=[cfg.razao,cfg.cnpj?'CNPJ '+cfg.cnpj:'',cfg.tel,cfg.email].filter(Boolean).join('  ·  ');
  const caixa=(x,y,w,h,lbl,fill)=>{doc.setDrawColor(...LINE); if(fill){doc.setFillColor(...fill); doc.roundedRect(x,y,w,h,2,2,'FD')} else doc.roundedRect(x,y,w,h,2,2); doc.setFont('helvetica','normal'); doc.setFontSize(7); doc.setTextColor(...GREY); doc.text(lbl,x+4,y+5)};
  const bloco=(y0,via)=>{const k=dois?1:1.18, hh=dois?24:30; /* k: folga extra quando é uma via só na folha */
    doc.setFillColor(...NAVY); doc.rect(0,y0,W,hh,'F'); if(logo){const lw=dois?54:66, lh=lw*24/66; doc.addImage(logo.d,'JPEG',M-2,y0+(hh-lh)/2,lw,lh)}
    doc.setTextColor(255); doc.setFont('helvetica','bold'); doc.setFontSize(dois?16:19); doc.text('RECIBO',W-M,y0+(dois?11:13),{align:'right'});
    doc.setFont('helvetica','normal'); doc.setFontSize(9); doc.text(`Nº ${r.n?recNum(r.n):'(prévia)'}${via?'  ·  '+via:''}`,W-M,y0+(dois?17:20),{align:'right'}); if(!dois) doc.text(dbr(r.data),W-M,y0+25,{align:'right'});
    doc.setFillColor(...GOLD); doc.rect(0,y0+hh,W,1.2,'F');
    let y=y0+hh+(dois?6:10); const cw=W-2*M;
    /* quem pagou + valor */
    const h1=dois?17:20; doc.setFont('helvetica','bold'); doc.setFontSize(dois?11:12.5); const pl=doc.splitTextToSize(r.pag||'',cw-62); const h1b=Math.max(h1,(dois?11:13)+pl.length*5+(r.pag_doc?4.5:0));
    caixa(M,y,cw-58,h1b,chR?'RECEBEMOS DE':'RECEBI(EMOS) DE'); doc.setTextColor(30); doc.setFont('helvetica','bold'); doc.setFontSize(dois?11:12.5); doc.text(pl,M+4,y+(dois?10.5:12));
    doc.setFont('helvetica','normal'); doc.setFontSize(8.5); doc.setTextColor(60); if(r.pag_doc) doc.text((/\d{3}\.\d{3}\.\d{3}-\d{2}|^\d{11}$/.test(r.pag_doc)?'CPF ':(/\//.test(r.pag_doc)||/^\d{14}$/.test(r.pag_doc)?'CNPJ ':''))+r.pag_doc,M+4,y+(dois?10.5:12)+pl.length*5);
    caixa(W-M-54,y,54,h1b,'VALOR',CREAM); doc.setTextColor(30); doc.setFont('helvetica','bold'); doc.setFontSize(dois?15:17); doc.text(brl(r.valor),W-M-4,y+h1b/2+(dois?4:4.5),{align:'right'}); y+=h1b+(dois?3:5)*k;
    /* extenso */
    doc.setFont('helvetica','normal'); doc.setFontSize(dois?10:11); const el=doc.splitTextToSize('('+(r.ext||extenso(r.valor))+')',cw-8).slice(0,2); const h2=(dois?9:11)+el.length*(dois?4.6:5.2);
    caixa(M,y,cw,h2,'A IMPORTÂNCIA DE'); doc.setTextColor(30); doc.setFont('helvetica','bolditalic'); doc.setFontSize(dois?10:11); doc.text(el,M+4,y+(dois?10:11.5)); y+=h2+(dois?3:5)*k;
    /* referente a */
    doc.setFont('helvetica','normal'); doc.setFontSize(dois?9.5:10.5); const rl=doc.splitTextToSize(r.ref||'—',cw-8).slice(0,dois?3:6); const h3=(dois?9:11)+rl.length*(dois?4.4:5);
    caixa(M,y,cw,h3,'REFERENTE A'); doc.setTextColor(30); doc.setFontSize(dois?9.5:10.5); doc.text(rl,M+4,y+(dois?10:11.5)); y+=h3+(dois?3:5)*k;
    /* quem recebeu · forma · data */
    const h4=dois?16:19, c1=cw*0.48, c2=cw*0.28, c3=cw-c1-c2; const rcl=doc.splitTextToSize(r.rec||'',c1-8);
    caixa(M,y,c1-2,h4,'QUEM RECEBEU'); doc.setTextColor(30); doc.setFont('helvetica','bold'); doc.setFontSize(9.5); doc.text(rcl[0]||'',M+4,y+(dois?10:11.5)); doc.setFont('helvetica','normal'); doc.setFontSize(8); doc.setTextColor(60); if(r.rec_doc) doc.text(r.rec_doc,M+4,y+(dois?13.8:15.8));
    caixa(M+c1,y,c2-2,h4,'FORMA DE PAGAMENTO'); doc.setTextColor(30); doc.setFont('helvetica','bold'); doc.setFontSize(9.5); doc.text(doc.splitTextToSize(r.forma||'—',c2-8)[0],M+c1+4,y+(dois?10:11.5));
    caixa(M+c1+c2,y,c3,h4,'DATA DO PAGAMENTO'); doc.setTextColor(30); doc.setFont('helvetica','bold'); doc.setFontSize(9.5); doc.text(dbr(r.data),M+c1+c2+4,y+(dois?10:11.5)); doc.setFont('helvetica','normal'); y+=h4+(dois?5:7)*k;
    /* quitação, local/data e assinatura */
    doc.setFontSize(dois?8.3:9.5); doc.setTextColor(...GREY); doc.text('Para clareza, firmo(amos) o presente recibo, dando plena, geral e irrevogável quitação do valor acima.',M,y); y+=dois?5:7*k;
    doc.setTextColor(30); doc.setFontSize(dois?9.5:11); doc.text([r.local,recDataLonga(r.data)].filter(Boolean).join(', ')+'.',W-M,y,{align:'right'}); y+=dois?13:24*k;
    doc.setDrawColor(60); doc.setLineWidth(.3); doc.line(W/2-45,y,W/2+45,y); doc.setFont('helvetica','bold'); doc.setFontSize(dois?9.5:10.5); doc.text(r.ass||r.rec||'',W/2,y+4.6,{align:'center'});
    doc.setFont('helvetica','normal'); doc.setFontSize(8); doc.setTextColor(...GREY); if(r.ass_doc) doc.text(r.ass_doc,W/2,y+8.6,{align:'center'}); y+=dois?11:14;
    if(r.obs){doc.setFontSize(7.5); doc.text(doc.splitTextToSize('Obs.: '+r.obs,cw).slice(0,2),M,y+(dois?0:4))}
    const fy=y0+(dois?141:283); doc.setDrawColor(...GOLD); doc.setLineWidth(.6); doc.line(M,fy,W-M,fy); doc.setFontSize(7.6); doc.setTextColor(...GREY); doc.text(rod,W/2,fy+4.4,{align:'center'}); if(cfg.end&&!dois) doc.text(cfg.end,W/2,fy+8.2,{align:'center'});
    if(r.cancelado||previa){doc.saveGraphicsState&&doc.saveGraphicsState(); try{doc.setGState(new doc.GState({opacity:.18}))}catch(_){}; doc.setTextColor(r.cancelado?200:120,r.cancelado?30:120,r.cancelado?30:120); doc.setFont('helvetica','bold'); doc.setFontSize(dois?54:80); doc.text(r.cancelado?'CANCELADO':'PRÉVIA',W/2,y0+(dois?92:170),{align:'center',angle:20}); doc.restoreGraphicsState&&doc.restoreGraphicsState(); doc.setFont('helvetica','normal')}};
  if(dois){bloco(0,'1ª via'); doc.setDrawColor(150); doc.setLineDashPattern([2,2],0); doc.setLineWidth(.2); doc.line(4,148.5,W-4,148.5); doc.setLineDashPattern([],0); doc.setFontSize(7); doc.setTextColor(150); doc.text('corte aqui',W-6,147,{align:'right'}); bloco(148.5,'2ª via')} else bloco(0,'');
  const nome=(r.tipo==='R'?r.pag:r.rec)||'recibo'; const fname=`Recibo-${r.n?recNum(r.n):'previa'}-${nome.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^A-Za-z0-9]+/g,'-').slice(0,30)}.pdf`;
  const blob=doc.output('blob'); if(window.__recPdfHook) return window.__recPdfHook(blob,fname);
  const file=new File([blob],fname,{type:'application/pdf'}); if(MOVEL&&navigator.canShare&&navigator.canShare({files:[file]})){try{await navigator.share({files:[file],title:'Recibo '+recNum(r.n)}); return}catch(e){if(e.name==='AbortError') return}}
  const a=document.createElement('a'); a.href=URL.createObjectURL(blob); a.download=fname; document.body.appendChild(a); a.click(); setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},1500); toast('PDF do recibo baixado')}

/* ---------- NF-e: leitura do XML, comissão e vínculo com o pedido ---------- */
function lerNFe(txt){const x=new DOMParser().parseFromString(txt,'text/xml'); if(x.getElementsByTagName('parsererror').length) throw new Error('XML inválido');
  const tg=(el,n)=>el&&el.getElementsByTagName(n)[0], tx=(el,n)=>{const e=tg(el,n); return e?e.textContent.trim():''}, nm=v=>+v||0;
  const ev=tg(x,'infEvento'); if(ev&&!tg(x,'infNFe')){return {evento:true,chave:tx(ev,'chNFe'),tipo:tx(ev,'tpEvento'),desc:tx(ev,'xEvento')||tx(ev,'descEvento')}}
  const inf=tg(x,'infNFe'); if(!inf) throw new Error('não é NF-e'); const ide=tg(inf,'ide'), em=tg(inf,'emit'), de=tg(inf,'dest'), tot=tg(inf,'ICMSTot');
  const ch=(inf.getAttribute('Id')||'').replace(/^NFe/,'')||tx(x,'chNFe'); const peds=new Set(); [...inf.getElementsByTagName('xPed')].forEach(e=>e.textContent.trim()&&peds.add(e.textContent.trim()));
  const ip=[...inf.getElementsByTagName('infProt')][0]||tg(x,'infProt'); const cStat=ip?tx(ip,'cStat'):'';
  return {chave:ch,numero:tx(ide,'nNF'),serie:tx(ide,'serie'),emissao:(tx(ide,'dhEmi')||tx(ide,'dEmi')).slice(0,10),tpNF:tx(ide,'tpNF'),natOp:tx(ide,'natOp'),
    emit_cnpj:tx(em,'CNPJ'),emit_nome:tx(em,'xFant')||tx(em,'xNome'),dest_cnpj:tx(de,'CNPJ')||tx(de,'CPF'),dest_nome:tx(de,'xNome'),dest_cidade:[tx(tg(de,'enderDest'),'xMun'),tx(tg(de,'enderDest'),'UF')].filter(Boolean).join('/'),
    v_prod:nm(tx(tot,'vProd')),v_ipi:nm(tx(tot,'vIPI')),v_st:nm(tx(tot,'vST')),v_frete:nm(tx(tot,'vFrete')),v_desc:nm(tx(tot,'vDesc')),v_nf:nm(tx(tot,'vNF')),
    x_ped:[...peds].join(', ')||null,inf_cpl:tx(tg(inf,'infAdic'),'infCpl')||null,cStat,
    duplicatas:[...inf.getElementsByTagName('dup')].map(d=>({n:tx(d,'nDup'),venc:tx(d,'dVenc'),v:nm(tx(d,'vDup'))}))}}
const finRegra=rep=>(FIN.regras||[]).find(r=>r.rep===rep)||{};
function finRepDaNF(n){const c=n.emit_cnpj; const r=(FIN.regras||[]).find(g=>(g.cnpjs||[]).includes(c)); if(r) return r.rep; const en=norm(n.emit_nome);
  const hit=(REPS||[]).filter(r=>{const k=norm(r.nome).split(' ')[0]; return k.length>=3&&en.includes(k)}); return hit.length===1?hit[0].id:null}
/* % por tabela do pedido (ex.: Medix "TABELA SUDESTE 3" = 3%): primeiro as linhas "trecho do nome; %", senão o último número do nome da tabela */
function finPctTabela(g,tab){if(!tab) return null; const t=norm(tab); for(const l of String(g.tabelas||'').split(/\n/)){const [k,v]=l.split(';').map(x=>(x||'').trim()); if(k&&v&&t.includes(norm(k))) return lerNumBR(v)} const m=t.match(/(\d+(?:[.,]\d+)?)\s*%?\s*$/); return m&&+m[1].replace(',','.')<=30?+m[1].replace(',','.'):null}
function finCalc(n){const g=finRegra(n.rep), b=g.base||'prod'; const base=b==='nf'?n.v_nf:b==='prod_ipi'?n.v_prod-n.v_desc+n.v_ipi:n.v_prod-n.v_desc; let pct=g.pct!=null?+g.pct:null; if(g.modo==='tabela'){const pt=finPctTabela(g,n.tabela); if(pt!=null) pct=pt}
  return {base:Math.round(base*100)/100,pct,comissao:pct==null?null:Math.round(base*pct)/100}}
async function finPedido(n){if(!n.dest_cnpj||!n.rep) return null; const di=ymd(new Date(Date.parse(n.emissao)-150*864e5));
  const P=await api(`pedidos?select=id,num,oc,num_fabrica,valor,valor_imp,data,status,tabela&cnpj=eq.${n.dest_cnpj}&representada=eq.${encodeURIComponent(repName(n.rep))}&data=gte.${di}&data=lte.${n.emissao}&order=data.desc&limit=50`).catch(()=>[]);
  const P2=P.filter(p=>!/cancel|rascunho/i.test(p.status||'')); const txt=' '+[n.x_ped,n.inf_cpl].filter(Boolean).join(' ').replace(/[^0-9A-Za-z-]+/g,' ')+' ';
  const tem=v=>{const s=String(v||'').trim(); if(s.length<4) return false; const d=s.replace(/^0+/,''); return txt.includes(' '+s+' ')||(d.length>=4&&new RegExp('\\D0*'+d.replace(/[^0-9A-Za-z]/g,'')+'\\D').test(txt))};
  let p=P2.find(p=>tem(p.oc)||tem(p.num_fabrica)||tem(p.num)||tem(String(p.num||'').split('-').pop())); if(p) return p;
  const perto=P2.filter(p=>[p.valor,p.valor_imp].some(v=>v&&Math.abs(v-n.v_prod)/n.v_prod<0.03)); return perto.length===1?perto[0]:null}
function finParcelas(nf){const g=finRegra(nf.rep), q=g.quando||'duplicata', dia=Math.min(28,Math.max(1,+g.dia||15)); if(nf.comissao==null||nf.cancelada) return [];
  const d0={tipo:'R',categoria:'comissao',rep:nf.rep,cnpj:nf.dest_cnpj,cliente:nf.dest_nome,nfe_id:nf.id,competencia:nf.emissao.slice(0,8)+'01',descricao:`Comissão ${repName(nf.rep)} NF ${nf.numero}`};
  if(q==='duplicata'&&nf.duplicatas&&nf.duplicatas.length){const tot=nf.duplicatas.reduce((a,d)=>a+d.v,0)||1; let acc=0; return nf.duplicatas.map((d,i,arr)=>{const v=i===arr.length-1?Math.round((nf.comissao-acc)*100)/100:Math.round(nf.comissao*d.v/tot*100)/100; acc+=v; return {...d0,valor:v,vencimento:d.venc||nf.emissao,parcela:`${i+1}/${arr.length}`}})}
  if(q==='faturamento') return [{...d0,valor:nf.comissao,vencimento:nf.emissao}];
  const [y,mo]=nf.emissao.split('-').map(Number); return [{...d0,valor:nf.comissao,vencimento:ymd(new Date(Date.UTC(y,mo,dia)))}]}
async function finGerarComissao(nf){await api(`fin_lancamentos?nfe_id=eq.${nf.id}&status=eq.aberto`,{method:'DELETE'}); const ja=await api(`fin_lancamentos?select=id&nfe_id=eq.${nf.id}`);
  if(ja.length) return; const rows=finParcelas(nf); if(rows.length) await api('fin_lancamentos',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify(rows)})}
async function finImportarXML(files){const res={ok:0,dup:0,ev:0,err:[],semRep:[],semPct:0,semPed:0}; await finDados();
  for(const f of files){let n; try{n=lerNFe(await f.text())}catch(err){res.err.push(f.name+': '+err.message); continue}
    try{if(n.evento){if(n.tipo==='110111'){const r=await api(`fin_nfe?chave=eq.${n.chave}`,{method:'PATCH',headers:{Prefer:'return=representation'},body:JSON.stringify({cancelada:true})}); if(r.length){await api(`fin_lancamentos?nfe_id=eq.${r[0].id}&status=eq.aberto`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({status:'cancelado'})})} res.ev++} continue}
      if(!n.chave) throw new Error('sem chave de acesso'); if(n.tpNF==='0'){res.err.push(`${f.name}: NF de entrada (devolução?) — lance à mão se precisar`); continue}
      const ex=await api(`fin_nfe?select=id&chave=eq.${n.chave}`); if(ex.length){res.dup++; continue}
      n.origem=f.fila?'email':'upload'; n.rep=finRepDaNF(n); if(n.rep==='_ignorar'){res.ign=(res.ign||0)+1; continue} if(!n.rep){res.semRep.push({n,xml:await f.text(),nome:f.name,fila:f.fila}); continue}
      await finSalvarNF(n,await f.text(),res)}catch(err){res.err.push(f.name+': '+err.message)}}
  return res}
async function finSalvarNF(n,xml,res){const ped=await finPedido(n), pedido_id=ped&&ped.id||null; n.tabela=ped&&ped.tabela||null; const c=finCalc(n); const {tpNF,natOp,cStat,...row}=n;
  const [nf]=await api('fin_nfe',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({...row,...c,pedido_id,xml,origem:n.origem||'upload'})}); await finGerarComissao(nf);
  /* não grava pedidos.data_fat: a 1ª NF (às vezes parcial) jogava o pedido inteiro para o mês dela; o faturado do mês vem das próprias NF-e */
  res.ok++; if(c.pct==null) res.semPct++; if(!pedido_id) res.semPed++}
async function finEscolherRep(it){return new Promise(ok=>{const ov=document.createElement('div'); ov.className='ov';
  ov.innerHTML=`<div class="sh grid"><b style="font-size:18px">De qual representada é esta NF?</b><p class="hint">NF ${esc(it.n.numero)} emitida por <b>${esc(it.n.emit_nome)}</b> (CNPJ ${esc(it.n.emit_cnpj)}) para ${esc(it.n.dest_nome)}. O Sistema lembra a escolha para as próximas notas deste CNPJ.</p>
   <div class="row">${(REPS||[]).filter(r=>r.ativa).map(r=>`<button class="chip" data-er="${r.id}">${esc(r.nome)}</button>`).join('')}</div><div class="row"><button class="btn ghost" data-er="_ignorar">🚫 Não representamos: ignorar sempre este CNPJ</button><button class="btn ghost" data-er="">Pular só agora</button></div></div>`;
  document.body.appendChild(ov); ov.onclick=e=>{const b=e.target.closest('[data-er]'); if(b){ov.remove(); ok(b.dataset.er||null)}}})}
async function finNFe(box){const de=mesIni(FST.y,FST.mo), ate=mesFim(FST.y,FST.mo);
  const N=await api(`fin_nfe?select=id,chave,numero,emissao,rep,emit_nome,dest_cnpj,dest_nome,dest_cidade,v_prod,v_ipi,v_nf,base,pct,comissao,pedido_id,cancelada,x_ped,duplicatas,tabela,v_desc&emissao=gte.${de}&emissao=lte.${ate}&order=emissao.desc,numero.desc`); if(!box.isConnected) return;
  const L1=N.length?await api(`fin_lancamentos?select=nfe_id,status,valor,valor_pago&nfe_id=in.(${N.map(n=>n.id).join(',')})`):[];
  const recb=id=>L1.filter(l=>l.nfe_id===id&&l.status==='pago').reduce((a,l)=>a+(+l.valor_pago||0),0);
  const v=N.filter(n=>!n.cancelada); const semPct=v.filter(n=>n.pct==null).length;
  box.innerHTML=`<div class="card" id="fdrop" style="border-style:dashed;text-align:center;padding:22px;cursor:pointer"><b>📄 Arraste aqui os XML das NF-e</b> <span class="hint">(ou toque para escolher; pode mandar vários de uma vez, inclusive eventos de cancelamento)</span><input id="fxml" type="file" accept=".xml,text/xml" multiple hidden></div>
   <p class="hint" style="margin:8px 0">Os XML que chegam no e-mail entram sozinhos ao abrir esta tela (o robô confere as caixas a cada hora). A comissão usa o % e a regra de cada representada em <b>Configurar</b>.${semPct?` <span class="warn">${semPct} nota(s) sem % de comissão cadastrado.</span>`:''}</p>
   <div class="kpis"><div class="kpi"><span class="hint">NFs no mês</span><b style="font-size:20px">${v.length}</b></div><div class="kpi"><span class="hint">Faturado pelas fábricas</span><b style="font-size:20px">${brl(v.reduce((a,n)=>a+(+n.v_prod||0),0))}</b></div><div class="kpi"><span class="hint">Comissão prevista</span><b class="ok" style="font-size:20px">${brl(v.reduce((a,n)=>a+(+n.comissao||0),0))}</b></div><div class="kpi"><span class="hint">Sem pedido ligado</span><b style="font-size:20px">${v.filter(n=>!n.pedido_id).length}</b></div></div>
   <div class="row" style="margin:10px 0;justify-content:flex-end"><button class="btn ghost sm" id="frec">↻ Recalcular comissões em aberto do mês</button></div>
   <div style="overflow-x:auto"><table class="t"><tr><th>NF</th><th>Emissão</th><th>Representada</th><th>Cliente</th><th class="n">Produtos</th><th class="n">Comissão</th><th>Pedido</th></tr>
   ${N.map(n=>`<tr data-fn="${n.id}" style="cursor:pointer;border-top:1px solid var(--line);${n.cancelada?'opacity:.5;text-decoration:line-through':''}"><td><b>${esc(n.numero)}</b></td><td>${dbr(n.emissao)}</td><td>${esc(repName(n.rep))}</td><td>${esc(n.dest_nome)}<div class="hint">${esc(n.dest_cidade||'')}</div></td><td class="n">${brl(n.v_prod)}</td>
     <td class="n">${n.pct==null?'<span class="warn">sem %</span>':`<b>${brl(n.comissao)}</b><div class="hint">${pct(n.pct)}${recb(n.id)?' · recebido '+brl(recb(n.id)):''}</div>`}</td><td>${n.pedido_id?'<span class="tag ok">✓ ligado</span>':'<span class="tag">sem pedido</span>'}</td></tr>`).join('')||'<tr><td colspan="7" class="hint" style="padding:12px 0">Nenhuma NF-e com emissão neste mês.</td></tr>'}</table></div>`;
  const inp=$('#fxml'), drop=$('#fdrop'); drop.onclick=()=>inp.click(); inp.onclick=e=>e.stopPropagation();
  const roda=async(files,auto)=>{files=[...files].filter(f=>/xml$/i.test(f.name)||(f.type||'').includes('xml')); if(!files.length) return toast('Escolha arquivos .xml'); drop.innerHTML=`<p class="hint">Lendo ${files.length} arquivo(s)…</p>`;
    const r=await finImportarXML(files); for(const it of r.semRep){const rep=await finEscolherRep(it); if(!rep){r.err.push(`${it.nome}: pulada (sem representada)`); if(it.fila) FILA_PULADAS.add(it.fila); continue} it.n.rep=rep; const g=finRegra(rep); if(rep==='_ignorar'){r.ign=(r.ign||0)+1; try{await api('fin_regras?on_conflict=rep',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({rep,cnpjs:[...new Set([...(g.cnpjs||[]),it.n.emit_cnpj])]})}); await finDados(true)}catch(err){r.err.push(it.nome+': '+err.message)} continue}
      try{await api('fin_regras?on_conflict=rep',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({rep,cnpjs:[...new Set([...(g.cnpjs||[]),it.n.emit_cnpj])]})}); await finDados(true); await finSalvarNF(it.n,it.xml,r)}catch(err){r.err.push(it.nome+': '+err.message)}}
    if(auto){const ids=files.map(f=>f.fila).filter(id=>!FILA_PULADAS.has(id)); if(ids.length) await api(`fin_xml_fila?id=in.(${ids.join(',')})`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({processado:true,resultado:new Date().toISOString()})}).catch(()=>{})}
    alert(`${auto?'📧 Do e-mail: ':''}${r.ok} NF-e importada(s)${r.dup?`, ${r.dup} já estava(m) no Sistema`:''}${r.ev?`, ${r.ev} cancelamento(s)`:''}${r.ign?`, ${r.ign} ignorada(s) (fábrica que não representamos)`:''}.${r.semPed?`\n${r.semPed} sem pedido ligado (toque na nota para ligar).`:''}${r.semPct?`\n${r.semPct} sem % de comissão: cadastre em Configurar e use Recalcular.`:''}${r.err.length?'\n\nNão importadas:\n'+r.err.join('\n'):''}`);
    if(r.ok){const ult=await api('fin_nfe?select=emissao&order=criado_em.desc&limit=1'); if(ult[0]){const [y,mo]=ult[0].emissao.split('-'); FST.y=+y; FST.mo=+mo-1}} finView()};
  const fila=(await api('fin_xml_fila?select=id,chave,xml,conta&processado=eq.false&order=id&limit=200').catch(()=>[])).filter(x=>!FILA_PULADAS.has(x.id));
  if(fila.length&&box.isConnected) return roda(fila.map(x=>({name:`e-mail ${x.conta||''} ${x.chave}.xml`,type:'text/xml',fila:x.id,text:async()=>x.xml})),true);
  inp.onchange=()=>roda(inp.files); drop.ondragover=e=>{e.preventDefault(); drop.style.borderColor='var(--accent)'}; drop.ondragleave=()=>drop.style.borderColor=''; drop.ondrop=e=>{e.preventDefault(); roda(e.dataTransfer.files)};
  box.onclick=async e=>{const t=e.target; if(t.id==='frec'){if(!confirm('Recalcular a comissão das notas deste mês com as regras atuais? Parcelas já recebidas não mudam.')) return; await finDados(true); let k=0;
      for(const n of v){const c=finCalc({...n,v_desc:+n.v_desc||0,v_ipi:+n.v_ipi||0,v_prod:+n.v_prod||0,v_nf:+n.v_nf||0}); const full=(await api(`fin_nfe?select=*&id=eq.${n.id}`))[0]; await api(`fin_nfe?id=eq.${n.id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify(c)}); await finGerarComissao({...full,...c}); k++} toast(`${k} nota(s) recalculada(s)`); return finView()}
    const r=t.closest('[data-fn]'); if(r) finNFDet(+r.dataset.fn)}}
async function finNFDet(id){const [n]=await api(`fin_nfe?select=*&id=eq.${id}`); const L1=await api(`fin_lancamentos?select=*&nfe_id=eq.${id}&order=vencimento`);
  const P=n.dest_cnpj?await api(`pedidos?select=id,num,oc,valor,data,status,representada,vendedor,tabela&cnpj=eq.${n.dest_cnpj}&order=data.desc&limit=15`).catch(()=>[]):[];
  const ov=document.createElement('div'); ov.className='ov'; ov.innerHTML=`<div class="sh grid"><b style="font-size:18px">NF-e ${esc(n.numero)} · ${esc(repName(n.rep))}${n.cancelada?' <span class="bad">(cancelada)</span>':''}</b>
   <div class="hint">Emissão ${dbr(n.emissao)} · ${esc(n.emit_nome)} → <b>${esc(n.dest_nome)}</b> ${esc(n.dest_cidade||'')}<br>Chave ${esc(n.chave)}${n.x_ped?'<br>Pedido do cliente (xPed): '+esc(n.x_ped):''}</div>
   <table class="t"><tr><td>Produtos</td><td class="n">${brl(n.v_prod)}</td></tr>${+n.v_desc?`<tr><td>Desconto</td><td class="n">−${brl(n.v_desc)}</td></tr>`:''}<tr><td>IPI</td><td class="n">${brl(n.v_ipi)}</td></tr>${+n.v_st?`<tr><td>ST</td><td class="n">${brl(n.v_st)}</td></tr>`:''}${+n.v_frete?`<tr><td>Frete</td><td class="n">${brl(n.v_frete)}</td></tr>`:''}<tr><td><b>Total da NF</b></td><td class="n"><b>${brl(n.v_nf)}</b></td></tr>
    ${n.tabela?`<tr><td>Tabela do pedido</td><td class="n">${esc(n.tabela)}</td></tr>`:''}<tr><td>Base da comissão</td><td class="n">${brl(n.base)}</td></tr><tr><td><b>Comissão</b> ${n.pct==null?'<span class="warn">(sem % cadastrado)</span>':pct(n.pct)}</td><td class="n"><b class="ok">${brl(n.comissao)}</b></td></tr></table>
   ${(n.duplicatas||[]).length?`<div class="hint">Duplicatas do cliente: ${n.duplicatas.map(d=>`${esc(d.n)} ${dbr(d.venc)} ${brl(d.v)}`).join(' · ')}</div>`:''}
   <div><b>Comissão a receber</b>${L1.map(l=>`<div class="row" style="justify-content:space-between;padding:4px 0;border-bottom:1px solid var(--line)"><span>${dbr(l.vencimento)} ${l.parcela?esc(l.parcela):''}</span><span>${brl(l.valor)} ${FTAG[finStatus(l)]}</span></div>`).join('')||'<p class="hint">Nenhuma parcela (cadastre o % da representada).</p>'}</div>
   <div><b>Pedido ligado</b> ${n.pedido_id?`<span class="tag ok">${esc((P.find(p=>p.id===n.pedido_id)||{}).num||n.pedido_id)}</span> <button class="chip" data-np="">Desligar</button>`:'<span class="hint">nenhum — escolha abaixo</span>'}
    ${P.map(p=>`<div class="row" style="justify-content:space-between;padding:4px 0"><span>${dbr(p.data)} · nº ${esc(p.num)} ${p.oc?'· OC '+esc(p.oc):''} · ${esc(p.representada)} <span class="hint">${esc(p.tabela||'')} ${esc(p.vendedor||'')} ${esc(p.status||'')}</span></span><span>${brl(p.valor)} ${p.id===n.pedido_id?'':`<button class="chip" data-np="${esc(p.id)}">Ligar</button>`}</span></div>`).join('')}</div>
   <div class="row"><button class="btn ghost" id="fnx">Baixar XML</button><button class="btn ghost" id="fnd" style="color:var(--bad)">Excluir nota</button><button class="btn ghost" data-x>Fechar</button></div></div>`;
  document.body.appendChild(ov); ov.onclick=async e=>{const t=e.target; if(t===ov||t.closest('[data-x]')) return ov.remove();
    try{const np=t.closest('[data-np]'); if(np){const pp=P.find(p=>p.id===np.dataset.np); const nn={...n,v_prod:+n.v_prod||0,v_desc:+n.v_desc||0,v_ipi:+n.v_ipi||0,v_nf:+n.v_nf||0,tabela:pp&&pp.tabela||null}; await finDados(true); const c=finCalc(nn);
      await api(`fin_nfe?id=eq.${id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({pedido_id:np.dataset.np||null,tabela:nn.tabela,...c})}); await finGerarComissao({...nn,...c}); ov.remove(); toast(np.dataset.np?'Pedido ligado':'Desligado'); return finNFDet(id)}
      if(t.id==='fnx'){const a=document.createElement('a'); a.href=URL.createObjectURL(new Blob([n.xml||''],{type:'text/xml'})); a.download=`NFe_${n.chave}.xml`; a.click(); return}
      if(t.id==='fnd'){if(!confirm('Excluir esta nota e as parcelas de comissão dela?')) return; await api(`fin_nfe?id=eq.${id}`,{method:'DELETE'}); ov.remove(); toast('Nota excluída'); finView()}}catch(err){toast('Erro: '+err.message)}}}

/* ---------- importar contas a pagar do Conta Azul (relatório em PDF ou planilha) ---------- */
const CA_DRE=[[/simples|\bdas\b|imposto|\biss\b|\bpis\b|cofins|irpj|csll|parcelamento/i,'impostos','Deduções'],[/comiss/i,'com_vend','Pessoal'],
  [/sal[aá]rio|fgts|rescis|f[eé]rias|13[ºo°]|prev|inss|plano de sa[uú]de|odonto|vale|ticket|alimenta|pens[aã]o|pr[oó].?labore|benef|seguran[cç]a ocup|colaborador|funcion/i,'pessoal','Pessoal'],
  [/combust|ped[aá]gio|viage|hosped|brinde|amostra|feira|marketing|propaganda/i,'comercial','Comerciais'],[/tarifa|juros|\biof\b|multa|banc[aá]ri/i,'financeiro','Financeiras'],
  [/empr[eé]stimo|pronamp|financiamento|\bgiro\b/i,'emprestimo','Empréstimos'],[/transfer[eê]ncia/i,'transferencia','Transferências'],[/s[oó]cio|distribui|retirada/i,'retirada','Retiradas']];
const caDre=nome=>{for(const [re,d,g] of CA_DRE) if(re.test(nome)) return [d,g]; return ['administrativa','Administrativas']};
const caData=v=>{if(v==null||v==='') return null; if(typeof v==='number') return ymd(new Date(Math.round((v-25569)*864e5))); const s=String(v).trim(); let m=s.match(/^(\d{2})\/(\d{2})\/(\d{4})/); if(m) return `${m[3]}-${m[2]}-${m[1]}`; m=s.match(/^(\d{4})-(\d{2})-(\d{2})/); return m?m[0]:null};
const caNum=v=>typeof v==='number'?v:(lerNumBR(String(v||'').replace(/[R$\s]/g,'').replace(/^-/,''))||0)*(/^\s*-/.test(String(v||''))?-1:1);
async function caPDF(f){await loadPDFJS(); const pdf=await pdfjsLib.getDocument({data:await f.arrayBuffer()}).promise; const recs=[]; const DT=/^\d{2}\/\d{2}\/\d{4}$/, NUM=/^-?\d{1,3}(\.\d{3})*,\d{2}$/;
  for(let p=1;p<=pdf.numPages;p++){const pg=await pdf.getPage(p); const tc=await pg.getTextContent(), vp=pg.getViewport({scale:1}); /* posição na página como aparece (relatório em paisagem vem girado) */ const it=tc.items.filter(i=>i.str.trim()).map(i=>{const t=pdfjsLib.Util.transform(vp.transform,i.transform); return {s:i.str.trim(),x:t[4],y:-t[5]}});
    const hx=k=>{const h=it.find(i=>norm(i.s).startsWith(k)); return h&&h.x}; const H={desc:hx('DESCRI'),forn:hx('FORNECEDOR'),cat:hx('CATEGORIA'),val:hx('VALOR TOTAL')}; const hy=(it.find(i=>norm(i.s).startsWith('VENCIMENTO'))||{}).y;
    if(H.desc==null||H.cat==null||hy==null) continue; if(H.forn==null) H.forn=(H.desc+H.cat)/2; const fy=Math.max(...it.filter(i=>/^(Totais do per|Usu[aá]rio:)/i.test(i.s)).map(i=>i.y),-1e9);
    const linhas=[]; it.filter(i=>i.y<hy-2&&i.y>fy+2).sort((a,b)=>b.y-a.y||a.x-b.x).forEach(i=>{let l=linhas.find(l=>Math.abs(l.y-i.y)<2.5); if(!l){l={y:i.y,it:[]}; linhas.push(l)} l.it.push(i)});
    const reg=linhas.filter(l=>l.it.some(i=>DT.test(i.s)&&i.x<H.desc-2)).map(l=>({l,extra:[]})); if(!reg.length) continue;
    linhas.filter(l=>!reg.some(r=>r.l===l)).forEach(l=>{const r=reg.reduce((a,b)=>Math.abs(b.l.y-l.y)<Math.abs(a.l.y-l.y)?b:a); r.extra.push(l)});
    const col=(a,b,ls)=>ls.flatMap(x=>x.it.filter(i=>i.x>=a-3&&i.x<b-3&&!NUM.test(i.s)&&!DT.test(i.s)).map(i=>i.s)).join(' ').replace(/\s+/g,' ').trim();
    /* texto quebrado na virada da página: as linhas soltas no topo pertencem à última conta da página anterior */
    const r0=reg[0], ac=r0.extra.filter(x=>x.y>r0.l.y).sort((a,b)=>b.y-a.y), ab=r0.extra.filter(x=>x.y<r0.l.y).length; const ant=recs[recs.length-1];
    if(ant&&ac.length>ab){const mv=ac.slice(0,ac.length-ab); r0.extra=r0.extra.filter(x=>!mv.includes(x)); const j=(k,a,b)=>{const t=col(a,b,mv); if(t) ant[k]=(ant[k]+' '+t).trim()}; j('desc',H.desc,H.forn); j('forn',H.forn,H.cat); j('cat',H.cat,H.val!=null?H.val:1e4)}
    for(const {l,extra} of reg){const todas=[l,...extra].sort((a,b)=>b.y-a.y);
      const ds=l.it.filter(i=>DT.test(i.s)).sort((a,b)=>a.x-b.x).map(i=>i.s), ns=l.it.filter(i=>NUM.test(i.s)).sort((a,b)=>a.x-b.x).map(i=>i.s);
      const semValor=todas.filter(x=>x===l||!x.it.some(i=>NUM.test(i.s))); let cat=col(H.cat,H.val!=null?H.val:1e4,semValor); if(!cat){const c1=extra.filter(x=>x.it.some(i=>NUM.test(i.s))).sort((a,b)=>b.y-a.y)[0]; if(c1) cat=col(H.cat,H.val!=null?H.val:1e4,[c1])}
      const sit=(l.it.find(i=>/^(pago|em aberto|vencid|atrasad|cancel|recebid|parcial)/i.test(i.s))||{}).s||'';
      recs.push({venc:caData(ds[0]),pag:ds[1]?caData(ds[1]):null,desc:col(H.desc,H.forn,todas),forn:col(H.forn,H.cat,todas),cat,valor:caNum(ns[0]),aberto:ns[1]!=null?caNum(ns[1]):null,sit})}}
  return recs}
async function caXLS(f){await loadXLSX(); const wb=XLSX.read(await f.arrayBuffer(),{type:'array'}); const out=[];
  for(const sn of wb.SheetNames){const A=XLSX.utils.sheet_to_json(wb.Sheets[sn],{header:1,raw:true,defval:''}); const hi=A.findIndex(r=>r.some(c=>/vencimento/i.test(String(c)))); if(hi<0) continue;
    const h=A[hi].map(c=>norm(c)); const ix=(re,not)=>h.findIndex(c=>re.test(c)&&!(not&&not.test(c)));
    const C={venc:ix(/VENCIMENTO/),pag:ix(/PAGAMENTO|PAGO EM|DATA DO PAG|DATA DE PAG/,/FORMA/),desc:ix(/DESCRI/),forn:ix(/FORNECEDOR|CONTATO|NOME DO/),cat:ix(/CATEGORIA/),valor:[ix(/VALOR TOTAL|VALOR ORIGINAL|VALOR DA PARCELA/,/ABERTO/),ix(/^VALOR/,/ABERTO|PAGO|JUROS|MULTA|DESCONTO|CATEGORIA/),ix(/^VALOR/,/ABERTO/)].find(i=>i>=0)??-1,aberto:ix(/ABERTO/),sit:ix(/SITUA|STATUS/)};
    A.slice(hi+1).forEach(r=>{const g=k=>C[k]>=0?r[C[k]]:''; const venc=caData(g('venc')); if(!venc) return; out.push({venc,pag:caData(g('pag')),desc:String(g('desc')).trim(),forn:String(g('forn')).trim(),cat:String(g('cat')).trim(),valor:Math.abs(caNum(g('valor'))),aberto:C.aberto>=0?Math.abs(caNum(g('aberto'))):null,sit:String(g('sit')).trim()})})}
  return out}
async function finImportarCA(files){let R=[]; const err=[];
  for(const f of files){try{R.push(.../\.pdf$/i.test(f.name)?await caPDF(f):await caXLS(f))}catch(e){err.push(f.name+': '+e.message)}}
  R=R.filter(r=>r.venc&&r.valor&&r.desc); if(!R.length) return toast('Não encontrei lançamentos'+(err.length?': '+err.join('; '):' nesses arquivos'));
  await finDados(true); const catPor=n=>FIN.cats.find(c=>c.tipo==='P'&&norm(c.nome)===norm(n));
  const novas={}; R.forEach(r=>{r.cat=r.cat||'Outras despesas'; if(!catPor(r.cat)&&!novas[norm(r.cat)]){const [dre,grupo]=caDre(r.cat); novas[norm(r.cat)]={nome:r.cat,dre,grupo}}});
  const de=R.reduce((a,r)=>r.venc<a?r.venc:a,'9999'), ate=R.reduce((a,r)=>r.venc>a?r.venc:a,'0000');
  const ex=await api(`fin_lancamentos?select=descricao,valor,vencimento&tipo=eq.P&vencimento=gte.${de}&vencimento=lte.${ate}`); const chave=r=>r.vencimento+'|'+norm(r.descricao)+'|'+(+r.valor).toFixed(2); const ja=new Set(ex.map(chave));
  R.forEach(r=>r.dup=ja.has(chave({vencimento:r.venc,descricao:r.desc,valor:r.valor}))); const nv=R.filter(r=>!r.dup), pago=r=>/pago|quitad|liquid/i.test(r.sit)||(r.aberto===0&&!!r.pag);
  const opts=FDRE.filter(([k])=>!k.startsWith('=')&&!['receita','outras_receitas'].includes(k));
  const ov=document.createElement('div'); ov.className='ov'; ov.innerHTML=`<div class="sh grid"><b style="font-size:18px">Importar contas a pagar (Conta Azul)</b>
   <p class="hint">${R.length} lançamento(s) de ${dbr(de)} a ${dbr(ate)} · <b>${nv.length} novo(s)</b>${R.length-nv.length?` · ${R.length-nv.length} já estão no Sistema (não duplica)`:''} · total novo ${brl(nv.reduce((a,r)=>a+r.valor,0))}${err.length?`<br><span class="warn">${esc(err.join('; '))}</span>`:''}</p>
   ${Object.keys(novas).length?`<div class="card"><b>Categorias novas</b> <span class="hint">confira em qual linha da DRE cada uma entra</span><table class="t" style="margin-top:6px">${Object.entries(novas).map(([k,c])=>`<tr><td>${esc(c.nome)}</td><td><select data-nc="${esc(k)}">${opts.map(([d,l])=>`<option value="${d}"${d===c.dre?' selected':''}>${l}</option>`).join('')}</select></td></tr>`).join('')}</table></div>`:''}
   <div style="overflow:auto;max-height:45vh"><table class="t"><tr><th>Vencimento</th><th>Descrição</th><th>Fornecedor</th><th>Categoria</th><th class="n">Valor</th><th>Situação</th></tr>${R.map(r=>`<tr style="border-top:1px solid var(--line);${r.dup?'opacity:.45':''}"><td>${dbr(r.venc)}</td><td>${esc(r.desc)}${r.dup?' <span class="tag">já existe</span>':''}</td><td class="hint">${esc(r.forn)}</td><td class="hint">${esc(r.cat)}</td><td class="n">${brl(r.valor)}</td><td>${pago(r)?`pago ${dbr(r.pag)}`:'em aberto'}</td></tr>`).join('')}</table></div>
   <div class="row"><button class="btn" id="caok"${nv.length?'':' disabled'}>Importar ${nv.length} lançamento(s)</button><button class="btn ghost" data-x>Cancelar</button></div></div>`;
  document.body.appendChild(ov); ov.onchange=e=>{const s=e.target.closest('[data-nc]'); if(s) novas[s.dataset.nc].dre=s.value};
  ov.onclick=async e=>{const t=e.target; if(t===ov||t.closest('[data-x]')) return ov.remove(); if(t.id!=='caok') return; t.disabled=true; t.textContent='Importando…';
    try{const NG={impostos:'Deduções',pessoal:'Pessoal',com_vend:'Pessoal',comercial:'Comerciais',administrativa:'Administrativas',financeiro:'Financeiras',emprestimo:'Empréstimos',transferencia:'Transferências',investimento:'Investimentos',retirada:'Retiradas'};
      const cs=Object.values(novas).map(c=>({id:'ca_'+norm(c.nome).toLowerCase().replace(/[^a-z0-9]+/g,'_').slice(0,40),tipo:'P',grupo:NG[c.dre]||c.grupo,nome:c.nome,dre:c.dre,ordem:600}));
      if(cs.length) await api('fin_categorias?on_conflict=id',{method:'POST',headers:{Prefer:'resolution=ignore-duplicates,return=minimal'},body:JSON.stringify(cs)}); await finDados(true);
      const rows=nv.map(r=>{const p=pago(r), pm=r.desc.match(/^(\d{1,3}\/\d{1,3})\s*-/); return {tipo:'P',descricao:r.desc,categoria:(catPor(r.cat)||{}).id||'outras_desp',valor:r.valor,vencimento:r.venc,competencia:r.venc.slice(0,8)+'01',status:p?'pago':'aberto',pago_em:p?(r.pag||r.venc):null,valor_pago:p?r.valor:null,cliente:r.forn||null,parcela:pm?pm[1]:null,obs:'Importado do Conta Azul'}});
      for(let k=0;k<rows.length;k+=200) await api('fin_lancamentos',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify(rows.slice(k,k+200))});
      ov.remove(); toast(`${rows.length} lançamento(s) importado(s)`); const [y,mo]=de.split('-'); FST.y=+y; FST.mo=+mo-1; FST.st=''; finView()}catch(err){t.disabled=false; t.textContent='Tentar de novo'; toast('Erro: '+err.message)}}}

/* ---------- DRE ---------- */
async function finDRE(box){const y=FST.y, cx=FST.dre==='caixa'; const L1=await api(`fin_lancamentos?select=tipo,categoria,valor,valor_pago,competencia,vencimento,pago_em,status&status=neq.cancelado&${cx?`pago_em=gte.${y}-01-01&pago_em=lte.${y}-12-31&status=eq.pago`:`competencia=gte.${y}-01-01&competencia=lte.${y}-12-31`}`); if(!box.isConnected) return;
  const V={}; L1.forEach(l=>{const d=cx?l.pago_em:(l.competencia||l.vencimento); const mo=+d.slice(5,7)-1; const k=finCat(l.categoria).dre||(l.tipo==='R'?'outras_receitas':'administrativa'); const val=(cx?+l.valor_pago||0:+l.valor||0)*(l.tipo==='R'?1:-1); V[k]=V[k]||Array(12).fill(0); V[k][mo]+=val});
  const g=k=>V[k]||Array(12).fill(0), som=(...ks)=>Array.from({length:12},(_,i)=>ks.reduce((a,k)=>a+g(k)[i],0));
  const T={'=liq':som('receita','outras_receitas','impostos')}; T['=mc']=som('receita','outras_receitas','impostos','com_vend'); T['=op']=som('receita','outras_receitas','impostos','com_vend','pessoal','comercial','administrativa'); T['=res']=som('receita','outras_receitas','impostos','com_vend','pessoal','comercial','administrativa','financeiro');
  const cols=Array.from({length:12},(_,i)=>i);
  const cel=v=>`<td class="n${v<0?' bad':''}">${v?brl(v).replace('R$','').trim():'—'}</td>`;
  box.innerHTML=`<div class="row" style="margin-bottom:10px"><button class="chip${cx?'':' on'}" data-fdr="comp">Competência</button><button class="chip${cx?' on':''}" data-fdr="caixa">Caixa (pelo que foi baixado)</button><span class="hint">Ano ${y} · ${cx?'pela data da baixa':'comissão no mês do faturamento, despesas no mês de competência'}</span><span style="flex:1"></span><button class="btn ghost sm" id="fdx">Excel</button></div>
   <div style="overflow-x:auto"><table class="t"><tr><th></th>${cols.map(i=>`<th class="n">${MESES[i].slice(0,3)}</th>`).join('')}<th class="n">Ano</th></tr>
   ${FDRE.map(([k,l])=>{const a=k.startsWith('=')?T[k]:g(k); const tot=a.reduce((s,v)=>s+v,0); return `<tr style="border-top:1px solid var(--line);${k.startsWith('=')?'font-weight:700;background:var(--surface2)':''}${['investimento','retirada','emprestimo','transferencia'].includes(k)?'color:var(--muted)':''}"><td style="white-space:nowrap">${l}</td>${cols.map(i=>cel(a[i])).join('')}${cel(tot)}</tr>`}).join('')}</table></div>
   <p class="hint" style="margin-top:8px">Cada categoria do plano de contas cai numa linha da DRE (Configurar › Plano de contas). Impostos entram pelo lançamento da guia em Contas a pagar.</p>`;
  box.onclick=async e=>{const b=e.target.closest('[data-fdr]'); if(b){FST.dre=b.dataset.fdr; return finDRE(box)}
    if(e.target.id==='fdx'){await loadXLSX(); const ws=XLSX.utils.aoa_to_sheet([['DRE '+y+(cx?' (caixa)':' (competência)'),...cols.map(i=>MESES[i]),'Ano'],...FDRE.map(([k,l])=>{const a=k.startsWith('=')?T[k]:g(k); return [l,...cols.map(i=>Math.round(a[i]*100)/100),Math.round(a.reduce((s,v)=>s+v,0)*100)/100]})]); const wb=XLSX.utils.book_new(); XLSX.utils.book_append_sheet(wb,ws,'DRE'); XLSX.writeFile(wb,`DRE_${y}.xlsx`)}}}

/* ---------- configurar: comissão por representada, contas bancárias, plano de contas ---------- */
async function finAjustes(box){await finDados(true); const PC=await finPECfg(); if(!box.isConnected) return; const R=(REPS||[]).filter(r=>r.ativa);
  box.innerHTML=`<div class="card"><b>🏭 Comissão por representada</b><p class="hint">% fixo, ou pela tabela do pedido ligado à NF (Medix: SUDESTE 3 = 3%). Depois de mudar, use Recalcular na aba Comissões. Salva sozinho ao sair do campo. CNPJs emissores: o Sistema aprende ao importar a primeira nota de cada fábrica.</p>
    <div style="overflow-x:auto"><table class="t"><tr><th>Representada</th><th>Como calcula</th><th>% fixo</th><th>Base</th><th>Quando a fábrica paga</th><th>Dia</th><th>CNPJs das NF-e</th></tr>
    ${R.map(r=>{const g=finRegra(r.id); return `<tr data-rg="${r.id}" style="border-top:1px solid var(--line)"><td>${repIcon(r,16)} ${esc(r.nome)}</td><td><select data-k="modo"><option value="fixo"${g.modo!=='tabela'?' selected':''}>% fixo</option><option value="tabela"${g.modo==='tabela'?' selected':''}>Pela tabela do pedido</option></select>${g.modo==='tabela'?`<textarea data-k="tabelas" rows="2" style="margin-top:4px;min-width:170px" placeholder="Opcional, uma por linha: trecho do nome; %&#10;Sem nada: usa o número no fim do nome (SUDESTE 3 = 3%)">${esc(g.tabelas||'')}</textarea>`:''}</td><td><input data-k="pct" type="number" step="0.01" inputmode="decimal" value="${g.pct??''}" style="width:76px;padding:6px" placeholder="${g.modo==='tabela'?'se não achar':'%'}"></td>
      <td><select data-k="base">${Object.entries(FBASE).map(([k,l])=>`<option value="${k}"${(g.base||'prod')===k?' selected':''}>${l}</option>`).join('')}</select></td><td><select data-k="quando">${Object.entries(FQUANDO).map(([k,l])=>`<option value="${k}"${(g.quando||'duplicata')===k?' selected':''}>${l}</option>`).join('')}</select></td>
      <td><input data-k="dia" type="number" min="1" max="28" value="${g.dia??15}" style="width:58px;padding:6px" title="Dia do mês em que a comissão costuma cair"></td><td><input data-k="cnpjs" value="${esc((g.cnpjs||[]).join(', '))}" placeholder="aprende sozinho" style="min-width:150px;padding:6px"></td></tr>`}).join('')}<tr data-rg="_ignorar" style="border-top:1px solid var(--line)"><td>🚫 Ignorar</td><td colspan="4" class="hint">Notas destes CNPJs (fábricas que não representamos mais) nunca entram</td><td><input data-k="cnpjs" value="${esc((finRegra('_ignorar').cnpjs||[]).join(', '))}" placeholder="CNPJs" style="min-width:150px;padding:6px"></td></tr></table></div></div>
   <div class="card" style="margin-top:12px"><b>🏦 Contas bancárias</b>${FIN.contas.map(c=>`<div class="row" style="justify-content:space-between;padding:6px 0;border-bottom:1px solid var(--line)${c.ativa?'':';opacity:.5'}"><span>${esc(c.nome)} <span class="hint">${esc(c.banco||'')} · saldo inicial ${brl(c.saldo_inicial)} em ${dbr(c.data_saldo)}</span></span><button class="chip" data-cta="${c.id}">${c.ativa?'Desativar':'Ativar'}</button></div>`).join('')||'<p class="hint">Nenhuma conta cadastrada.</p>'}
    <div class="row" style="margin-top:8px"><input id="fcn" placeholder="Nome (ex.: Itaú PJ)" style="flex:1;min-width:140px"><input id="fcb" placeholder="Banco / agência / conta" style="flex:1;min-width:140px"><input id="fcs" inputmode="decimal" placeholder="Saldo inicial R$" style="width:130px"><input id="fcd" type="date" value="${hoje()}"><button class="btn sm" id="fcadd">+ Conta</button></div></div>
   <div class="card" style="margin-top:12px" id="fpecfg"><b>⚖️ Ponto de equilíbrio</b><p class="hint">Usa a média das despesas fixas dos últimos meses completos (pessoal, comerciais, administrativas e financeiras). Sem alíquota informada, os impostos pagos entram como despesa fixa.</p>
    <div class="row"><label class="f">Meses na média<input data-pe="meses" type="number" min="1" max="12" value="${PC.meses}" style="width:90px"></label><label class="f">Impostos sobre a comissão (%)<input data-pe="aliquota" type="number" step="0.01" value="${PC.aliquota??''}" placeholder="ex.: Simples" style="width:150px"></label><label class="f">Comissão de vendedores (% da comissão)<input data-pe="vend" type="number" step="0.01" value="${PC.vend||''}" style="width:150px"></label><label class="f" style="align-self:end"><span><input data-pe="emprestimos" type="checkbox"${PC.emprestimos?' checked':''}> contar parcelas de empréstimos</span></label></div>
    <div class="hint" style="margin-top:8px">Despesas não recorrentes (ficam fora da média):</div><div class="row" style="margin-top:4px">${FIN.cats.filter(c=>c.tipo==='P'&&c.ativa).map(c=>`<label class="chip" style="cursor:pointer"><input type="checkbox" data-peex="${esc(c.id)}"${PC.excluir.includes(c.id)?' checked':''}> ${esc(c.nome)}</label>`).join('')}</div></div>
   <div class="card" style="margin-top:12px"><b>📒 Plano de contas</b><div style="overflow-x:auto"><table class="t" style="margin-top:6px"><tr><th>Tipo</th><th>Grupo</th><th>Categoria</th><th>Linha da DRE</th><th></th></tr>
    ${FIN.cats.map(c=>`<tr style="border-top:1px solid var(--line)${c.ativa?'':';opacity:.5'}"><td>${c.tipo==='R'?'Receita':'Despesa'}</td><td>${esc(c.grupo)}</td><td>${esc(c.nome)}</td><td><select data-catdre="${esc(c.id)}">${FDRE.filter(([k])=>!k.startsWith('=')).map(([k,l])=>`<option value="${k}"${k===c.dre?' selected':''}>${l}</option>`).join('')}</select></td><td><button class="chip" data-cat="${c.id}">${c.ativa?'Ocultar':'Mostrar'}</button></td></tr>`).join('')}</table></div>
    <div class="row" style="margin-top:8px"><select id="ftt"><option value="P">Despesa</option><option value="R">Receita</option></select><input id="ftg" placeholder="Grupo (ex.: Administrativas)" style="flex:1;min-width:120px"><input id="ftn" placeholder="Categoria (ex.: Seguro)" style="flex:1;min-width:120px"><select id="ftd">${FDRE.filter(([k])=>!k.startsWith('=')).map(([k,l])=>`<option value="${k}">${l}</option>`).join('')}</select><button class="btn sm" id="ftadd">+ Categoria</button></div></div>`;
  box.onchange=async e=>{if(e.target.closest('#fpecfg')){const q=k=>box.querySelector(`[data-pe="${k}"]`); const v={meses:Math.min(12,Math.max(1,+q('meses').value||3)),aliquota:q('aliquota').value===''?null:+q('aliquota').value,vend:+q('vend').value||0,emprestimos:q('emprestimos').checked,excluir:[...box.querySelectorAll('[data-peex]:checked')].map(x=>x.dataset.peex)};
      try{await api('fin_config?on_conflict=chave',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({chave:'pe',valor:v,atualizado_em:new Date().toISOString()})}); toast('Ponto de equilíbrio atualizado')}catch(err){toast('Erro: '+err.message)} return}
    const i=e.target, cd=i.closest('[data-catdre]'); if(cd){try{await api(`fin_categorias?id=eq.${encodeURIComponent(cd.dataset.catdre)}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({dre:cd.value})}); cd.style.borderColor='var(--ok)'; await finDados(true)}catch(err){toast('Erro: '+err.message)} return} const tr=i.closest('[data-rg]'); if(!tr||!i.dataset.k) return; const k=i.dataset.k; let v=i.value;
    if(k==='pct') v=v===''?null:+String(v).replace(',','.'); if(k==='dia') v=+v||15; if(k==='tabelas') v=v.trim()||null; if(k==='cnpjs') v=v.split(/[,;\s]+/).map(s=>s.replace(/\D/g,'')).filter(s=>s.length>=8);
    try{await api('fin_regras?on_conflict=rep',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({rep:tr.dataset.rg,[k]:v,atualizado_em:new Date().toISOString()})}); i.style.borderColor='var(--ok)'; await finDados(true); if(k==='modo') finAjustes(box)}catch(err){toast('Erro: '+err.message)}};
  box.onclick=async e=>{const t=e.target; try{
    if(t.id==='fcadd'){const nome=$('#fcn').value.trim(); if(!nome) return toast('Dê um nome para a conta'); await api('fin_contas',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({nome,banco:$('#fcb').value.trim()||null,saldo_inicial:lerNumBR($('#fcs').value)||0,data_saldo:$('#fcd').value||hoje()})}); toast('Conta criada'); return finAjustes(box)}
    const ca=t.closest('[data-cta]'); if(ca){const c=FIN.contas.find(x=>x.id==ca.dataset.cta); await api(`fin_contas?id=eq.${c.id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({ativa:!c.ativa})}); return finAjustes(box)}
    const ct=t.closest('[data-cat]'); if(ct){const c=FIN.cats.find(x=>x.id===ct.dataset.cat); await api(`fin_categorias?id=eq.${c.id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({ativa:!c.ativa})}); return finAjustes(box)}
    if(t.id==='ftadd'){const nome=$('#ftn').value.trim(), grupo=$('#ftg').value.trim(); if(!nome||!grupo) return toast('Preencha grupo e categoria'); const id=norm(nome).toLowerCase().replace(/[^a-z0-9]+/g,'_').slice(0,30)+'_'+Date.now().toString(36).slice(-3);
      await api('fin_categorias',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({id,tipo:$('#ftt').value,grupo,nome,dre:$('#ftd').value,ordem:500})}); toast('Categoria criada'); return finAjustes(box)}}catch(err){toast('Erro: '+err.message)}}}

/* ================= busca técnica: CA, atributos, colar pedido do cliente, comparativo, fichas ================= */
/* base oficial de CAs (gerada toda semana pelo conversor-ca a partir do CAEPI): luvas + calçados, guardada 7 dias no aparelho */
const CAB={};
async function baseCA(){if(CAB.m) return CAB.m; return CAB.p||(CAB.p=(async()=>{let a=await kv.get('caepi_v1'); if(!a||Date.now()-a.t>7*864e5){try{const [l,c]=await Promise.all([fetch('/conversor-ca/caepi_luvas.json').then(r=>r.json()),fetch('/conversor-ca/caepi.json').then(r=>r.json()).catch(()=>[])]); a={t:Date.now(),d:[...c,...l]}; kv.set('caepi_v1',a)}catch(e){if(!a){CAB.p=null; throw e}}}
  const m=new Map(); a.d.forEach(x=>m.set(String(x.c),x)); CAB.m=m; return m})())}
const caCod=s=>String(s||'').replace(/\D/g,'').replace(/^0+/,'');
const caDt=x=>{const [d,m,y]=String(x&&x.v||'').split('/'); return y?new Date(+y,+m-1,+d):null};
/* situação do CA: ok | vence (até 90 dias) | vencido | sem (não achado na base) */
function caSit(x){if(!x) return {k:'sem',t:'não encontrado na base oficial'}; const dt=caDt(x); const dd=dt?Math.floor((dt-Date.now())/864e5):-1; const v=dt?dt.toLocaleDateString('pt-BR'):'?';
  if(!/VALIDO/.test(norm(x.s))||dd<0) return {k:'vencido',t:'VENCIDO em '+v,dd}; if(dd<=90) return {k:'vence',t:`vence em ${dd} dias (${v})`,dd}; return {k:'ok',t:'válido até '+v,dd}}
const SIT_ST={ok:'background:#d9f2e3;color:#14532d',vence:'background:#fff1cc;color:#7a5200',vencido:'background:#ffd9d4;color:#8a1c10',sem:'background:#eceef5;color:#555'};
const caTag=(ca,x)=>{const s=caSit(x); return `<span class="tag" style="${SIT_ST[s.k]}" title="${esc(x?x.f+' · '+x.n:'')}">CA ${esc(ca)} · ${esc(s.t)}</span>`};
/* fabricante na base de CAs de cada representada (para sugerir o CA de quem está sem) */
const FAB={medix:/MEDIX/,marluvas:/MARLUVAS/};

/* ---------- atributos técnicos: lidos do texto (pedido do cliente, descrição do produto, CA, ficha) ---------- */
const TEC_K=[['ca','CA'],['uso','Uso / tipo'],['desc','Descartável'],['mat','Material'],['po','Pó'],['est','Esterilidade'],['acab','Acabamento'],['cor','Cor'],['transp','Transparência'],['esp','Espessura'],['comp','Comprimento'],['bico','Biqueira'],['tam','Tamanho']];
const TEC_N={uso:{CIRURGICA:'Cirúrgica',PROCEDIMENTO:'Procedimento (saúde)',GERAL:'Uso geral (não médico)',EPI:'EPI / segurança'},mat:{LATEX:'Látex',NITRILO:'Nitrilo',VINIL:'Vinil',NEOPRENE:'Neoprene',PVC:'PVC',PU:'Poliuretano',COURO:'Couro',ALGODAO:'Algodão / tecido',POLIETILENO:'Polietileno',ACO:'Malha de aço',SINTETICA:'Sintética'},
  po:{COM:'Com pó',SEM:'Sem pó'},desc:{DESC:'Descartável (uso único)',REUT:'Reutilizável (forrada, multiuso)'},est:{SIM:'Estéril',NAO:'Não estéril'},acab:{LISA:'Lisa',TEXT:'Texturizada'},transp:{TRANSP:'Transparente',OPACA:'Opaca'},bico:{ACO:'Bico de aço',COMP:'Bico composite / plástico',SEM:'Sem bico'},
  cor:{AZUL:'Azul',BRANCA:'Branca',NATURAL:'Natural (bege)',PRETA:'Preta',ROSA:'Rosa',VERDE:'Verde',AMARELA:'Amarela',LARANJA:'Laranja',CINZA:'Cinza',VIOLETA:'Violeta / lilás',VERMELHA:'Vermelha',TRANSPARENTE:'Transparente',MARROM:'Marrom'}};
const tecTxt=(k,v)=>v==null||v===''?'—':Array.isArray(v)?v.map(x=>(TEC_N[k]||{})[x]||x).join(' / '):k==='esp'?String(v).replace('.',',')+' mm':k==='comp'?(+v?v+' mm':({CURTO:'Curto',MEDIO:'Médio',LONGO:'Longo'}[v]||v)):((TEC_N[k]||{})[v]||v);
const RX={mat:[['NITRILO',/NITRIL/],['LATEX',/LATEX|BORRACHA NATURAL/],['VINIL',/VINIL/],['NEOPRENE',/NEOPRENE|POLICLOROPRENO/],['PVC',/\bPVC\b/],['PU',/POLIURETANO|\bPU\d?\b/],['COURO',/COURO|VAQUETA|\bRASPA\b|PELICA/],['POLIETILENO',/POLIETILENO/],['ACO',/MALHA DE ACO|\bACO INOX/],['ALGODAO',/ALGODAO|TRICOT|MALHA PIGMENT/],['SINTETICA',/SINTETIC|POLIISOPRENO/]],
  cor:[['AZUL',/\bAZU(L|IS)\b/],['BRANCA',/\bBRANC[AO]S?\b|BRANCO LEITOSO/],['NATURAL',/\bNATURA(L|IS)\b|\bBEGE\b/],['PRETA',/\bPRET[AO]S?\b/],['ROSA',/\bROSA\b|\bPINK\b/],['VERDE',/\bVERDES?\b/],['AMARELA',/\bAMAREL[AO]S?\b/],['LARANJA',/\bLARANJA\b/],['CINZA',/\bCINZA\b/],['VIOLETA',/VIOLETA|LILAS|\bROX[AO]\b/],['VERMELHA',/VERMELH/],['MARROM',/MARROM/],['TRANSPARENTE',/TRANSPARENTE|INCOLOR/]]};
const sets=(t,L)=>L.filter(([,r])=>r.test(t)).map(([k])=>k);
const TAMS={PP:'PP',XP:'PP','EXTRA PEQUEN':'PP',EP:'PP',P:'P',PEQUEN:'P',M:'M',MEDI:'M',G:'G',GRANDE:'G',GG:'GG',XG:'GG','EXTRA GRANDE':'GG',EG:'GG',EGG:'XG',XGG:'XG'};
const TAMNUM={6:'PP',7:'P',8:'M',9:'G',10:'GG',11:'XG'};
function tamDe(t){let m=t.match(/TAMANHO\s*[:=]?\s*(EXTRA\s+PEQUEN|EXTRA\s+GRANDE|PEQUEN|MEDI|GRANDE|[A-Z]{1,3}\b|\d+(?:[.,]\d)?)/); if(!m) m=t.match(/\bTAM\.?\s*(EXTRA\s+PEQUEN|EXTRA\s+GRANDE|PEQUEN|MEDI|GRANDE|[A-Z]{1,3}\b|\d+(?:[.,]\d)?)/); if(!m) m=t.match(/\b(PP|GG|EGG|XGG|XG|EG|XP)\b/)||t.match(/[\s,(-](P|M|G)\s*(?:\(\d+\))?(?=\s*(?:[,);]|$)|\s+(?:[CS]\/|COM\b|SEM\b|QTD|QUANT|-|\d))/);
  if(!m) return null; const v=m[1].replace(/\s+/,' '); if(/^\d/.test(v)){const n=+v.replace(',','.'); return /^\d+$/.test(v)&&TAMNUM[n]?TAMNUM[n]:String(n).replace('.',',')} return TAMS[v]||null}
/* lê os atributos de um texto livre; os campos "NOME: valor;" (descrição de compras/edital) têm prioridade */
function lerAttrs(txt){const t=' '+norm(txt).replace(/\s+/g,' ')+' '; const a={}; const campo=re=>{const m=t.match(new RegExp('(?:'+re+')\\s*[:=]\\s*([^;\\n]+)')); return m?m[1].trim():null};
  const ca=campo('CERTIFICADO (?:DE )?APROVACAO|\\bC\\.?A\\.?')||(t.match(/\bC\.?A\.?\s*(?:N[OºO.]*\s*)?[:.]?\s*(\d{1,3}\.\d{3}|\d{3,6})\b/)||[])[1]; if(ca&&caCod(ca).length>=3) a.ca=caCod(ca);
  const fm=campo('MATERIAL'); a.mat=sets(fm||t,RX.mat); if(!a.mat.length) delete a.mat;
  const fc=campo('\\bCOR'); const cc=sets(fc||'',RX.cor); if(cc.length) a.cor=cc; else if(!fc){const c2=sets(t.replace(/BRANCO LEITOSO/g,'NATURAL'),RX.cor); if(c2.length) a.cor=c2}
  const ft=campo('TRANSPARENCIA'); if(ft) a.transp=/TRANSL|TRANSP/.test(ft)&&!/NAO|OPAC/.test(ft)?'TRANSP':'OPACA'; else if(a.cor&&a.cor.includes('TRANSPARENTE')) a.transp='TRANSP';
  const fp=campo('LUBRIFICACAO|\\bPO\\b')||''; const tp=fp||t; if(/\b(S\/ ?PO|SEM PO|ISENTA? DE PO|LIVRE DE PO|POWDER ?FREE|NAO TALCAD)/.test(tp)) a.po='SEM'; else if(/\b(C\/ ?PO|COM PO|TALCAD|AMIDO)/.test(tp)) a.po='COM';
  if(/NAO[ -]?ESTERIL|\bN\/ ?ESTERIL|NAO[ -]?ESTERILIZAD/.test(t)) a.est='NAO'; else if(/\bESTERI[LZ]/.test(t)) a.est='SIM';
  const fa=campo('ACABAMENTO')||t; if(/TEXTURI|RUGOS|RANHURAD|ANTIDERRAP|MICROTEXT|\bGRIP\b/.test(fa)) a.acab='TEXT'; else if(/\bLISA\b|\bLISO\b/.test(fa)) a.acab='LISA';
  const fe=t.match(/ESPESSURA[^;\d]{0,25}(\d+[.,]\d+)\s*(MM)?/)||t.match(/\b(0[.,]\d{2,3})\s*MM\b/); if(fe) a.esp=String(+fe[1].replace(',','.'));
  const fcp=campo('COMPRIMENTO(?: (?:DO )?PUNHO| TOTAL)?'); const cm=(fcp||t).match(/(\d{3})\s*MM/)||(fcp||'').match(/(\d{2})\s*CM/); if(cm) a.comp=String(cm[1].length===2?+cm[1]*10:+cm[1]); else if(fcp) a.comp=/CURT/.test(fcp)?'CURTO':/LONG|CANO/.test(fcp)?'LONGO':/MEDI|PADRAO|NORMAL/.test(fcp)?'MEDIO':undefined; else if(/\b(LONGA|CANO LONGO|PUNHO LONGO)\b/.test(t)) a.comp='LONGO'; if(!a.comp) delete a.comp;
  const tm=tamDe(t); if(tm) a.tam=tm;
  if(/SEM BICO|SEM BIQUEIRA/.test(t)) a.bico='SEM'; else if(/(BICO|BIQUEIRA) (DE )?ACO|·\s*ACO\s*·/.test(t)) a.bico='ACO'; else if(/(BICO|BIQUEIRA) (DE )?(COMPOSIT|PLASTIC|POLIPROP|PVC|TERMOPLAST)|·\s*COMPOSITE\s*·/.test(t)) a.bico='COMP';
  if(/MULTIUSO|FLOCAD|FORRAD|FORRO|REUTILIZ|BANHAD|REVESTID|TRICOT|MALHA|COURO|VAQUETA|\bRASPA\b|CANO LONGO|PUNHO EXTRA|VIROLA|ANATOMIC/.test(t)&&!/CIRURGI/.test(t)) a.desc='REUT'; else if(/DESCARTAV|USO UNICO|PROCEDIMENTO|CIRURGI|AMBIDESTR|\b[CS]\/ ?PO\b|COM PO|SEM PO|ISENTA? DE PO|\b\d+ ?UN\b|CARTUCHO|POLYBAG|\bUSO GERAL\b/.test(t)) a.desc='DESC';
  const u=[]; if(/CIRURGI/.test(t)&&!/NAO[ -]CIRURGI/.test(t)) u.push('CIRURGICA'); if(/PROCEDIMENTO|NAO[ -]CIRURGI|EXAME|\bSAUDE\b/.test(t)&&!/NAO SAUDE|NAO MEDIC|NAO UTILIZAR EM PROCEDIMENTO/.test(t)) u.push('PROCEDIMENTO');
  if(/NAO SAUDE|NAO MEDIC|USO GERAL|MULTIUSO|LIMPEZA|DOMESTIC/.test(t)) u.push('GERAL'); if(/AGENTES (MECANICOS|TERMICOS)|CORTE|CORTANTE|ABRASIV|ESCORIANT|SOLDA|ELETRIC|MALHA DE ACO|\bFRIO\b/.test(t)) u.push('EPI'); else if(!u.length&&a.desc==='DESC'&&/AGENTES (QUIMICOS|BIOLOGICOS)/.test(t)) u.push('GERAL'); if(u.length) a.uso=[...new Set(u)];
  const tipo=(t.match(/\b(LUVAS?|BOTAS?|BOTINAS?|SAPATOS?|TENIS|CALCADOS?|OCULOS|MASCARAS?|RESPIRADOR|AVENTAL|CAPACETE|PROTETOR|TOUCA|SERINGA|AGULHA|SONDA|CATETER|COLETE|MACACAO|JALECO)\b/)||[])[1]; if(tipo) a.tipo=tipo.replace(/S$/,'').replace(/^BOTINA$/,'BOTA').replace(/^(SAPATO|TENIS|CALCADO)$/,'CALCADO');
  return a}
/* atributos do produto: o que o gestor confirmou (attrs.tec) > descrição > ficha técnica > base de CA */
const TECM=new WeakMap();
function tecDe(p,base,fic){const ch=TECM.get(p); if(ch&&ch.b===!!base&&ch.f===!!fic) return ch.v; const d=lerAttrs([p.descricao,p.linha,(p.attrs||{}).sec].filter(Boolean).join(' · ')); delete d.ca; if(p.ca) d.ca=caCod(p.ca); const tm=(p.attrs||{}).tam||tamDe(' '+norm(p.descricao)+' '); if(tm) d.tam=tm; else delete d.tam;
  const g=norm(p.grupo||''); if(!d.uso){if(/HOSPITALAR/.test(g)) d.uso=/\bCIR\b|CIRURG/.test(norm(p.descricao))?['CIRURGICA']:['PROCEDIMENTO']; else if(/PROFISSIONAL/.test(g)) d.uso=['GERAL']; else if(/SAFETY|EPI/.test(g)||p.rep==='marluvas') d.uso=['EPI']}
  if(!d.est&&d.uso&&!d.uso.includes('CIRURGICA')&&/LUVA/.test(norm(p.descricao))) d.est='NAO';
  const src={}; Object.keys(d).forEach(k=>src[k]='descrição');
  const x=base&&d.ca?base.get(d.ca):null; if(x){const a=caAttrs(x); for(const k of ['mat','po','est','acab','cor','uso','transp']) if(a[k]&&d[k]===undefined){d[k]=a[k]; src[k]='CA'}}
  const f=fic&&fic[p.cod]; if(f) for(const k of ['esp','comp','cor','po','mat','acab']) if(f[k]&&d[k]===undefined){d[k]=k==='cor'||k==='mat'?sets(norm(f[k]),RX[k]):k==='po'?(/SEM|ISENT/.test(norm(f[k]))?'SEM':'COM'):f[k]; src[k]='ficha'}
  const man=(p.attrs||{}).tec||{}; for(const k in man) if(man[k]!==null&&man[k]!==''&&k!=='_por'){d[k]=man[k]; src[k]='confirmado'}
  if(d.mat&&!d.mat.length) delete d.mat; if(d.cor&&!d.cor.length) delete d.cor; d._src=src; TECM.set(p,{b:!!base,f:!!fic,v:d}); return d}

/* compara o pedido com o produto: ok | parcial | dif | ? (produto sem a informação) */
const PESO={bico:10,ca:40,mat:20,uso:12,desc:10,po:10,est:10,cor:8,tam:7,acab:4,esp:6,comp:3,transp:3};
function comparaTec(r,p,caProv){const out=[]; let s=0, mx=0;
  for(const [k] of TEC_K){const a=r[k]; if(a==null||(Array.isArray(a)&&!a.length)) continue; const b=p[k]; const w=PESO[k]||3; mx+=w; let st='?', nota='';
    if(k==='ca'&&b==null&&caProv){st='parcial'; nota='produto sem CA no cadastro, mas combina com o CA '+a+' ('+caProv+'): confirme na caixa ou com o fabricante e grave o CA no cadastro'}
    else if(b==null||(Array.isArray(b)&&!b.length)){st='?'; nota='produto sem essa informação: confira na ficha'}
    else if(k==='ca'){st=a===b?'ok':'dif'; if(st==='dif') nota='CA diferente do pedido'}
    else if(k==='esp'){const d=+b-+a; st=Math.abs(d)<0.006?'ok':Math.abs(d)<=0.021?'parcial':'dif'; if(st!=='ok') nota=d>0?'mais grossa que o pedido':'mais fina que o pedido'}
    else if(k==='comp'){const c=v=>+v?(+v<250?'CURTO':+v<300?'MEDIO':'LONGO'):v; st=c(a)===c(b)?'ok':'parcial'}
    else if(k==='cor'){const A0=a.filter(x=>x!=='TRANSPARENTE'), A=A0.length?A0:a, B=b; if(A.some(x=>B.includes(x))) st=A.every(x=>B.includes(x))?'ok':'parcial'; else if(A.includes('BRANCA')&&B.includes('NATURAL')||A.includes('NATURAL')&&B.includes('BRANCA')){st='parcial'; nota='látex natural é bege leitoso, não branco'} else st='dif'}
    else if(Array.isArray(a)){const B=Array.isArray(b)?b:[b]; const hit=a.filter(x=>B.includes(x)); st=hit.length===a.length?'ok':hit.length?'parcial':'dif';
      if(k==='mat'&&a.length>1&&hit.length) nota='o pedido cita '+a.map(x=>tecTxt('mat',x)).join(' e ')+', que são materiais diferentes: confirme com o cliente';
      if(k==='uso'&&st!=='ok'&&B.includes('GERAL')&&a.some(x=>x==='PROCEDIMENTO'||x==='CIRURGICA')) {st='dif'; nota='produto não é para uso em saúde'}
      if(k==='uso'&&a.length>1&&hit.length) st='ok'}
    else st=a===b?'ok':'dif';
    if(k==='transp'&&st==='dif') st='parcial';
    s+=st==='ok'?w:st==='parcial'?(k==='ca'?w*0.8:w/2):st==='?'?w*0.3:0; out.push({k,a,b,st,nota})}
  return {pts:mx?s/mx:0,lin:out}}
const ST_IC={ok:'✓',parcial:'≈',dif:'✕','?':'?'}, ST_COR={ok:'#14532d',parcial:'#7a5200',dif:'#8a1c10','?':'#666'}, ST_BG={ok:'#d9f2e3',parcial:'#fff1cc',dif:'#ffd9d4','?':'#eceef5'};
const difsTxt=lin=>lin.filter(l=>(l.st==='dif'||l.st==='parcial')&&l.k!=='ca'||l.k==='ca'&&l.st==='dif').map(l=>`${(TEC_K.find(x=>x[0]===l.k)||[])[1]}: pediu ${tecTxt(l.k,l.a)}, é ${tecTxt(l.k,l.b)}${l.nota?' ('+l.nota+')':''}`);
const tabCmp=lin=>{const sem=lin.filter(l=>l.st==='?'&&l.k!=='ca'); lin=lin.filter(l=>!sem.includes(l)); return `<table class="t" style="margin-top:6px"><tr><th>Atributo</th><th>Pedido</th><th>Produto</th><th></th></tr>${lin.map(l=>`<tr style="background:${ST_BG[l.st]}"><td>${esc((TEC_K.find(x=>x[0]===l.k)||[])[1])}</td><td>${esc(tecTxt(l.k,l.a))}</td><td>${esc(tecTxt(l.k,l.b))}${l.nota?`<div class="hint" style="color:${ST_COR[l.st]}">${esc(l.nota)}</div>`:''}</td><td style="color:${ST_COR[l.st]};font-weight:800;text-align:center">${ST_IC[l.st]}</td></tr>`).join('')}${sem.length?`<tr style="background:${ST_BG['?']}"><td colspan="4">? O cadastro não informa: ${esc(sem.map(l=>(TEC_K.find(x=>x[0]===l.k)||[])[1]+' (pedido '+tecTxt(l.k,l.a)+')').join(', '))}. Confira na ficha técnica.</td></tr>`:''}</table>`};
/* família = mesma descrição sem o tamanho (para mostrar um modelo só, no tamanho pedido) */
const familia=p=>norm(p.descricao).replace(/\bTAM(ANHO)?\.?\s*[A-Z0-9.,]+(\s*\(\d+\))?/g,' ').replace(/\b(PP|P|M|G|GG|XG|EG|EGG|XGG|XP)\b(\s*\(\d+\))?/g,' ').replace(/\(\d+(\.\d)?\)/g,' ').replace(/\b\d{1,2}[.,]\d\b/g,' ').replace(/\s+/g,' ').trim();
/* catálogos para a busca: todas as representadas ativas com produtos */
async function catalogosTec(so){const R=(await reps()).filter(r=>r.ativa&&r.n&&(!so||r.id===so)); const out=[]; await Promise.all(R.map(async r=>{const C=await catalog(r.id).catch(()=>[]); C.forEach(p=>out.push(p))})); return out}
const FIC={}; async function fichasDados(){if(FIC.d) return FIC.d; try{const [s,d]=await Promise.all([fetch('/medix-luvas/fichas.json').then(r=>r.json()).catch(()=>({})),fetch('/medix-luvas/fichas_dados.json').then(r=>r.json()).catch(()=>({}))]); FIC.site=s; FIC.d=d.cod||{}; FIC.pdf=d.pdf||{}}catch(e){FIC.d={}} return FIC.d}
/* ranqueia produtos para um item do pedido: mesmo tipo (luva, bota…), CA igual pesa mais; um modelo por família */
function ranquear(req,C,base,fic,n){const res=[]; const xr=req.ca&&base?base.get(req.ca):null, fr=FAB_DE(xr), ca0=xr?caAttrs(xr):null;
  for(const p of C){const t=tecDe(p,base,fic); if(req.tipo&&t.tipo!==req.tipo) continue; let prov=null;
    if(ca0&&!t.ca&&p.rep===fr){const q={}; for(const k of ['mat','po','est','desc','uso','acab']) if(ca0[k]!=null) q[k]=ca0[k]; const c0=comparaTec(q,t); if(!c0.lin.some(l=>l.st==='dif')&&c0.pts>=0.7) prov=repName(p.rep)}
    const c=comparaTec(req,t,prov); if(!req.tipo&&c.pts<0.2) continue; res.push({p,t,prov,...c})}
  res.sort((a,b)=>b.pts-a.pts); const fam=new Set(), out=[]; for(const r of res){const f=r.p.rep+'|'+familia(r.p); if(fam.has(f)) continue; fam.add(f); out.push(r); if(out.length>=(n||3)) break} return out}
/* separa os itens de um texto colado (WhatsApp, e-mail, edital): uma linha em branco, um nº de item ou cada linha que começa com o nome do produto */
function itensDoTexto(txt){const QRX=/\b(?:QTD|QTDE|QUANTIDADE|QUANT)\.?\s*[:=]?\s*(\d[\d.]*)|(\d[\d.]*)\s*(?:UN|UND|UNID|CX|CAIXAS?|PARES|PCT|PACOTES?|CARTUCHOS?)\b/;
  const ln=String(txt||'').replace(/\r/g,'').split('\n').map(l=>l.replace(/^\s*\[\d{1,2}:\d{2}[^\]]*\][^:]*:\s*/,'').trim()); const out=[]; let cur=null; const fecha=()=>{if(cur) out.push(cur); cur=null};
  for(const l of ln){if(!l){fecha(); continue} const a=lerAttrs(l), n=Object.keys(a).filter(k=>k!=='tipo').length, q=QRX.test(norm(l));
    if(a.tipo&&cur&&cur.tipo) fecha(); if(!a.tipo&&!n&&!q){if(cur) cur.l.push(l); continue} if(!cur) cur={l:[],tipo:false}; cur.l.push(l); if(a.tipo) cur.tipo=true}
  fecha(); return out.map(c=>{const b=c.l.join('\n').trim(); const m=norm(b).match(QRX); return {txt:b,qt:m?+(m[1]||m[2]).replace(/\./g,''):null,a:lerAttrs(b)}}).filter(it=>Object.keys(it.a).length)}
const resumoReq=a=>TEC_K.filter(([k])=>a[k]!=null).map(([k,l])=>`<span class="tag">${esc(l)}: ${esc(tecTxt(k,a[k]))}</span>`).join('');
async function precoRef(rep){const T=await tabelas(rep).catch(()=>[]); const o=Q()[rep]; const t=(o&&T.find(x=>x.id==o.tabela))||(rep==='medix'&&T.find(x=>/SUDESTE 3/.test(norm(x.nome))))||T.find(x=>/GERAL/.test(norm(x.nome)))||T[0]; return t?{t,P:await prices(t.id)}:{t:null,P:{}}}
/* Medix: tamanhos do mesmo produto (descrição igual tirando o "Tam …") viram um card só. TAM_MEDIX=false volta ao card por código.
   Reconhece "Tam P (7)", "TAM.6,5", "P (7)", "G/ GG (9)" e o tamanho no fim ("s/ pó PP", "Quimica PP C/100un").
   Junta também quando só a medida muda (ex.: 10392 0.28mm na família 0.38mm), quando falta o CA em algum tamanho
   e erro de digitação de 1–2 letras (Sepreme × Supreme), desde que o tamanho não se repita; a linha do tamanho avisa a diferença. */
const TAM_MEDIX=true;
const TAM_RE=/(?:\b(EGGG|XXG|XGG|EXG|EGG|XG|EG|GG|PP|P|M|G)\s+)?\bTam(?:anho)?\.?(?=[\s(\d])\s*(?:(EGGG|XXG|XGG|EXG|EGG|XG|EG|GG|PP|P|M|G|\d{1,2}(?:[.,]\d)?)\b)?\s*(?:\(\s*(\d{1,2}(?:[.,]\d)?)\s*\))?/i;
const TAM_SZ=/\b(EGGG|XXG|XGG|EXG|EGG|XG|EG|GG|PP|P|M|G)(?:\s*\/\s*(EGGG|XXG|XGG|EXG|EGG|XG|EG|GG|PP|P|M|G))?\s*\(\s*(\d{1,2}(?:[.,]\d)?)\s*\)/i;
const TAM_FIM=/\s(EGGG|XXG|XGG|EXG|EGG|XG|EG|GG|PP|P|M|G)(?=\s*(?:C\/\s*\d+\s*[A-Za-z]*)?\s*$)/;
const TAM_N={PP:6,P:7,M:8,G:9,GG:10,XG:10.5,EG:10.5,EXG:11,XGG:11,EGG:11,XXG:11,EGGG:12};
const MEDIDA_RE=/\d+(?:[.,]\d+)?\s*(?:mm|cm|m)?\s*[xX\/]\s*\d+(?:[.,]\d+)?\s*(?:mm|cm|m)\b|\d+(?:[.,]\d+)?\s*(?:mm|cm|m)\b/gi;
function tamMx(p){if(p._tam!==undefined) return p._tam; const d=String(p.descricao||''); let m=d.match(TAM_RE), a='', n2='', lab='';
  if(m&&(m[2]||m[3])){a=(m[2]||m[1]||'').toUpperCase(); n2=m[3]||''}
  else if((m=d.match(TAM_SZ))){a=m[1].toUpperCase()+(m[2]?'/'+m[2].toUpperCase():''); n2=m[3]}
  else if((m=d.match(TAM_FIM))){a=m[1]}
  else return p._tam=null;
  const n=n2?parseFloat(n2.replace(',','.')):a&&/\d/.test(a)?parseFloat(a.replace(',','.')):TAM_N[a.split('/').pop()]||50; lab=a&&n2?`${a} (${n2})`:a||`(${n2})`;
  const resto=(d.slice(0,m.index)+' '+d.slice(m.index+m[0].length)).replace(/\s+,/g,',').replace(/,\s*$/,'').replace(/\s{2,}/g,' ').trim();
  const kk=s=>norm(s).replace(/[^A-Z0-9]+/g,' ').trim(), med=(resto.match(MEDIDA_RE)||[]).join(' ');
  return p._tam={lab, n, nome:resto, med, k:kk(resto)+'|'+(p.ca||'')+'|'+norm(p.un||''), kr:kk(resto.replace(MEDIDA_RE,' '))+'|'+norm(p.un||'')}}
const famNome=p=>(tamMx(p)||{}).nome||p.descricao||'';
const lev=(a,b,max)=>{if(Math.abs(a.length-b.length)>max) return max+1; let v=Array.from({length:b.length+1},(_,i)=>i); for(let i=1;i<=a.length;i++){const w=[i]; let mn=i; for(let j=1;j<=b.length;j++){w[j]=Math.min(v[j]+1,w[j-1]+1,v[j-1]+(a[i-1]===b[j-1]?0:1)); mn=Math.min(mn,w[j])} if(mn>max) return max+1; v=w} return v[b.length]};
const FAMC=new WeakMap(); function famMedix(C){if(FAMC.has(C)) return FAMC.get(C); const G={}; C.forEach(p=>{const t=tamMx(p); if(t) (G[t.kr]=G[t.kr]||[]).push(p)});
  const fams=[], sol=[], dup=F=>{const o={}; return F.some(p=>{const t=tamMx(p), a=o[t.n]; o[t.n]=t.k; return a!=null&&a!==t.k})};
  Object.values(G).forEach(F=>{const cas=new Set(F.map(p=>p.ca).filter(Boolean)); let S=cas.size>1?Object.values(F.reduce((o,p)=>((o[p.ca||'']=o[p.ca||'']||[]).push(p),o),{})):[F];
    S=S.flatMap(f=>dup(f)?Object.values(f.reduce((o,p)=>((o[tamMx(p).k]=o[tamMx(p).k]||[]).push(p),o),{})):[f]);
    S.forEach(f=>f.length>1&&!dup(f)?fams.push(f):sol.push(...f))});
  /* tamanho solto com erro de digitação (1–2 letras) entra na família que não tem esse tamanho */
  sol.forEach(p=>{const t=tamMx(p), [k,u]=t.kr.split('|'); if(k.length<12) return; const F=fams.find(f=>{const t0=tamMx(f[0]), [k0,u0]=t0.kr.split('|'); return u0===u&&(!p.ca||!f[0].ca||f.some(x=>x.ca===p.ca))&&!f.some(x=>tamMx(x).n===t.n)&&lev(k,k0,2)<=2}); if(F) F.push(p)});
  const M=new Map(); fams.forEach(F=>{F.sort((a,b)=>tamMx(a).n-tamMx(b).n||String(a.cod).localeCompare(String(b.cod),'pt',{numeric:true})); F.forEach(p=>M.set(p.id,F))}); FAMC.set(C,M); return M}
/* o que difere este tamanho dos outros da família: {w: aviso em amarelo (medida/nome/CA fora do padrão), i: medida própria do tamanho (ex.: avental)} */
function famDif(F,p){const kn=x=>norm(tamMx(x).nome.replace(MEDIDA_RE,' ')).replace(/[^A-Z0-9]+/g,' ').trim(), meds=F.map(x=>tamMx(x).med), md=moda(meds), rep=meds.filter(m=>m===md).length>1, t=tamMx(p), w=[], i=[];
  if(t.med!==md&&rep){const tk=x=>String(x||'').split(/[\s\/]+/).filter(Boolean), a=tk(t.med), b=tk(md), da=a.filter(x=>!b.includes(x)), db=b.filter(x=>!a.includes(x)); w.push(`${(da.join(' ')||'sem medida').replace(/\./g,',')} (os outros: ${(db.join(' ')||'sem medida').replace(/\./g,',')})`)} else if(!rep&&t.med) i.push(t.med);
  if(kn(p)!==moda(F.map(kn))) w.push('descrição: '+t.nome);
  const ca=moda(F.map(x=>x.ca).filter(Boolean)); if(ca&&p.ca&&p.ca!==ca) w.push('CA '+p.ca);
  const ig=F.filter(x=>x!==p&&tamMx(x).n===t.n); if(ig.length) w.push('mesmo tamanho no código '+ig.map(x=>x.cod).join(', '));
  return {w:w.join(' · '), i:i.join(' · ')}}
const famBase=F=>{const meds=F.map(x=>tamMx(x).med), md=moda(meds); return meds.filter(m=>m===md).length>1?F.find(x=>tamMx(x).med===md):null};
/* nome do card: o da maioria; se cada tamanho tem medida própria (avental), o nome sai sem a medida */
const famTitulo=F=>{const b=famBase(F); return b?famNome(b):famNome(F[0]).replace(MEDIDA_RE,' ').replace(/\s{2,}/g,' ').trim()};
/* diferenças do modelo em destaque no card (cano curto/médio/longo, espessura, comprimento, acabamento, pó) */
const DIF_ACAB=[['FLOCAD','Flocada'],['LISA INTERNAMENTE','Lisa por dentro'],['ASPER','Palma áspera'],['RANHURAD','Ranhurada'],['TEXTURIZ','Texturizada'],['ANTIDERRAPANTE','Antiderrapante'],['FORRAD','Forrada'],['PIGMENT','Pigmentada'],['MICROESPUMA','Microespuma'],['TRICOTAD','Tricotada'],['VAQUETA','Vaqueta'],['NEOPRENE','Neoprene'],['AMBIDESTR','Ambidestra']];
function difMx(desc){const d=String(desc||''), N=norm(d); if(!/\bLUVA/.test(N)) return []; const out=[];
  const cm=N.match(/(\d+(?:[.,]\d+)?)\s*CM\b/), mm=N.match(/(\d+[.,]\d+)\s*MM\b/), c=cm?parseFloat(cm[1].replace(',','.')):null;
  let cano=(N.match(/CANO\s+(CURTO|MEDIO|LONGO)/)||[])[1]||(/\bLONG[AO]?\b|\bLONG\b/.test(N)?'LONGO':/\bCURT[AO]\b/.test(N)?'CURTO':null);
  const cl=cano?'':c?(c<30?'CURTO':c<=40?'MEDIO':'LONGO'):''; cano=cano||cl;
  if(cano) out.push(`Cano ${({CURTO:'curto',MEDIO:'médio',LONGO:'longo'})[cano]}${c?' · '+String(c).replace('.',',')+' cm':''}`); else if(c) out.push(String(c).replace('.',',')+' cm');
  if(mm) out.push(mm[1].replace('.',',')+' mm');
  DIF_ACAB.forEach(([k,l])=>{if(N.includes(k)) out.push(l)}); if(!N.includes('LISA INTERNAMENTE')&&/\bLISA\b/.test(N)) out.push('Lisa');
  if(/\bS\/\s*PO\b|SEM PO\b/.test(N)) out.push('Sem pó'); else if(/\bC\/\s*PO\b|COM PO\b/.test(N)) out.push('Com pó');
  return out}
const difTags=desc=>{const D=difMx(desc); return D.length?`<div class="tags">${D.map(x=>`<span class="tag" style="border-color:var(--accent);color:var(--accent);font-weight:600">${esc(x)}</span>`).join('')}</div>`:''};
function famUnid(list,M){const vis=new Set(), U=[]; list.forEach(p=>{const F=M.get(p.id); if(!F) return U.push(p); if(vis.has(F)) return; vis.add(F); U.push({fam:F})}); return U}
const EST={}; async function estoqueMedix(){if(EST.d) return EST.d; try{EST.d=(await fetch('/medix-luvas/estoque.json?'+Date.now()).then(r=>r.json())).d||{}}catch(e){EST.d={}} return EST.d}
const estTxt=(rep,cod,E)=>rep==='medix'&&E[cod]?(E[cod][0]==='S'?'<span class="ok">em estoque</span>':`<span class="bad">sem estoque${E[cod][1]?' · previsão '+esc(E[cod][1]):''}</span>`):rep==='sigma'&&SGS[cod]&&SGS[cod].it?`${nBR(SGS[cod].it.disp)} disp.`:'';
const fichaLink=p=>{const f=(FIC.d||{})[p.cod]; return p.ficha||(f&&f.ficha)||null}, siteLink=p=>(FIC.site||{})[p.cod]||((FIC.d||{})[p.cod]||{}).url||null;
/*FICHAS-INICIO*/
/* ficha técnica do produto: botão "📄 Ficha" ao lado do adicionar (catálogo de todas as fábricas e busca do orçamento).
   O gestor cadastra por link ou PDF (o PDF vai para arquivos/fichas/<rep>/), ligado ao código do produto (produtos.ficha).
   PDF enviado fica gravado como "arq:<caminho>" e abre com link assinado (no PDF do orçamento, link válido por 1 ano). */
const FICHA_ON=true; /* false = esconde os botões de ficha (volta ao que era) */
const FSIG={};
async function fichaUrl(l,longo){if(!l||!/^arq:/.test(l)) return l; const path=l.slice(4), k=path+(longo?'|L':''), c=FSIG[k]; if(c&&c.t>Date.now()) return c.u;
  const exp=longo?31536000:3600, tk=await token(); const r=await fetch(`${SB}/storage/v1/object/sign/arquivos/${path}`,{method:'POST',headers:{apikey:KEY,Authorization:'Bearer '+tk,'Content-Type':'application/json'},body:JSON.stringify({expiresIn:exp})}); if(!r.ok) throw new Error('Não consegui abrir a ficha ('+r.status+')');
  const j=await r.json(); const u=SB+'/storage/v1'+(j.signedURL||j.signedUrl); FSIG[k]={u,t:Date.now()+(exp-300)*1000}; return u}
function abrirFicha(l){if(!l) return; if(!/^arq:/.test(l)) return window.open(l,'_blank','noopener'); const w=window.open('about:blank','_blank'); fichaUrl(l).then(u=>{if(w&&!w.closed) w.location.href=u; else location.href=u}).catch(e=>{if(w) w.close(); toast(e.message)})}
/* links das fichas para o PDF do orçamento: {cod: url} (PDF enviado vira link assinado de 1 ano) */
async function fichasPdf(rows){await fichasDados().catch(()=>{}); const out={}; await Promise.all(rows.map(async r=>{const l=fichaLink(r.p); if(!l) return; try{out[r.p.cod]=await fichaUrl(l,true)}catch(e){}})); return out}
const fichaBtn=(p,ids)=>{if(!FICHA_ON||!p) return ''; const l=fichaLink(p), ges=ehGestor(), k=String(ids||p.id); if(!l&&!ges) return ''; return `<span class="row" data-ficw="${esc(k)}" style="gap:4px;flex-wrap:nowrap">${l?`<button class="chip" data-fic="${esc(l)}" title="Abrir a ficha técnica">📄 Ficha</button>`:''}${ges?`<button class="chip" data-ficed="${esc(k)}" data-ficrep="${esc(p.rep||'')}" title="${l?'Trocar a ficha técnica':'Cadastrar a ficha técnica (link ou PDF)'}" aria-label="${l?'Trocar a ficha técnica':'Cadastrar a ficha técnica'}">${l?'✎':'＋ Ficha'}</button>`:''}</span>`};
const ficSafe=x=>String(x||'').normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[^\w.-]+/g,'_').slice(0,80);
async function ficEnviar(rep,cod,f){if(!/pdf$/i.test(f.type||'')&&!/\.pdf$/i.test(f.name)) throw new Error(f.name+': envie em PDF'); if(f.size>25*1024*1024) throw new Error(f.name+': PDF maior que 25 MB');
  const path=`fichas/${ficSafe(rep)}/${ficSafe(cod)}-${Date.now()}.pdf`, tk=await token(); const r=await fetch(`${SB}/storage/v1/object/arquivos/${path}`,{method:'POST',headers:{apikey:KEY,Authorization:'Bearer '+tk,'Content-Type':'application/pdf','x-upsert':'true'},body:f}); if(!r.ok) throw new Error((await r.text()).slice(0,150)); return 'arq:'+path}
async function ficGravar(rep,ids,link){await api(`produtos?id=in.(${ids.join(',')})`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({ficha:link,atualizado_em:new Date().toISOString()})});
  [CAT[rep]||[]].flat().forEach(p=>{if(ids.includes(p.id)) p.ficha=link}); STALE.add('cat_'+rep);
  if(route==='prod'&&ids.includes(ctx.pid)){const i=document.querySelector('[data-pf="ficha"]'); if(i) i.value=link||''; const p=(CAT[rep]||[]).find(x=>x.id===ctx.pid); const b=document.querySelector('#ptec'); if(p&&b) tecFicha(b,rep,p)}}
const ficRedesenha=(rep,k)=>{const C=CAT[rep]||[]; const p=C.find(x=>x.id===+String(k).split(',')[0]); document.querySelectorAll(`[data-ficw="${CSS.escape(k)}"]`).forEach(el=>{el.outerHTML=fichaBtn(p,k)||'<span></span>'})};
async function fichaEditar(rep,k){const ids=String(k).split(',').map(Number).filter(Boolean); const C=CAT[rep]||await catalog(rep).catch(()=>[]); const Ps=ids.map(id=>C.find(p=>p.id===id)).filter(Boolean); if(!Ps.length) return toast('Produto não encontrado'); await fichasDados().catch(()=>{});
  const p=Ps[0], atual=fichaLink(p), deFab=atual&&!p.ficha; const ov=document.createElement('div'); ov.className='ov';
  ov.innerHTML=`<div class="sh grid"><b>📄 Ficha técnica · ${esc(Ps.length>1?Ps.map(x=>x.cod).join(', '):p.cod)}</b><div class="hint">${esc(String(p.descricao||'').slice(0,140))}</div>
   ${atual?`<div class="row" style="gap:8px"><span>Ficha atual:</span><button class="chip" data-fic="${esc(atual)}">📄 Abrir</button><span class="hint">${deFab?'automática (fichas do fabricante)':/^arq:/.test(atual)?'PDF enviado':'link'}</span></div>`:'<div class="hint">Este produto ainda não tem ficha técnica.</div>'}
   <label class="f">Link da ficha (site do fabricante, Google Drive…)<input id="ficL" type="url" inputmode="url" placeholder="https://…" value="${esc(p.ficha&&!/^arq:/.test(p.ficha)?p.ficha:'')}"></label>
   <label class="f">ou enviar o PDF<input id="ficF" type="file" accept="application/pdf,.pdf"></label>
   ${Ps.length>1?`<label class="row" style="gap:6px"><input type="checkbox" id="ficT" checked style="width:auto"> Usar a mesma ficha nos ${Ps.length} tamanhos</label>`:''}
   <p class="hint" style="margin:0">A ficha fica ligada ao código do produto: aparece no catálogo, na busca do orçamento e como link no PDF (se a opção “Link da ficha técnica” estiver ligada no PDF da representada). Para trocar, é só enviar outra.</p>
   <div class="row"><button class="btn" data-ok>Salvar</button>${p.ficha?'<button class="btn ghost" data-rm>Tirar a ficha</button>':''}<button class="btn ghost" data-x>Cancelar</button><span class="hint" id="ficSt"></span></div></div>`;
  document.body.appendChild(ov); const fecha=()=>ov.remove();
  ov.onclick=async e=>{const t=e.target; if(t===ov||t.closest('[data-x]')) return fecha(); const alvo=()=>Ps.length>1&&!ov.querySelector('#ficT').checked?[p.id]:Ps.map(x=>x.id);
    if(t.closest('[data-rm]')){if(!confirm('Tirar a ficha técnica deste produto?')) return; try{await ficGravar(rep,alvo(),null); toast('Ficha retirada'); fecha(); ficRedesenha(rep,k)}catch(err){toast('Erro: '+err.message)} return}
    if(!t.closest('[data-ok]')) return; const f=ov.querySelector('#ficF').files[0], url=ov.querySelector('#ficL').value.trim(); if(!f&&!url) return toast('Cole o link ou escolha o PDF'); if(!f&&!/^https?:\/\/\S+$/i.test(url)) return toast('O link precisa começar com http:// ou https://');
    t.disabled=true; const st=ov.querySelector('#ficSt'); try{st.textContent=f?'Enviando o PDF…':'Salvando…'; const link=f?await ficEnviar(rep,p.cod,f):url; await ficGravar(rep,alvo(),link); toast('Ficha técnica salva'); fecha(); ficRedesenha(rep,k)}catch(err){st.textContent=''; t.disabled=false; toast('Erro: '+err.message)}}}
/* várias fichas de uma vez (Produtos, gestor): PDFs com o código no nome do arquivo, ou lista "código; link" */
async function fichasLote(rep){const C=await catalog(rep).catch(()=>[]); const ov=document.createElement('div'); ov.className='ov'; const kn=x=>norm(String(x||'')).replace(/[^A-Z0-9]/g,'').replace(/^0+/,'');
  const idx={}; C.forEach(p=>{[p.cod,p.ref].forEach(c=>{const kk=kn(c); if(kk) (idx[kk]=idx[kk]||new Set()).add(p)})});
  const acha=nome=>{const base=String(nome).replace(/\.pdf$/i,''); const toks=base.split(/[^A-Za-z0-9.\-\/]+|\s+/).filter(Boolean); for(const tk of [base,...toks]){const s=idx[kn(tk)]; if(s) return [...s]} return []};
  ov.innerHTML=`<div class="sh grid"><b>📄 Fichas técnicas em lote · ${esc(repName(rep))}</b>
   <label class="f">PDFs (o nome do arquivo começa com o código ou a referência, ex.: <i>10356.pdf</i>, <i>50B26-BP ficha.pdf</i>)<input id="flF" type="file" accept="application/pdf,.pdf" multiple></label>
   <label class="f">ou cole uma lista: código; link (um por linha)<textarea id="flL" rows="4" placeholder="10356; https://site.com/ficha-10356.pdf\n50B26-BP; https://drive.google.com/…"></textarea></label>
   <button class="btn ghost sm" id="flV" style="justify-self:start">Conferir</button><div id="flR"></div>
   <div class="row"><button class="btn" id="flOk" disabled>Salvar fichas</button><button class="btn ghost" data-x>Fechar</button><span class="hint" id="flSt"></span></div></div>`;
  document.body.appendChild(ov); let J=[];
  const conferir=()=>{J=[]; [...ov.querySelector('#flF').files].forEach(f=>J.push({f,nome:f.name,ps:acha(f.name)})); ov.querySelector('#flL').value.split(/\n/).map(l=>l.split(/[;\t]/).map(x=>x.trim())).filter(a=>a[0]&&a[1]).forEach(([c,u])=>J.push({u,nome:c,ps:/^https?:\/\//i.test(u)?(idx[kn(c)]?[...idx[kn(c)]]:[]):[],bad:!/^https?:\/\//i.test(u)}));
    const ok=J.filter(j=>j.ps.length&&!j.bad); ov.querySelector('#flR').innerHTML=J.length?`<table class="t"><tr><th>Arquivo / código</th><th>Produtos</th></tr>${J.map(j=>`<tr><td>${esc(j.nome)}</td><td>${j.bad?'<span class="bad">link inválido</span>':j.ps.length?esc(j.ps.slice(0,6).map(p=>p.cod).join(', ')+(j.ps.length>6?' +'+(j.ps.length-6):'')):'<span class="warn">não achei o código</span>'}</td></tr>`).join('')}</table><p class="hint">${ok.length} de ${J.length} prontos. Os sem código não são salvos (renomeie o arquivo com o código).</p>`:'<p class="hint">Escolha os PDFs ou cole a lista.</p>'; ov.querySelector('#flOk').disabled=!ok.length};
  ov.querySelector('#flF').onchange=conferir; ov.onclick=async e=>{const t=e.target; if(t===ov||t.closest('[data-x]')) return ov.remove(); if(t.id==='flV') return conferir();
    if(t.id==='flOk'){const ok=J.filter(j=>j.ps.length&&!j.bad); t.disabled=true; const st=ov.querySelector('#flSt'); let n=0, er=[]; for(const j of ok){st.textContent=`Salvando ${++n} de ${ok.length}…`; try{const link=j.f?await ficEnviar(rep,j.ps[0].cod,j.f):j.u; await ficGravar(rep,j.ps.map(p=>p.id),link)}catch(err){er.push(j.nome+': '+err.message)}}
      st.textContent=''; toast(`${ok.length-er.length} ficha(s) salva(s)`+(er.length?`, ${er.length} com erro`:'')); if(er.length) ov.querySelector('#flR').innerHTML=`<p class="bad">${er.map(esc).join('<br>')}</p>`; else ov.remove()}}}
document.addEventListener('click',e=>{const f=e.target.closest&&e.target.closest('[data-fic]'); if(f){e.preventDefault(); e.stopPropagation(); return abrirFicha(f.dataset.fic)} const d=e.target.closest&&e.target.closest('[data-ficed]'); if(d){e.preventDefault(); e.stopPropagation(); fichaEditar(d.dataset.ficrep,d.dataset.ficed)}},true);
